/* 令和5年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.r05.committeeSessions.push(...[{"id":"r05-20230315-3","meetingId":"r05-c-budget","date":"2023年3月15日","dateIso":"2023-03-15","committee":"予算特別委員会","time":"午前１０時００分～午後 ６時００分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を174件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"澤田委員","kind":"質問・要望","question":"３３６ページ、公園管理費、３５５ページ、防災ラジオ関連経費についてお伺いします。先日要望させていただいた防災ラジオの件についてお聞きします。","respondent":"平原防災課長","answer":"書類のやり取りが二、三必要になる関係もありますので、防災課の窓口において直接取扱いをさせていただいているところです。今後、防災ラジオの普及を広く図っていくために、様々な工夫を考えてまいりたいと考えています。","id":"exchange-001"},{"speaker":"澤田委員","kind":"質問","question":"次に、３３６ページ、公園管理費についてお伺いいたします。品川区には２７２か所の区立公園がありますが、そのうちのバリアフリートイレの設置状況は、現在どのようになっていらっしゃるのか尋ねました。","respondent":"高梨公園課長","answer":"公園・児童遊園の中のトイレの数といたしましては、１２８か所のトイレがございまして、そのうち６８か所が、いわゆるだれでもトイレ、バリアフリートイレ、身障者用トイレという形になってあります。","id":"exchange-002"},{"speaker":"澤田委員","kind":"質問","question":"現在、トイレが１２８か所、バリアフリートイレが６８か所ということですけれども、まだ全然バリアフリートイレになっていないというか、まだまだだと思うのですが、今後どのように進めていかれるのか尋ねました。","respondent":"高梨公園課長","answer":"現在、共同の和式トイレが１基置いてあるようなトイレにおきましても、バリアフリートイレを１基設置するなどして進めているところです。直近におきましては、昨年１２月に開園いたしました旗六公園におきまして、バリアフリートイレ、１基のみですけれども、設置をしています。","id":"exchange-003"},{"speaker":"澤田委員","kind":"質問・要望","question":"ただいまバリアフリートイレの推進を要望いたしましたが、公園のトイレにＡＥＤを設置することはできないでしょうか。区としては、いかがお考えでしょうか示すよう求めました。","respondent":"高梨公園課長","answer":"しながわ水族館の中にも設置されてあります。無人の状況下での設置ということで、設置可能な箇所については、幅広く検討してまいりたいと考えています。","id":"exchange-004"},{"speaker":"澤田委員","kind":"質問・要望","question":"楽しみなのですが、Ｐａｒｋ－ＰＦＩ事業を行うには広さが足りない公園については、どのようにお考えでしょうか。そのような公園に、しながわ区民公園のサイクルセンターの脇にある小さな売店のような施設を整備することはいかがか尋ねました。","respondent":"高梨公園課長","answer":"広さ１万m2以上を１つの目安といたしまして、７つの公園を候補公園として、どのようなことができるのかといった内容について検討中です。売店を設置する折になりましたら、福祉団体が設置する自販機が公園内に幾つかありますので、まず物理的には可能なのかといったところです。","id":"exchange-005"},{"speaker":"澤田委員","kind":"質問・要望","question":"今お話しした子供の森公園ですけれども、現在、自転車置場がなく困っているというお声も多くいただいております。ラインを引くなどの形で自転車置場をつくっていただきたいとの要望もありますので、ぜひご検討していただきたいのですが、いかがか尋ねました。","respondent":"高梨公園課長","answer":"子どもたちのアイデアを公園の中に活かしながら改修を進めてまいりたいと考えています。子供の森公園、そういったところについても、利用者や周辺の方々等のお声も聞きながら計画してまいりたいと考えています。","id":"exchange-006"},{"speaker":"澤田委員","kind":"質問・要望","question":"最近、ぜひしっかりとした高さのあるフェンスをつくっていただきたいというご要望もありますので、そのようなことをご検討ほしいと求めました。ご意見を説明するよう求めました。","respondent":"高梨公園課長","answer":"費用をかけずに効果のある何か簡易的なといいますか、効果のあるようなネットの設置等ができないかといったところを、現在検討しています。","id":"exchange-007"},{"speaker":"澤田委員","kind":"質問","question":"改修工事を行う際に、ぜひレガシーとして恐竜を何らかの形で残していただくことはできないでしょうか。そのような計画などがあれば、お聞かせほしいと求めました。","respondent":"高梨公園課長","answer":"皆さんの意見を聞く中で、恐竜のモニュメントをどうするのかといったところは非常に重要なキーワードになると公園課としても考えているところです。しっかりと皆様方とも意見交換をしながら、恐竜のモニュメントをレガシーとしてつないでいきたいと思っているところです。","id":"exchange-008"},{"speaker":"澤田委員","kind":"質問・要望","question":"ぜひ区民の皆様の様々なご意見をお聞きしながら、そして周りの区民の皆様が楽しめる、笑顔になれる公園をつくっていただけたらと思います。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"新妻委員","kind":"質問・要望","question":"３月１８日より相鉄線の乗り入れが開始されるということで、この乗り入れに対して、何か事業者のほうで対策されているのか伺います。この件に関して、時間帯の拡充等を要望するお考えがあるのか、伺わせていただきます。","respondent":"鈴木都市計画課長","answer":"まずはスタートに当たって、需要がどの程度見込めるかというところがまだ判明していない中で、まずは日中のみのスタートとお聞きしています。ご指摘いただいた相鉄線の乗り入れ開始、あるいは武蔵小山でも、まちづくりがこれからも進んでいく。","id":"exchange-010"},{"speaker":"新妻委員","kind":"質問・要望","question":"事務事業概要で令和３年度の実績、あっ旋決定者数は３７名、協力金の支払件数は２６件と確認いたしました。次に、令和４年度の年度途中でありますけれども、この実績を、高齢者、ひとり親、障害者、低所得者、それぞれお伺いいたします。","respondent":"竹田住宅課長","answer":"障害者が１、低所得者が６８で、合計１２１となっています。身内の方と同居することになった等々があります。","id":"exchange-011"},{"speaker":"新妻委員","kind":"質問・要望","question":"ご協力をいただきながら、庁舎内において住宅相談会のようなものをぜひ開催していただきたいと要望いたしますが、見解を伺います。見解を伺います。","respondent":"竹田住宅課長","answer":"庁舎内で相談会を開催し、１回３時間の予約制で、年２回ぐらい行うことを想定した予算を計上しています。住宅をお探しの区民の方にとって、見やすい、分かりやすいものに工夫していきたいと考えております。","id":"exchange-012"},{"speaker":"新妻委員","kind":"質問・要望","question":"もっと観光資源として使っていただきたい、目立つところにこの砲台を移設してはどうかという、それぞれについてお伺いいたします。階段を下りるところへの手すりの設置もしていただきたい、そういうようなお声も出ておりますので、この要望に対しての見解を伺います。","respondent":"高梨公園課長","answer":"浜川砲台の移設等につきましても、適切な位置に設置すべきというふうに考えてありますので、しっかりと協議を進めてまいりたいというふうに考えます。","id":"exchange-013"},{"speaker":"新妻委員","kind":"質問・要望","question":"それぞれいろいろな各関係各所との連携と、また調整が必要になってくると思いますけれども、ぜひ推進してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"安藤委員","kind":"質問","question":"３３５ページ、３５９ページ、宿泊施設滞在費助成について伺います。伺いますけれども、これは何の目的で行う検討か、調査をするのか、伺いたいと思います。","respondent":"大石木密整備推進課長","answer":"（仮称）整備地域不燃化加速事業活用検討業務委託についてのお問合せです。土地利用状況がどうなのかといった、そういった基礎的な調査を行う目的で、１地区４００万円を計上させていただいているところです。","id":"exchange-015"},{"speaker":"安藤委員","kind":"質問・要望","question":"一方、３本の特定整備路線は、計８８３億円の事業費、立ち退きを求められる建物棟数は、計９５２棟に上ります。伺いますけれども、早期に災害に強いまちをつくっていただきたいが、いかがか尋ねました。","respondent":"鈴木都市計画課長","answer":"建物の不燃化を図っていくことは非常に大きい取組の１つで、実際、区のほうでも非常に力を入れて取り組んでいるところです。区としましては、都と連携して、特定整備路線に合わせた沿道の不燃化、耐震化を引き続き鋭意取り組んでいきたいところです。","id":"exchange-016"},{"speaker":"安藤委員","kind":"質問・要望","question":"私は、住民の犠牲を生み出すことなく安価に早期に災害に強いまちをつくっていただきたいと求めました。再度伺います。","respondent":"鈴木都市計画課長","answer":"繰り返しになりますが、正に建物の不燃化は非常に効果のある取組の１つというところで、今後も力を入れていくことに変わりはございません。こうした取組を今後も力強く推し進めてまいります。","id":"exchange-017"},{"speaker":"安藤委員","kind":"質問","question":"大崎駅北口自由通路整備計画追加検討等委託ですけれども、委託先はどこでしょうか。大崎駅東口第２地区、今、準備組合段階の大崎駅西口駅前地区にもつながるものを検討しているのか伺います。","respondent":"多並都市開発課長","answer":"この通路につきましては、大崎駅の混雑を緩和するために、以前より、ＪＲ東日本と協議をしながら、その具体策について検討してきたところです。具体的な位置については、まだ検討中です。","id":"exchange-018"},{"speaker":"安藤委員","kind":"質問","question":"なのに、その事業化を前提にして通路を整備するというのは少しおかしいのではないでしょうか。いかがか尋ねました。","respondent":"多並都市開発課長","answer":"北口の自由通路につきましては、今、冒頭にもご説明させていただきましたが、混雑の緩和を目的として、その方策の１つとして、今、検討しています。","id":"exchange-019"},{"speaker":"安藤委員","kind":"質問","question":"西口駅前地区についても伺っていきますけれども、３月２２日に、共用部分の調査を実施しますとのお知らせが入りました。かつ、都道府県知事から許可を受けているのでしょうか、受けていないのでしょうか、伺いたいと思います。","respondent":"多並都市開発課長","answer":"この準備組合は法令に基づかず、任意の組織ということで、皆さんで検討されている形です。その中でご検討いただいて、今現在進めているということですので、マンションの方々にご了解いただきながら進んでいる。","id":"exchange-020"},{"speaker":"安藤委員","kind":"質問・要望","question":"区から再開発準備組合に聞いていただいて、承諾も都知事ですよね。承諾も許可もないのであれば、実施を行わないように求めてほしいのですけれども、いかがか尋ねました。","respondent":"多並都市開発課長","answer":"繰り返しになりますが、今回の調査は、準備組合が準備組合の皆さんで確認して任意で行っている調査になりますので、皆さんで行うということですので、都知事もしくは行政が関わる調査ではないというふうに区としては認識しています。","id":"exchange-021"},{"speaker":"安藤委員","kind":"質問・要望","question":"これは納得いかないです。法律に関わることを見過ごすわけにいかない、きちんと指導してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"},{"speaker":"松永委員","kind":"質問","question":"３３７ページの公園・児童遊園費全般、あと３４１ページの公衆便所費全般、３４１ページのしながわ水族館運営費について伺いたいと思います。これはなぜか尋ねました。","respondent":"工藤交通安全担当課長","answer":"区の職員の手当が低くなればなるほど、それだけ安価で区民に安い保険をご案内できるといったところから、２か月の期間を設けてあります。なお、加入率ですけれども、令和４年度は３,１９４人ということで、前年比プラス２２件です。","id":"exchange-023"},{"speaker":"松永委員","kind":"質問・要望","question":"罰則はないのですが、この保険内容もそれで変わってくるのかどうか、併せて伺いたいと思います。ほかの区は、ヘルメットを買ったときに２,０００円割引ということで予算が組まれているのですが、品川区にはこうした割引制度はあるのか尋ねました。","respondent":"工藤交通安全担当課長","answer":"委員ご説明のとおり、４月１日から、ヘルメットの着用努力義務化が行われます。自分の命を守るという認識を持ってご自身でご用意いただくべきものと考えておりますので、啓発を進めてまいりたいと、このように思っております。","id":"exchange-024"},{"speaker":"松永委員","kind":"質問・要望","question":"だから、少し分かりづらいという声も伺っております。ぜひ高齢者の方々に対しても、こうした講習会をしていただきたいと考えていますが、いかがか尋ねました。","respondent":"工藤交通安全担当課長","answer":"ただ、ただいま徐々にコロナの影響も薄くなり、警察と協力して、小学校、中学校、そして高齢者に対して講習会を実施し始めているところです。併せまして、ヘルメットの着用義務化、こちらも指導をしていますので、引き続き、交通ルールの周知に取り組んでまいりたいと思います。","id":"exchange-025"},{"speaker":"松永委員","kind":"質問・要望","question":"ああという感じでどこかへ行ってしまうという感じでございまして、特に大森海岸など、国道沿いには駐輪場をつくっては駄目なのですか。こうした状況をぜひ改善していただきたいと思いまして、せっかくならきれいに並べていただいて、そういった駐輪場の設置はどうなのか説明を求めました。","respondent":"工藤交通安全担当課長","answer":"区としましては、駐輪場の整備を国、東京都も含めまして要請していますが、いまだ整備に至っていないという状況です。撤去活動を行いまして、違法駐輪が慢性化しないように努めているところですけれども、引き続き活動に取り組んでまいりたいと考えています。","id":"exchange-026"},{"speaker":"松永委員","kind":"質問・要望","question":"そういうものを直してほしいという声も伺っておりますが、確認させていただいたら、約２２か所あるのです。その２２か所ある中で、屋根に、上にネットをつけているところはどのくらいあるのでしょうか、伺います。","respondent":"高梨公園課長","answer":"様々な理由があって、安全基準等も厳しくなっているところで、遊具、また新しいものが設置できないというような事情もあります。はベンチが欲しい、様々な要望がありますので、皆様の声を聞きながら努めてまいりたいというふうに考えてあります。","id":"exchange-027"},{"speaker":"松永委員","kind":"質問・要望","question":"そうした方も含めまして、ぜひ屋根というか、そうしたところも含めて対策をとってほしいと求めました。どこの学校かは分かりませんけれども、ぜひそうした注意喚起もしていただきたいと思うのですが、最後にご意見を説明するよう求めました。","respondent":"高梨公園課長","answer":"公園課のほうにも情報が入っているところで、この間、バットの使用禁止等の注意喚起を行っているところです。ネットをかけると、まずはしっかりと注意啓発を繰り返し行って、しっかりと状況を注視してまいりたいというふうに考えてあります。","id":"exchange-028"},{"speaker":"江野下委員","kind":"質問","question":"先日、広告費など、他区の状況も質問に出ましたが、ご答弁では、それぞれ区の特性があると伺いました。区としては、ルートごとにどのような特性があるのか、お伺いします。","respondent":"鈴木都市計画課長","answer":"その中で導入効果が一番高いという調査結果が出た大井ルートから、現在、試行運行を開始しています。こちらもＪＲの駅を結ぶルートにはなってありますが、より地域の方がお使いになるというようなところでの特性が出ているのかなです。","id":"exchange-029"},{"speaker":"江野下委員","kind":"質問","question":"荏原ルートも候補にありますので、そちらの特性もお伺いします。","respondent":"鈴木都市計画課長","answer":"３ルート目の荏原ルートですが、武蔵小山駅から循環して、昭和医大を通ってまた武蔵小山駅に戻っていくというルートです。途中、こうしたより広域のご利用のお客様が見込まれるルートになっておりますが、より地域の方に乗っていただけるような特性があるのかなです。","id":"exchange-030"},{"speaker":"江野下委員","kind":"質問・要望","question":"地域の方の利便性がさらによくなることを要望いたします。広告ですけれども、車内の吊り広告に医院が１件、放送では、これも医院が１件でしたが、医療関係に限定されているのか尋ねました。","respondent":"鈴木都市計画課長","answer":"今、実績としましては、バスでの車内広告というところで２件の実績がありますが、どちらも病院関係です。","id":"exchange-031"},{"speaker":"江野下委員","kind":"質問・要望","question":"補助２６号線の東急バスの開通についてご質問がありましたが、地域からも要望していたので、とても便利になったと喜びの声を多く聞きます。こちらは、バスの本数がやはり１時間に１本などとお伺いしましたが、停留所の数などもお知らせいただけますか尋ねました。","respondent":"鈴木都市計画課長","answer":"今回新たに民間バスルートが運行されました停留所ですが、武蔵小山、あるいは小山三丁目は既存のバス停ですが、その後、平塚橋ですとか、下神明駅入口、そうしたところが新設のバス停として設置されているというような状況です。","id":"exchange-032"},{"speaker":"江野下委員","kind":"質問・要望","question":"これは事業者のお考えということで、しなバスは２０分に１本の運行ですので、拡充検討を要望したいと思います。本格導入から見直し、廃止を含む判断をするには、収支率５０％以上とすると先日のご答弁で、現状は５０％以上は超えていると伺いました。","respondent":"鈴木都市計画課長","answer":"民間バスと同じ２２０円で実施していますが、今、５０％を超える利用状況につながっているのかです。それから、沿線商店街と連携した、そうした地域振興にもつながるような取組を地域の方と一緒に考えて取り組んでまいりたいところです。","id":"exchange-033"},{"speaker":"江野下委員","kind":"質問・要望","question":"様々なご答弁をありがとうございました。データを積み重ねて、地域に愛されるしなバスの運行を要望して質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-034"},{"speaker":"いながき委員","kind":"質問","question":"再開発組合でしょうか。それは今ある小山三丁目第２地区市街地再開発準備組合が、その団体に補助金がいくということでしょうか、お尋ねいたします。","respondent":"多並都市開発課長","answer":"再開発組合を令和５年度中に設立する予定ということで聞いてありますので、組合設立後にその組合に補助するための費用ということで計上しています。これにつきまして、現在は準備組合ですけれども、もう一度繰り返しますけれども、組合を設立した後に組合に対して補助するです。","id":"exchange-035"},{"speaker":"いながき委員","kind":"確認","question":"品川区から６億円超もの巨額の支援を受けるということに、問題、差し障りはないのでしょうか。これまでの準備組合の体質が改善されたのか、品川区はそれらをどのように確認されるのでしょうか、見解を伺います。","respondent":"多並都市開発課長","answer":"これまでの経過も含めてご説明いたしますと、都市計画決定という手続を進めてまいりました。準備組合、民間の計画として進められるよう支援しながら、ともに進めていきたいと思っているところです。","id":"exchange-036"},{"speaker":"いながき委員","kind":"意見","question":"準備組合が自らつくった規約をきちんと守っていなかったということがこれまでありました。そうしたことが今後は起こらないというような形をどうやって品川区は担保し、それを東京都は認可するのか、その点をお尋ねいたしますとの意見を述べました。","respondent":"多並都市開発課長","answer":"今、委員からご説明がありましたように、その準備組合の皆さんで決めた規約に基づいて公開することになります。今後につきましても、やはり民間の事業の情報ですので、そのように進めていただきたいと思っているところです。","id":"exchange-037"},{"speaker":"いながき委員","kind":"質問・要望","question":"その際にはどういったアドバイスをされていますでしょうか。本来ならば、どこに連絡したらいいのかということもお伝えしてほしいと思いますが、それを示すよう求めました。","respondent":"多並都市開発課長","answer":"まず、計画を都市計画手続の中で皆様にお示ししながら、これまでご説明して進めてきたところです。令和４年に工事説明会を事業者が行っており、その中でもご説明しながら今行っているというところでございまして、説明会があって。","id":"exchange-038"},{"speaker":"いながき委員","kind":"質問","question":"すみません、今、合意がされているというお話だったのですけれども、それはどことどこで合意がされているのかお尋ねします。そうなると、今おっしゃったような狭隘道路が課題の１つであったという部分に関しては、見解を伺います。","respondent":"多並都市開発課長、溝口土木管理課長","answer":"は合意についてですけれども、これは、先ほどのご説明の中で、都市計画決定手続の中で進めてきたということを説明した内容です。所管がご説明しますけれども、先ほどもご説明しましたが… 道路区域を変更しているところになりますので、手続上は道路区域の変更という形をとっておりますので、議会等にはかけずに進めてきている。","id":"exchange-039"},{"speaker":"いながき委員","kind":"質問","question":"区域の変更ということは、この土地に関しては、まだ品川区の土地ということでよろしいのでしょうか。その廃道となった部分、お願いします。","respondent":"多並都市開発課長","answer":"権利変換という計画の中で行っていきますので、区道ですので、最終的には品川区が所有するということになるものです。","id":"exchange-040"},{"speaker":"須貝委員","kind":"質問","question":"１つ申し上げておきますが、この共済制度は保険業法に該当しないので、ダブル加入しても問題ない、可能である、これをお聞きしております。今の２点について説明を求めました。","respondent":"平原防災課長","answer":"品川区におきましては、これは以前お答えさせていただきましたとおり、しっかりとこちらは区民に向けて周知啓発を進めてまいりたいと考えています。","id":"exchange-041"},{"speaker":"須貝委員","kind":"質問","question":"だって区は、個人財産に対して支援できないではないですか。でも、財産がなかったらどうするのか尋ねました。","respondent":"平原防災課長","answer":"先ほどもご説明させていただきましたとおり、それだけに関わらず、しっかりと今後は周知してまいりたいというふうに考えてあります。再建のときの財産の支援といったところですが、それも生活再建の一端の中で、地震保険以外にも災害救助法に基づく様々な支援もありますので。","id":"exchange-042"},{"speaker":"須貝委員","kind":"確認","question":"それはそれでいただいて、こちらはこちらで、やはり皆さん、自己防衛をする仕組みを考えてあげるべきではないでしょうか。どうするのだというと、安全確認をした上で、これについてもご見解を説明するよう求めました。","respondent":"平原防災課長","answer":"４０％というような形で再計算させていただいたところです。ローリングストックなどを活用して在宅避難の準備を、今、区でも強く推奨しています。","id":"exchange-043"},{"speaker":"須貝委員","kind":"意見","question":"そういうことなので、皆さん、やはり避難しなければいけないと考えています。区としてどのようにお考えなのか、もっとしっかり強く皆さんにアピールしてほしいと思うのですが、ご見解を説明するよう求めました。","respondent":"平原防災課長","answer":"しっかりと進めていく必要がある分野だというふうに考えてありますが、在宅避難に対する支援制度についてもしっかりと区のほうで準備する必要がありますので、在宅避難を推奨してまいりたいというふうに考えてあります。","id":"exchange-044"},{"speaker":"須貝委員","kind":"確認","question":"そこで少し在宅避難についてお聞かせ願いたいのですが、自分の建物は安全なのだ、どうやってこれを確認するのですか。その辺について、何か指導ならびにそういう基準はしっかり設けているのでしょうか、説明を求めました。","respondent":"平原防災課長","answer":"どのぐらいの被害を受けたかということを、まずご自身で見ていただく、そういったところからスタートするものです。そのとき、状況によって異なってきますけれども、区の持っている様々な情報発信手段で随時お知らせしていくことを考えてあります。","id":"exchange-045"},{"speaker":"須貝委員","kind":"質問・要望","question":"これをなぜ品川区、もっと積極的にそういう診断をしないのでしょうか。いや、避難路はここです、そこは本当に絶対安全な道路なのですか、説明を求めました。","respondent":"長尾建築課長","answer":"は耐震改修に向けての支援は、今までも続けておりますし、都と連携して建築課のほうで支援してきているところです。さらに支援をしていこうということで、また別のメニューで支援もしておりまして、幅広く支援してきているところです。","id":"exchange-046"},{"speaker":"須貝委員","kind":"質問・要望","question":"やはり調べなければいけないのではないですか。その辺について、もう一度お聞かせいただきたいのですが、こういうきちんとしたデータをつくるべきではないかと思うのですが、説明を求めました。","respondent":"長尾建築課長","answer":"令和２年度に改定いたしました耐震改修促進計画、品川区の計画の中でも算出しております。その中で特に特定緊急輸送道路は重要性も高いということで、さらに細かく数値も出しているところです。","id":"exchange-047"},{"speaker":"須貝委員","kind":"質問・要望","question":"緊急輸送道路ではなくて、実際、区民が避難するとか、そういうこともあるし、ふだん、日常小さなお子さんからご高齢者まで生活しているのですから、しっかり対応してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-048"},{"speaker":"せらく委員","kind":"質問","question":"当区は、マンション、オフィスビル、商業施設が多く建つエリアもあり、地震発生時のエレベーターの動作や対策について伺っていきたいと思います。エレベーター内に備蓄ボックスが設置されていることも多く見かけますが、そういった備えについて、品川区での取組を伺います。","respondent":"平原防災課長","answer":"いわゆる災害が発生したときに対応できるボックス、こちらの支援といいましょうか、あっ旋を行っていることが現状あります。そういったところが１点と、もう１つ、その対象となるようなマンションにご説明させていただいているところです。","id":"exchange-049"},{"speaker":"せらく委員","kind":"質問","question":"１時間の閉じ込めでも精神的、身体的にダメージがあり、回復にも時間がかかったそうです。そこで、閉じ込めを想定したエレベーターのドアを開ける避難訓練や講習といった体験をする場をつくれないでしょうか、伺います。","respondent":"平原防災課長","answer":"先ほどご説明させていただきましたマンション防災アドバイザーの支援の内容の中には、マンションにおける防災訓練の実施が含まれてあります。","id":"exchange-050"},{"speaker":"せらく委員","kind":"質問","question":"人が乗っているエレベーターということですが、その判断の判定は、非常ボタンの押下になるのでしょうか。非常ボタンの作動について、停電時非常用電源の作動も関係あると思いますが、非常ボタンの通知は正常にされるのでしょうか、伺います。","respondent":"平原防災課長","answer":"先ほどご説明させていただきましたエレベーターの保安基準について定めております建築基準法等の法令におきましては、そういった電源が確保されているものということを前提に、人が乗っているということをお知らせすることを今考えているところです。","id":"exchange-051"},{"speaker":"せらく委員","kind":"質問","question":"次に、空き家について伺います。当区でも対策事業がありますが、今回の予算にあります空き家等対策計画改定について、どのような見直しが行われたのか尋ねました。","respondent":"竹田住宅課長","answer":"５年が経過し、管理不全土地・建物の管理制度の創設などの法改正や、協定による民間事業者との連携が行われております。それらを踏まえて、計画の見直しを令和５年度にやっていきたいと考えております。","id":"exchange-052"},{"speaker":"せらく委員","kind":"提案","question":"区で管理をさせてもらえるような取組も柔軟にご検討いただけたら、空き家を発生させないようにするためにもいかがでしょうかというご提案になります。こういった住宅をお持ちの方へのアプローチはどのようにお考えか尋ねました。","respondent":"竹田住宅課長","answer":"品川区として対応できるところもあれば、修繕、協定している民間事業者等をご紹介して対応しています。地域交流や子どもの学習支援、改築費の３分の２、そういった仕組みを有効に活用して空き家対策を進めていきたいと考えております。","id":"exchange-053"},{"speaker":"せお委員","kind":"質問","question":"３３９ページ、３２９ページ、目黒駅のエレベーターについてお伺いします。この２つのコンセプトの違いがありましたら、説明を求めました。","respondent":"高梨公園課長","answer":"今、ご案内ありました２つの事業の違いといったところですが、公園整備に活かしていく改修工事をメインとして記載をしています。みんなに愛される公園づくりにつきましては、それ以外のいわゆる通常の公園改修工事について記載をさせていただいたところです。","id":"exchange-054"},{"speaker":"せお委員","kind":"確認","question":"私の質問で、今後の公園改修の中で、そのアイデアを活かして取り入れていきたいと答弁されています。両方とも以前のワークショップの際に取り入れ切れなかったアイデアを活かして整備するという理解なのでしょうか、確認したいと求めました。","respondent":"高梨公園課長","answer":"令和５年度予算につきましては、いただいたアイデアの中から公園に合った遊具を選定いたしまして設置していきたいというふうに考えているところです。もう１つ、昭和４５年の開園当時、子供の森公園だけでワークショップ等を開いたらどうかといったところを現在検討しています。","id":"exchange-055"},{"speaker":"せお委員","kind":"質問・要望","question":"ですから、改修することを知らなかった、要望を聞いてほしいなどご意見を伺っていました。そこで、その西五反田公園の際の皆様からのご意見は、どのように設計に反映されますか尋ねました。","respondent":"高梨公園課長","answer":"西五反田第二保育園ほか、教育施設にも赴いて、学校の先生等にもご協力いただいてアンケート等を実施してきたところです。安全管理上、類似する遊具を現在探しておりまして、同じような遊具を設置できたらなというふうに考えているところです。","id":"exchange-056"},{"speaker":"せお委員","kind":"質問・要望","question":"児童相談所と公園が一体となったイメージでつくってほしいと思っていて、ワークショップも行ってほしいのですけれども、ある程度。あそこの公園が一体となってみんなが明るく楽しく過ごせるような公園にしていただきたいと思うのですが、そこら辺、見解を説明するよう求めました。","respondent":"高梨公園課長","answer":"子供の森公園につきましては、隣接用地での下水道工事の完成に合わせて、令和７年度からの全体改修工事の実施を計画しております。楽しい雰囲気になるような設えを、設計、計画の中でしっかりと考えていきたいというふうに考えてあります。","id":"exchange-057"},{"speaker":"せお委員","kind":"質問","question":"要は、設置できるかどうかという検討の費用だと伺っています。来年度、記載がなかったので、現状、どういったところなのかＪＲから区に届いていますでしょうか、説明を求めました。","respondent":"鈴木都市計画課長","answer":"工事予定については、来年度、再来年度、２か年をかけて行う。東急とも協議を行っていまして、令和６年度に工事費について助成をするというような予定です。","id":"exchange-058"},{"speaker":"小芝委員","kind":"質問","question":"私からは、３５３ページの地域防災計画についてと、３３１ページ、コミュニティバスについて伺います。地域防災計画について伺います。","respondent":"平原防災課長","answer":"令和４年度、これまでの訓練により得られた成果や課題、そういったものの検証を行ってきたところです。早速、おおむね年度末を予定しておりますけれども、年明けぐらいのところの防災会議で決定に至ればというふうに今考えているところです。","id":"exchange-059"},{"speaker":"小芝委員","kind":"質問・要望","question":"そこでお聞きしますが、品川区が要配慮者を把握する仕組みについて教えてもらいたいと思います。全庁の横串を刺して、所管をまたいで把握されていると思いますが、その辺りを教えてほしいと求めました。","respondent":"平原防災課長","answer":"避難行動要支援者については、それらの方々の該当しているところを各所管で把握している数字を防災課で集めて一括した名簿を作成しています。そのような方々を、まず、避難行動要支援者の母数として把握し、今後の支援に活かしています。","id":"exchange-060"},{"speaker":"小芝委員","kind":"質問","question":"今、名簿をつくられているといった答弁がございました。２つの種類の名簿があると認識しておりますが、その場合は、その認識で正しいのかどうかも含めて教えてほしいと求めました。","respondent":"平原防災課長","answer":"避難行動要支援者の名簿についての有事における提供ですけれども、災害時については、本人同意不要で提供することができるとなっております。避難支援に関係する者という形になっておりますので、その災害の発生状況に応じて範囲を特定していくようなことになるかと思います。","id":"exchange-061"},{"speaker":"小芝委員","kind":"質問・要望","question":"そういうところでは、区として人的に町会を災害時にフォローできるように努めていただきたいと考えますが、どのようにお考えか。既にそういった取組、フォローできるような取組として何かありましたら、教えてほしいと求めました。","respondent":"平原防災課長","answer":"避難行動要支援者の支援について、具体的に誰が当たるのかというのは、私どもでも一定の課題とさせていただいているところです。そういう方々を中心に名簿を作成した上で、具体的な避難支援者が誰かといったところを今後特定していく必要があるというふうに考えているところです。","id":"exchange-062"},{"speaker":"小芝委員","kind":"提案","question":"１つ提案といいますか、そういった取組で治安の回復が図られたとか、そういったことが全国的に展開されてきた歴史があります。地域のコミュニティの危機管理の力が格段に上がると考えますが、その辺り、どのようにお考えか尋ねました。","respondent":"平原防災課長","answer":"災害時における避難行動要支援者の避難支援に当たる方につきましては、どのような方に呼びかけていくか、こういったところについてはしっかりと考えてまいりたいというふうに思ってあります。","id":"exchange-063"},{"speaker":"小芝委員","kind":"質問","question":"もう既に５０％は超えているということですので、１つのハードルは超えていると思います。これまで品川区が行ってきました宣伝の取組について教えてほしいと求めました。","respondent":"鈴木都市計画課長","answer":"それから運行ルート、運賃等について、直接届く周知を行ってきたところです。","id":"exchange-064"},{"speaker":"小芝委員","kind":"質問","question":"私も何度か、一般質問とか予算特別委員会などで取り上げさせてもらいました。この協議会の構成はどのような形で構成されていくのか、その協議会の在り方、意義について教えてほしいと求めました。","respondent":"鈴木都市計画課長","answer":"コミュニティバス、３月末から運行を開始し、１０月にダイヤ改正を行ってあります。長くコミュニティバスを継続し運行していけるように、この連絡会を立ち上げるものです。","id":"exchange-065"},{"speaker":"小芝委員","kind":"質問・要望","question":"それで、この宣伝もそうですけれども、昨年の１１月から１２月にかけてアンケートが行われたと。そこに入れ込んで相乗効果を生んでほしいと求めましたが、その辺り、何かお考えがありましたら教えてほしいと求めました。","respondent":"鈴木都市計画課長","answer":"まず現状のままで試行を実施していくですが、沿線のルートだけではなくて、地域資源もしっかりＰＲしていきたいです。","id":"exchange-066"},{"speaker":"あくつ委員","kind":"質問・要望","question":"ここから大きく３点伺ってまいります。そして、この火災時の弔慰金・見舞金はホームページに載っているのですが、来年度、周知はどのように行っていくのか、まずお伺いします。","respondent":"五十嵐災害対策担当課長","answer":"２点目、どのような形で宿泊施設と連携していくかというようなお話ですけれども、協定ベースで進めていきたいというふうに考えてあります。３点目、運用開始以降の周知方法ですけれども、ホームページ等でお知らせしていきたいと考えております。","id":"exchange-067"},{"speaker":"あくつ委員","kind":"質問","question":"２点目に伺います。その宿泊費１万円は自腹で最初は出して立て替えてもらえるのかとか、その火災現場に防災課の職員が駆けつけた後の利用の手順、簡潔に説明を求めました。","respondent":"五十嵐災害対策担当課長","answer":"火災発生時の宿泊助成を受ける方法についてのご質問だと思います。さらに、宿泊費用に関しては、火災罹災者が払うべき宿泊費用を区が肩代わりするというような内容のものとなっています。","id":"exchange-068"},{"speaker":"あくつ委員","kind":"質問・要望","question":"都営住宅などでは、住宅を７割以上焼失したとか滅失したものでなければ入居できないとか、非常にハードルが高い制度です。消防活動による水をかぶった場合、こういった方をぜひ対象にしていただきたいと思うのですけれども、この点について対象の範囲を説明するよう求めました。","respondent":"五十嵐災害対策担当課長","answer":"助成制度を受けられる範囲のお話ですけれども、もちろん火元であろうと類焼であろうと、一定の焼損程度があれば、この助成は受けられるものです。さらに、水損についても、その自宅での居住が継続できないということであれば、この助成制度は受けられるものです。","id":"exchange-069"},{"speaker":"あくつ委員","kind":"質問・要望","question":"次に、京浜急行青物横丁駅前交差点の歩道橋について伺ってまいります。国の管理ですので、公明党の国会議員に依頼して、令和３年２月の国会の衆議院予算委員会で、地元の強い要望として取り上げていただきました。","respondent":"鈴木都市計画課長","answer":"１度目は、直近で今年の２月に第２回目が開かれまして、国がこの歩道橋について利用状況調査を行ってあります。こうした勉強会を踏まえての区の受け止めですが、非常に前向きにバリアフリー化に向けた具体的な検討を行っているというような受け止めです。","id":"exchange-070"},{"speaker":"あくつ委員","kind":"質問・要望","question":"私のもとにも愛犬家の区民の皆様を中心に、区内での、そして歩いて行ける範囲の公園でのドッグラン設置の要望を多くいただくようになりました。品川区内には大小２７２の区立公園があるということで、やはり工夫次第では、公園課のお考えを伺いたいと思います。","respondent":"高梨公園課長","answer":"２つの区分、現在の区立公園の中ではなかなか設置は難しいというふうに考えているところですが、公園課のほうにも。大きなドッグランを最終的に設置するというよりは、そういったことをはじめ様々な工夫につきまして、引き続き検討してまいりたいと考えています。","id":"exchange-071"},{"speaker":"あくつ委員","kind":"提案","question":"少し時間があるので、３４９ページ、マンション管理支援事業、管理計画認定制度について最後に伺います。前の２０２１年の第４回定例会の一般質問で、防災対策の取組や町会・自治会への加入促進、連携強化等の取組の基準を上乗せすることをご提案しました。","respondent":"竹田住宅課長","answer":"は年１回以上の定期的な防災訓練の実施が１つと、平成２８年に、町会および自治会の活動に協力するよう努めるものとする」と規定されております。その趣旨を生かすために、マンション管理計画認定基準には、地域との連絡調整を行う者を選任することという基準を設けております。","id":"exchange-072","title":"町会・自治会支援"},{"speaker":"あくつ委員","kind":"質問","question":"地域との連絡員、これは町会・自治会がマンションに行けば教えてもらえるのか、それとも地域センターに行けば教えてもらえるのか、説明を求めました。","respondent":"竹田住宅課長","answer":"お近くの地域センターでご紹介できるようになっております。","id":"exchange-073","title":"町会・自治会支援"},{"speaker":"あくつ委員","kind":"質問","question":"前からある制度ですけれども、これをぜひ活用していただいて、マンションと地域、町会・自治会との連携、これからますますスムーズにいくことを祈って私の質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-074","title":"町会・自治会支援"},{"speaker":"おくの委員","kind":"質問・要望","question":"昨年６月の建設委員会に出された資料には、八潮団地に住む方からは、八潮団地内で新駅への要望や期待を聞いたことはないと伺っております。具体的に、どこに住む区民の、どういう交通利便性の向上を考えて業務委託したのでしょうか、伺います。","respondent":"鈴木都市計画課長","answer":"初めに、中身的には、都市計画関係事務費の中に羽田空港アクセス線新駅可能性検討経費で２７０万円ほど予算を計上させていただいているところです。アクセス線実施の早期実現と、要望の可能性について検討していくというところで、検討しています。","id":"exchange-075"},{"speaker":"おくの委員","kind":"質問","question":"これ、昨年の６月補正で業務委託した報告が上がってきたのではないかと思うのですけれども、上がってきたのでしょうか、お伺いいたします。そして、課題は何だというふうに抽出されたのでしょうか、伺います。","respondent":"鈴木都市計画課長","answer":"それから、今年度補正を組んで検討を進めております内容ですが、報告書自体はまだ完成という形では上がってございません。設置の可能性があるその辺の土地利用ですとか、検討を進めていく中で、議会を含めて報告を行っていきたいです。","id":"exchange-076"},{"speaker":"おくの委員","kind":"質問・要望","question":"海外からの需要を呼び込むのか、あるいは国内の需要を呼び込むのか、報告書にはどのように書かれているのでしょうか。その点、お伺いいたします。","respondent":"鈴木都市計画課長","answer":"もう少し東京寄りになりますと、天王洲の近傍を通る、そうしたまずは土地利用の現状を調査の中で把握していくです。具体的な報告書は、まだこれからですので、先ほどご答弁したとおりです。","id":"exchange-077"},{"speaker":"おくの委員","kind":"質問","question":"少し分からないのですけれども、報告書がまだ完全には上がってきていないということか尋ねました。","respondent":"鈴木都市計画課長","answer":"上がってきていないです。","id":"exchange-078"},{"speaker":"おくの委員","kind":"質問","question":"私、この２つの再開発地域における地権者、そのうち再開発で建てられた超高層マンションに入居した方は何人なのでしょうかと伺いましたけれども。そして、なぜ非公開なのでしょうか、この点も伺います。","respondent":"多並都市開発課長","answer":"武蔵小山駅周辺の再開発についてのご質問にお答えいたします。区としては、細々追いかけて確認するようなことはしていないというところで、区として把握していないところです。","id":"exchange-079"},{"speaker":"おくの委員","kind":"質問","question":"従来どおりに住み続けたいという権利が保障されていないのは問題だとは思わないのでしょうか、伺います。私はそう思いますけれども、いかがか尋ねました。","respondent":"多並都市開発課長","answer":"皆さんでどういう建物にしようか、仕様にしようかと、建てた後の管理もどうしていこうかと考えながら計画を立てながら進められているところです。皆さんが、検討されて実現していく過程の事業ですので、しっかり皆さんでお話し合いできるように支援しながら今も進めていますし。","id":"exchange-080"},{"speaker":"西村委員","kind":"質問","question":"３１７ページ、３３１ページ、自転車利用全般について伺ってまいります。それらに関しましての現況を伺います。","respondent":"鈴木都市計画課長","answer":"それが従前まではなかなか戻らないという見通しも伺ってあります。そうした中で、自転車を利用する方が増えてきているというような実態もあります。","id":"exchange-081"},{"speaker":"西村委員","kind":"質問・要望","question":"尼崎市の方に実際に伺いますと、三ノ宮まで２０分なので、市も自転車活用に力を入れているとのことでした。自転車活用推進計画を立てる際に、このような事例もぜひ参考にしていただきたいと思うのですが、一言いただけますか。","respondent":"鈴木都市計画課長","answer":"この検討会の状況ですが、１回目が開かれて、今年の３月に２回目を行います。その中でアンケートも実施しまして、この２回目でお示しするわけですが、自転車対策としての側面が強いところもあります。","id":"exchange-082"},{"speaker":"西村委員","kind":"質問・要望","question":"どうしても課題解決がフォーカスされがちですけれども、これ以上、禁止看板を増やしたくないなという個人的な思いも強くあります。にぎわいですとか、健康で環境にやさしいまち品川モデルを目指してほしいと求めましたが、もう一度ご答弁をお願いいたします。","respondent":"鈴木都市計画課長","answer":"観光ですとか、健康ですとか、そうした側面も非常に利用促進には大きい視点なのかなです。そうした取組を、より小さい子どもにも興味を持って見ていただけるように、幅広い年齢層の方にしっかり届くように発信していきたいです。","id":"exchange-083"},{"speaker":"西村委員","kind":"質問・要望","question":"２点、伺います。２点、ご見解を説明するよう求めました。","respondent":"工藤交通安全担当課長","answer":"こちらは短時間利用の駐輪場設置というお話ですけれども、なかなかこちらも、そこら辺は慎重に検討を要するのかということで考えております。","id":"exchange-084"},{"speaker":"横山委員","kind":"提案","question":"２点目に、応急活動対策費、災害復旧費についてお伺いします。平成３０年より、トイレトレーラーについて提案、質問していますが、現在の検討状況を説明するよう求めました。","respondent":"多並都市開発課長、吉岡防災体制整備担当課長、平原防災課長","answer":"その中で、やはりまちづくりは地域の方が主役であり、その方々が円滑にまちづくりの検討ができるように、区がそれを支援する。再開発を進めるに当たっては… 非常に重要な課題と認識しておりまして、高齢者の方や障害者の方がお使いになれる自動ラップ式ポータブルトイレ、こういったものも配備しております。… さらには、妊産婦の場合、医療との連携が必要になっておりますので、こちらは問題意識を持ってございまして、今後進めてまいります。","id":"exchange-085"},{"speaker":"横山委員","kind":"提案","question":"４点目に、地域交通検討経費についてお伺いいたします。渋谷区、返礼品としてふるさと納税のメニューに加えることを検討していただきたいということを提案いたしますが、区のご見解をお伺いいたしますとの意見を述べました。","respondent":"栗原河川下水道課長、鈴木都市計画課長","answer":"東京都下水道局が実施しております立会川幹線の再構築についてお答えいたします。立会川幹線の老朽度調査を順次行いまして、その結果を踏まえて計画的に再構築を実施しており、これまでに約９００ｍを実施したと聞いております。やはりコミュニティバスが非常に長く地域に愛されて続いていくようなスキームで考えますと、収支のほうに反映できる制度がまず第一なのかなです。","id":"exchange-086"},{"speaker":"横山委員","kind":"質問・要望","question":"下水道の老朽化も心配のお声がありますので、引き続き区として把握していっていただきたい、要望もお願いしたいというふうに思います。少し時間がありませんが、５点目に、みんなに愛される公園づくり、荏原中央公園改修工事についてお伺いいたします。","respondent":"高梨公園課長","answer":"昭和４４年に開設いたしました１,１４０m2ほどの公園でございまして、それから３０年以上が経過しておりまして、施設の老朽化が進行しております。改修に当たりましては、近隣や利用者に加えて、小山小学校の全生徒からアンケート調査を行うなど、取り組んだところです。","id":"exchange-087"},{"speaker":"木村委員","kind":"質問","question":"予算書の３２５ページ、水辺利活用事業についてお伺いいたします。これからどのように活性化というか、にぎわいを取り戻すことができるのか、お考えを説明するよう求めました。","respondent":"栗原河川下水道課長","answer":"１０月、１１月に実施しました「らくらく舟旅通勤」を除きまして、コロナの影響が大きかった昨年度と比較しまして利用回数が増えているです。あるいは舟運活性化に向けまして、ハード整備、ソフト整備の面から取り組んでまいりたいと考えているところです。","id":"exchange-088"},{"speaker":"木村委員","kind":"質問・要望","question":"ＣＯ２排出削減など、積極的にＬＥＤ照明への転換を進めていくべきであると考えますけれども、そこでお伺いいたします。この２点、お伺いいたします。","respondent":"高梨公園課長","answer":"来年度、令和５年度につきましては、しながわ区民公園のプールおよびクラブハウス内の照明のＬＥＤ化工事を実施する予定です。今年度は、天王洲公園野球場のＡ・Ｂ面のナイター照明のＬＥＤ化を実施しています。","id":"exchange-089"},{"speaker":"木村委員","kind":"質問・要望","question":"このネーミングは募集でおつけになったのでしょうか、お聞かせください。私は気づかなかったのですけれども、いつ頃から設置をしていたのでしょうか、これも説明を求めました。","respondent":"高梨公園課長","answer":"東京２０２０大会で、お迎えをしたいというところで、この事業のネーミングをしたところです。ですので、きっかけとしては、東京２０２０大会、東京オリンピック・パラリンピック前の時期にネーミングしたといったところです。","id":"exchange-090"},{"speaker":"木村委員","kind":"質問","question":"これからもこのようなネーミングを使っていくお考えがあるのかどうか。私もそのうちの一人でありますけれども、ワンちゃん専用のトイレというか、そういうものはお考えにはならないか尋ねました。","respondent":"高梨公園課長","answer":"分かりやすいという前提のもと、興味を引くようなネーミングについては、これからも取り組んでいきたいというふうに考えてあります。","id":"exchange-091"},{"speaker":"木村委員","kind":"質問","question":"そして、３４９ページの空き家等対策事業についてお伺いいたします。その際には、庁内各部署や都税事務所などとの連携も必要と思いますけれども、現状はどのようになっているのでしょうか、説明を求めました。","respondent":"竹田住宅課長","answer":"区内の適正に管理されていない不適正管理状態の空き家は、１月末現在９６棟あると認識しております。それから、必要に応じて、庁内の他部署や都税事務所、水道局等からも情報提供を求めるなど、空き家の解決に向けて全力で取り組んでいるところです。","id":"exchange-092"},{"speaker":"芹澤委員","kind":"質問","question":"３１７ページの駅周辺等放置自転車対策事業、時間次第で３４９ページのマンション管理支援事業についてもお伺いします。品川区でもそこまでまだ見かけていないのですが、これ、今後の予定としてどうなっているのかをまず説明を求めました。","respondent":"栗原河川下水道課長","answer":"令和３年度に、地域の団体が主体となりまして、非動力船のイベントを実施しています。品川区といたしましては、引き続き、非動力船を含む水上アクティビティの充実に努めてまいりたいと考えております。","id":"exchange-093"},{"speaker":"芹澤委員","kind":"質問","question":"東品川だけではなくて、今お話しいただいた高さの問題が多分あるのだろうと思っていて、それを解決していく方向性でよろしいのでしょうか。今後、桟橋として増やしていく方向性がもしあれば、それも説明を求めました。","respondent":"栗原河川下水道課長","answer":"東海橋の船着場であるとか、そういった場所で地域の団体が主体となってＳＵＰやカヌーのイベントを実施したいというお話があった場合は。現時点では整備予定はございませんが、引き続き必要なハード整備については取り組んでまいりたいと考えております。","id":"exchange-094"},{"speaker":"芹澤委員","kind":"質問・要望","question":"普通の船と共存できる環境をつくっていくことが目標であると伺っていますが、やはり一緒にやると、なかなかいろいろな課題があると思っていますので。例えば、これ以上は船があまり行かないように整備をするということも１つの考え方なのかと思うのですが、ご見解を説明するよう求めました。","respondent":"栗原河川下水道課長","answer":"区といたしましては、引き続き地域の皆様のニーズ等もお話し合いしながら、必要な整備については検討してまいりたいと考えております。","id":"exchange-095"},{"speaker":"芹澤委員","kind":"意見","question":"例えばその２つを使って、何か品川区の水辺の活用の中で利活用していくということも、１つ方向性としてはありなのかなと思っています。不動前にもし土地がある場合に、そういった活用をご検討いただくのか、まずご見解を説明するよう求めました。","respondent":"栗原河川下水道課長","answer":"ＳＵＰやカヌーといった非動力船を実施するに適する場所なのかということを確認させていただければと思います。次年度から水辺利活用推進計画を作成する検討を進めることとしておりまして、整備として何ができるのか、しっかりと考えていきたいと思います。","id":"exchange-096"},{"speaker":"芹澤委員","kind":"質問","question":"駐輪場について改めて伺ってまいりますが、今の八潮のほうに１つでまとまるのであれば、今後はそういう方向性もありなのかと思っています。２３区の中でもそんなにないのではないかと思っているのですが、まず、何か差があるのかをまず説明を求めました。","respondent":"工藤交通安全担当課長","answer":"今現在、所有者が受け取りに来なかった自転車の返還率が、不動前は８４％と非常に高くなってあります。八潮北のほうは６５％ですので、その適地のめどが立っていない関係で、このまま進めさせていただければというふうに考えてあります。","id":"exchange-097"},{"speaker":"芹澤委員","kind":"質問","question":"事前にお伺いしたところで言えば、以前からリサイクルとして使っていただいているというふうに伺っていますけれども、例えば。リサイクルもたしか売っていらっしゃるというふうに伺っていますので、そこの金額も改めてお聞かせほしいと求めました。","respondent":"工藤交通安全担当課長","answer":"検討に検討を重ね不動前を保管所として設置したところがありますので、そこら辺は、改めて重々検討させていただければというふうに考えてあります。そのリサイクルに充てる費用については、自転車１台当たり、大体１,８００円ぐらいで推移しています。","id":"exchange-098"},{"speaker":"芹澤委員","kind":"質問","question":"先ほど、これ、事前にも数字を伺っていましたが、１台１,８００円程度で、ある意味、売ることもできるわけですよね。あんなにいい場所ですから、いい場所ですから、ぜひあそこを盛り上げてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-099"},{"speaker":"こんの委員","kind":"質問","question":"私からは、３２１ページ、道路改良費、３５１ページ、セーフティネット住宅補助、この２点をお伺いしたいと思います。こうした課題について、区のご所見と改善策、何か考えていらっしゃるか、お伺いしたいと思います。","respondent":"工藤交通安全担当課長","answer":"区としましても、ここからは自転車を押して歩いてくださいというような注意喚起の立て看板を設置して注意を促しています。","id":"exchange-100"},{"speaker":"こんの委員","kind":"質問・要望","question":"２０１７年から、決算特別委員会などで求めてきたわけですが、ここは道路が幅広く確保されております。そうしたことを求めてきているわけですが、水神公園側から池上通り沿いになだらかな坂で１本の道で、いかがか尋ねました。","respondent":"森道路課長","answer":"今委員にご紹介いただきました桐畑隧道の部分ですけれども、今、ＪＲの線路下の幅員が約３ｍ程度となっています。バリアフリーのことであったり、できるだけ、引き続き安全性の高い通行ができるような構造を模索していきたいというように考えています。","id":"exchange-101"},{"speaker":"こんの委員","kind":"質問・要望","question":"高台に避難をするときの大事な避難経路として考えたときに、地域の方、あるいは大井鹿島町会からもそういう声が聞こえております。災害時の避難経路ということも併せて、ここの道路の抜本改善をいま一度求めたいと思いますが、ご所見を伺いたいと思います。","respondent":"森道路課長","answer":"あるいは周辺の道路との取付けをどう考えるか、スロープになったことで、逆に自転車の危険な走行ということも出てくるかもしれません。そういった様々な面が交錯している路線というふうに考えておりますが、池上通りですので、今後いろいろ検討していきたいというふうに思います。","id":"exchange-102"},{"speaker":"こんの委員","kind":"質問・要望","question":"最後のご答弁を伺って、どうか研究していただいて、改善をこれからも求めていきたいと思います。引き続き。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-103"},{"speaker":"のだて委員","kind":"質問・要望","question":"私からは、３３７ページの戸越公園駅周辺まちづくり事業に関わって、戸越公園駅周辺再開発の中止を求めて質問します。公共施設管理者負担金の総額も併せて伺います。","respondent":"中道まちづくり立体化担当課長","answer":"東京都と、令和５年度の事業認可変更などを進めているところで、令和５年度中に事業認可を変更していくという形で進めているところです。公共施設管理者負担金ですが、今現在、３億４,０００万円程度を予定しています。","id":"exchange-104"},{"speaker":"のだて委員","kind":"質問","question":"今現在、３９億円の補助金と、公共施設管理者負担金３億４,０００万円程度ということは分かったのですが、なぜ補助金が増えたのか伺ったので、答えるよう求めました。","respondent":"中道まちづくり立体化担当課長","answer":"１つの大きい要因としましては、コロナ禍というところで、資材または人件費が高騰したです。そうした資材高騰分を、今回、令和５年度以降、増加分という形で計上しています。","id":"exchange-105"},{"speaker":"のだて委員","kind":"質問・要望","question":"すみません、聞き漏らしまして、今後見込んでいる補助金総額、また、公共施設管理者負担金の見込んでいる総額もお答えほしいと求めました。","respondent":"中道まちづくり立体化担当課長","answer":"国のほうからの補助金につきましては、令和５年度は１３億円程度を予定しています。その進捗によって令和６年度は変更するものとなっています。","id":"exchange-106"},{"speaker":"のだて委員","kind":"質問・要望","question":"これまでは総額で補助金が３６億円ということだったのですけれども、今後どこまで上がっていくのかということで伺っております。品川区、自治体としてやるべき仕事ではないと思いますが、いかがか尋ねました。","respondent":"中道まちづくり立体化担当課長","answer":"補助金の総額ですが、約４０億円程度と見込んです。そうしたことも踏まえて、まちづくりを進めるというところで、補助金の使い方は適正と考えております。","id":"exchange-107"},{"speaker":"のだて委員","kind":"質問・要望","question":"この戸越五丁目１９番地区再開発事業の中止を求めます。いかがか尋ねました。","respondent":"中道まちづくり立体化担当課長","answer":"補助２９号線において、そうしたことをきっかけに、まちづくりを皆さんで今考えられているというところ。再開発を１つまちづくりの手法として取り入れているところで、地域の方々で考えてきたまちづくり、それに区も寄り添って進めているところです。","id":"exchange-108"},{"speaker":"のだて委員","kind":"質問","question":"寄り添っていると言いますけれども、やはり住民の暮らし、住環境が悪化するというところで、ぜひ再開発はやめてほしいと思うのです。超高層に反対する方が多い下でアンケートを利用し超高層再開発を進めることはやめるべきだと思いますが、いかがか尋ねました。","respondent":"中道まちづくり立体化担当課長","answer":"１８番地のまちづくりですが、今現在、東京都が主体となって、地域にどういったまちづくりを進めていくかということのアンケート調査をしています。まだまだそこの、いわゆる共同化にするのかどうか、個別で進むのかといったところを、今、皆さんで話し合われているところです。","id":"exchange-109"},{"speaker":"松澤委員","kind":"質問","question":"３５３ページ、そして３４１ページ、公園・児童遊園整備費のおもてなしトイレ整備について質問します。例えば、商店街近くの公園のトイレ、このような場所を優先してやっていただくことがおもてなしにつながるかと考えますが、ご見解を説明するよう求めました。","respondent":"高梨公園課長","answer":"現在の進捗ですが、約６割の公衆公園・児童遊園トイレの洋便器化が完了したといった状況です。順次、西品川おさんぽ公園と鎗ヶ崎公園の２か所が、洋便器化を進める公園トイレ等については選定していきたいと考えているところです。","id":"exchange-110"},{"speaker":"松澤委員","kind":"質問・要望","question":"そして手応えを教えていただきたいのと、これ、大変勉強になる冊子だと思いました。例えば、積極的に区のほうからマンション自治会へ直接配布していって、周知啓発に努めたほうがよろしいかと考えますが、ご見解をお願いします。","respondent":"平原防災課長","answer":"平成２９年度からマンション防災アドバイザー派遣事業を開始したところでございまして、防災講演を３６回、訓練支援を４０回など行ってまいりました。","id":"exchange-111"},{"speaker":"松澤委員","kind":"提案","question":"昨年度の予算特別委員会でも提案させていただきましたローリングストック、わざわざ災害のために買うのも負担があります。ぜひ大きく取り上げていただきたいと考えますが、ご見解を説明するよう求めました。","respondent":"平原防災課長","answer":"今、３月１１日に開催いたしました防災フェアも非常に盛況だったということもございまして、一定の効果があったものというふうに考えてあります。このことにつきましては、こちらについては今後とも様々な場で取り上げてまいりたいというふうに考えてあります。","id":"exchange-112"},{"speaker":"松澤委員","kind":"提案","question":"品川区の公式ＬＩＮＥアカウントでも要望が通りまして、防災に関するメニューが独立して、より見やすくなりました。このメニューを活用して、デジタル防災をぜひ進めていただきたいと提案しますとの意見を述べました。","respondent":"五十嵐災害対策担当課長","answer":"さらに気になる部分や、実証が必要な部分など、リアルな体験を通じて学ぶという手法は非常に効果的なものと認識しています。区といたしましても、引き続き、デジタル、リアル双方の訓練の参加を促してまいりたいと考えております。","id":"exchange-113"},{"speaker":"松澤委員","kind":"質問・要望","question":"これが災害時給水ステーションですけれども、現在、品川区には何か所あるのか教えていただきたい。「防災・減災、国土強靱化のための３か年緊急対策」が平成３０年より始まりましたが、品川区における水道管の耐震性等の状況を説明するよう求めました。","respondent":"吉岡防災体制整備担当課長","answer":"水道管の耐震化についてですが、都では給水管の耐震化を進めるとともに、さらに曲げることが可能である水道管路の継手の耐震化を進めております。","id":"exchange-114"},{"speaker":"松澤委員","kind":"提案","question":"４か所の場所のバランスというのですか、もう１個、半径を絞ってやることもいいのかと思っています。例えばこういうところに災害時給水ステーションを設置するとか、そういった考え方も提案したいのですが、ご見解を説明するよう求めました。","respondent":"吉岡防災体制整備担当課長","answer":"この４か所の災害時給水ステーションに加えまして、区民避難所の応急給水栓などにより、安全な飲料水を十分に確保しています。給水袋の配備も進めているところですが、訓練の実施なども含めまして、引き続き飲料水を必要な方へ確実にお渡しできる体制を整えてまいります。","id":"exchange-115"},{"speaker":"松澤委員","kind":"質問・要望","question":"しながわ防災学校についてお聞きしたいのですけれども、しながわ防災学校も含めて、防災士も私はいい事業になると思っています。両面から学ぶ機会を考えていただきたいのですが、ご見解をお願いします。","respondent":"平原防災課長","answer":"区といたしましては、防災士という資格の取得がモチベーション向上につながるという効果は認識していますけれども、一方で。","id":"exchange-116"},{"speaker":"高橋（し）委員","kind":"提案","question":"企業内を通行できるようにというご要望があり、以前のご答弁では、どういったことがやりたいということを提案しながら。それから３つ目、以前質問させていただいて、それからヤマダ電機に状況を伺うなどから始めていきたいということでおっしゃっていましたとの意見を述べました。","respondent":"鈴木都市計画課長、森道路課長、高梨公園課長","answer":"モバイルＳｕｉｃａに対応可能な新型機種への交換を実施しているところで、一方で、無人化についてエリア全体で検討しているというようなところで。ただ… それから、勝島人道橋の東口のところで考えております佐川急便との間の通路です。メインのルートになるかと考えておりますので… 私からは、しながわ花海道と新浜川公園に関する検討、シルバー人材センターの公園清掃費についてお答えします。","id":"exchange-117"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"今、交渉されているということですから、今後に向けて何とか実現するように進めていってほしいと求めました。発注元は今度は区になるわけですから、どのような予算措置をしているのでしょうか、お尋ねします。","respondent":"鈴木都市計画課長、高梨公園課長","answer":"基本的には、この動向を区としても注視してまいりますが、やはり駅員の方がいて、安全あるいは安心につながっている部分があろうかと思います。動向を注視して、必要な働きかけを今後行っていきたいです。シルバー人材センターから見積りを徴取し、協議の下、予算を計上させていただいているところです。","id":"exchange-118"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"先日の産業経済費でもお話ししましたが、シルバー人材センターに関しては、ぜひそういった事情の中で協議を進めてほしいと求めました。ぜひ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-119"},{"speaker":"たけうち委員","kind":"質問・要望","question":"それから３４３ページ、緑化活動支援事業、保存樹について伺います。１０月、この損害賠償保険で対応されるのかどうか、その辺を説明するよう求めました。","respondent":"工藤交通安全担当課長、高梨公園課長","answer":"公用の自転車を仕事で使う場合には、各所管課で用意していただいたヘルメットを必ずかぶって事故防止に努めるようにということでお願いしています。区民の方々にも、そういったヘルメットの重要性を再度周知しながら… 区のほうで、保存樹、保存樹林に対して入ってあります。台風等天災と認定される災害で発生したものについては、免責事項、保険料は支払われないということで保険会社から回答を得ています。","id":"exchange-120"},{"speaker":"たけうち委員","kind":"質問","question":"５０万円ぐらいかかって、やはりほかの自治体でも、台風の場合は非常に難しいみたいであります。一部というものがあったのですけれども、これについて区のご感想というか、どのような感じで思っているか説明を求めました。","respondent":"高梨公園課長","answer":"もう何十年もというような方もいらっしゃいますので、改めて保険の内容の周知については、実施する方向で検討したいと考えています。保険の商品等をしっかりと研究しながら、よりよい保険の加入について、これから検討してまいりたいと考えています。","id":"exchange-121"},{"speaker":"たけうち委員","kind":"質問","question":"本当に早ければ３か月、４か月でできることもあるのでしょうけれども、そこは通学路にもなっているのです。そういったものを例えばあとで少し返却するとか、支援するとかということができないのかと思うのですけれども、いかがか尋ねました。","respondent":"長尾建築課長","answer":"緊急対応ということで、そういったできる範囲での対応を、状況を見ながらしていきたいと考えております。","id":"exchange-122"},{"speaker":"高橋（伸）委員","kind":"質問","question":"時間がありましたら、３４９ページ、マンション管理支援事業についてお伺いしたいと思います。平成３１年度予算にはあって、令和２年度以降は予算づけがないところで、進捗はどうなっているのかということをお尋ねしたいと思います。","respondent":"森道路課長","answer":"事務費の中等々に隠れてしまっておりますけれども、予算としてはいただいておるところです。今もまだ月に３００枚とか、４００枚とか、そういった配布実績があるところです。","id":"exchange-123"},{"speaker":"高橋（伸）委員","kind":"質問","question":"課長がおっしゃったように、第１弾と第２弾があります。今８つのデザインマンホールがあるのですけれども、今後、デザインマンホールの設置は考えておられるのかということだけお聞きしたいと思います。","respondent":"森道路課長","answer":"今、具体的に、この場所で、このデザインでとは考えていないところではあります。ただ、そういった部分のＰＲに資する１つの施策であろうと考えますので、そういったものも考えていきたいというふうには思っています。","id":"exchange-124"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"それは確認していないのですけれども、ぜひ周知をよろしくお願いしたいということで、これは要望でよろしくお願いいたします。続きまして、３３９ページ、立会川児童遊園（その３）、旗の台北公園改修基本・実施設計委託についてお伺いいたします。","respondent":"高梨公園課長","answer":"令和５年度は、立会川児童遊園（その３）と、東急池上線沿いの旗の台北公園を一体として基本設計・実施設計を行う計画としています。そういった事実を踏まえながら、地域の皆様の声をしっかりと聞いてまいりたい、このように考えているところです。","id":"exchange-125"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"もう１点ですけれども、立会川児童遊園（その３）のところは、タイルとかが盛り上がっている状態です。新しくするときには、路面をきちんとしっかりとやっていただきたいという要望なのですけれども、お考えを説明するよう求めました。","respondent":"高梨公園課長","answer":"新しいものにするかというところも含めて、しっかりと地域の皆さんのお考え、声を聞いてまいりたいというふうに考えてあります。そういった現状等をしっかりと調査して、全体改修の内容に活かしていきたいと考えています。","id":"exchange-126"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"３４１ページ、Ｐａｒｋ－ＰＦＩ導入に向けた事業化検討についてお伺いいたします。民間事業者の意見を聞いてきたとのことですけれども、お分かりになればでいいので、意見を聞いた民間業者の業種と数を教えてほしいと求めました。","respondent":"高梨公園課長","answer":"昨年１２月にサウンディング調査を実施することを公表させていただきまして。飲食業を営んでいる会社であったり、また、食品を製造している会社等々から申込みがあったところです。","id":"exchange-127"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"意見の中で、この事業化に取り入れたいような有意義な意見はあったか、あったとしたら、どのようなものなのか、お知らせほしいと求めました。","respondent":"高梨公園課長","answer":"一応、公表した段階では１月末の時点で個別対話を実施したところですが、現段階でも数社とは個別の打合せを続けているといったような状況です。","id":"exchange-128"},{"speaker":"高橋（伸）委員","kind":"質問","question":"７か所でしたか、この７つの公園が選ばれている選定の基準があると思うのですけれども、教えていただけたらと思います。","respondent":"高梨公園課長","answer":"候補となる７つの公園を選んだ根拠ですけれども、面積がないといけないということで、１万m2以上の公園をまずピックアップいたしました。水辺に近い、利用者の利便性に非常に資するのではないかといった観点から、その１万m2以上の公園の中から７公園を選んだところです。","id":"exchange-129"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"この７つの公園、それぞれの公園の特性があると思うのです。事業者の公募は７つの公園ごとに行われるのか、それとも、１つの業者が一括して７つの公園を手がけていくのかをお知らせほしいと求めました。","respondent":"高梨公園課長","answer":"実施する公園の数もまだ未定といったところですが、区といたしましては、まず候補の公園全てでいきなり始めるのではなくて、まず、一番効果があるであろう１つの公園、１つの業種で、１つの事業内容で始めさせていただければと考えているところです。","id":"exchange-130"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"渋谷区も、それぞれ特性を持った公園となっておりますので、ぜひ本区としても取り組んでいただきたいと考えています。もう１つお伺いしたいのですけれども、事業者に対して何かデメリットがあれば、教えていただきたい。","respondent":"高梨公園課長","answer":"どうしても新しいことを始めようとしますと、特に周辺の方々からは賛否両方のご意見をいただくことがあろうかと思います。人を集めてにぎわいを持たせたいという考えの裏返しでは、そのデメリットよりも、そのように成功させていきたいというふうに今考えているところです。","id":"exchange-131"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"ほかの公園の自動販売機の設置とかいろいろありましたので、それを含めて公園づくりを目指してほしいと求めました。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-132"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私からは、３３７ページの公園管理費と、あと、リニア新幹線について伺いたいと思います。計画的にトイレの改修をしていただきたいと思うのですが、その２点、伺いたいと思います。","respondent":"高梨公園課長","answer":"用地情報はなかなか区としてもリアルタイムな情報は難しいところです。令和９年度までには、区内の公園トイレ、児童遊園トイレについては洋式化を完了させたいというふうに考えてあります。","id":"exchange-133"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"これはＪＲ東海の説明責任と中止を求めていただきたいという思いで質問したいと思います。それから、２００ｍ間隔でないところはどれぐらいあるのか、その点について伺います。","respondent":"中道まちづくり立体化担当課長","answer":"シールドの掘削深さまで達しているボーリングは、ＪＲ東海が実施しました１１本です。土質調査ですけれども、既存資料など地質の構成を把握してといったところで、良質な土質の状況を随時把握しているということを聞いてあります。","id":"exchange-134"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ここのところはしっかりと、私は区としても求めてほしいと求めました。このシールドマシンは昨年の３月からずっと止まったままで、それから、何メートル掘進するのかということの説明を聞いていたら伺いたいと思います。","respondent":"中道まちづくり立体化担当課長","answer":"シールドの今後の状況ですが、止まっていたので、動作確認ということで、今月末にセグメント４リング分、７ｍ程度動くということは聞いてあります。土木のガイドラインですが、こういったものを踏まえてシールド工事を進めていくと聞いてあります。","id":"exchange-135"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私は、説明責任をしっかりと果たしていくべきだということを改めて区のほうからも求めてほしいと求めました。中止を求めてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-136"},{"speaker":"松本委員","kind":"質問","question":"私からは、３１７ページ、交通安全啓発費、３１９ページ、道路安全施設費、３５７ページ、避難看板整備費について伺います。このような状況になっているのは、何か事故が過去にあったのか、この辺りを伺いたいと思います。","respondent":"工藤交通安全担当課長","answer":"交通事故防止の観点から、その場の状況に応じまして効果的と思われる対策を実施しています。委員のご説明がありました荏原南公園前の通りですけれども、「横断歩道あり」、「止まれ」の標識が設置された経緯があると伺っております。","id":"exchange-137"},{"speaker":"松本委員","kind":"質問・要望","question":"私もこれは地域の方からご要望いただいたところで、実際に車で走っていると、見通しが悪くて少し怖いというような話を伺いました。これは地域の町会の方たちとのご相談にはなると思うのですけれども、これを移動していただくということはできないか、お伺いいたします。","respondent":"工藤交通安全担当課長","answer":"掲示板の移動ができないかというようなご質問に対してお答えしたいと思います。町会の方々のご意見等をお聞きしながら、そちらについては、できる対応をしていきたいと考えています。","id":"exchange-138"},{"speaker":"松本委員","kind":"質問・要望","question":"実際にここで事故があったというような情報もお伝えしていただきながら、対応について考えていただきたいというふうに要望します。一部にはやられていると思うのですけれども、こうした対応について、区の見解をお伺いいたします。","respondent":"森道路課長","answer":"例えば、路面標示で視覚的なハンプといいましょうか、そういった部分もあります。今、例で挙げられました荏原南公園のところについても、それぞれ検討していきたいと考えています。","id":"exchange-139"},{"speaker":"松本委員","kind":"質問","question":"仮に無視したとしても、刑事罰がないというか、違反にはならないというようなことは聞いたことがあります。標識としてではなくて、路面に「止まれ」というふうに書くというようなアイデアもあり得るのではないかと思いますが、いかがか尋ねました。","respondent":"森道路課長","answer":"今、荏原南公園のところですと、通学路になっているというお話でございました。それこそ「止まれ」であったり、そういった文字での標示ということもしっかり候補の中に入れて検討していきたいと思っています。","id":"exchange-140"},{"speaker":"松本委員","kind":"質問","question":"次に、避難看板整備費について伺います。こちらは令和３年度に行われた避難看板等の現況調査の結果を受けての予算だと思いますが、整備の内容についてお伺いいたします。","respondent":"吉岡防災体制整備担当課長","answer":"平常時からそういった認識をしてもらうことを目的にいたしまして、区内５２か所にあります区民避難所に看板を設置するものです。今後は、令和５年度から令和７年度、３年間かけて区民避難所に順次設置をしていくところです。","id":"exchange-141"},{"speaker":"松本委員","kind":"質問","question":"では、どこに避難所があるのかということもご存じない方はやはりいらっしゃって、震災のときとかはネットもつながらないというような事情があります。なので、避難場所に誘導するような標識も必要かと思いますが、いかがか尋ねました。","respondent":"吉岡防災体制整備担当課長","answer":"あるいはしながわ防災ハンドブックでそういった場所を認識していただくという啓発が非常に重要だと思いますけれども、そういったものを収集しながら、今後のさらなる安全な避難誘導体制を検討していきたいと思います。","id":"exchange-142"},{"speaker":"松本委員","kind":"質問","question":"路面に、こちら側が避難所ですよというような標示は比較的やりやすいかと思いますので、ぜひこれも検討していただけないでしょうか。一言お願いします。","respondent":"吉岡防災体制整備担当課長","answer":"今ご提案いただいたものも含めまして、こういった他自治体での好事例を収集しながら、引き続きいろいろと研究していきたいと思います。","id":"exchange-143"},{"speaker":"若林委員","kind":"質問・要望","question":"３２５ページ、河川管理費、来年度の様々な取組を確認します。２０１７年、御成橋公園も洋式化されましたけれども、洋式化とか安全安心なトイレをご要望してまいりました。","respondent":"栗原河川下水道課長、高梨公園課長、平原防災課長","answer":"毎年マナー啓発活動を実施しておりまして、実際に船で来られる方に、スピードを出さないようにということを呼びかけて実施していくものです。… 順次、洋便器化を進め、令和９年度までに全ての公園・児童遊園トイレの洋便器化を完了させたいというふうに考えてあります。… 私からは、災害時の薬のランニングストックについてお答えします。","id":"exchange-144"},{"speaker":"若林委員","kind":"質問・要望","question":"水辺、五反田が選定されるかどうか分かりませんけれども、ぜひ魅力アップにつなげていただきたいと。水辺をどのように魅力をアップさせていくかというような取組も、ぜひご検討ほしいと求めましたけれども、一言ご答弁を。","respondent":"高梨公園課長","answer":"公園におきましても、水辺におきましても、しっかりと地域の方とお話しながら、魅力ある品川のまちづくりを進めていきたいと考えています。","id":"exchange-145"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"私からは、３５７ページ、７項の防災費、帰宅困難者対策経費、それと３４１ページ、公園・児童遊園整備費から質問させてほしいと求めました。どのように力を注いでいるのか、その点につきまして、お答えほしいと求めました。","respondent":"高梨公園課長、吉岡防災体制整備担当課長","answer":"そういったあの区域全体での公園の在り方、しっかりとゾーニングを含めて検討していかなければいけないというふうに考えてあります。さらに望ましいと考えていますので… 考え方についてですけれども、再開の見込みが立たない場合、こういったことによりまして帰宅困難者自身も二次被害に遭うおそれがあります。","id":"exchange-146"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"昼間家にいるお子さんたちも遊びに行かれるような形をつくってもらいたいと思いますので、その辺、もう１回お考えをお聞きしたいです。区としてどういう対応をしていくか、地元の方と商店街の方との関連もあると思うのですが、その辺についてお聞きしたいと思います。","respondent":"高梨公園課長、吉岡防災体制整備担当課長","answer":"委員がご懸念されているような状況にならないように、庁内関係各所としっかりと話を進めてまいりたいというふうに考えてあります。多くの方が憩いを、そういった形でも利用ができる用地となるように… まだまだ拡充が必要と考えていますので、今後、さらに一歩前にアプローチを強めてまいりたいと思います。","id":"exchange-147"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"品川区は４つの駅の協議会でしたか、たしか協議会をやっていますね。それから国道１５号徒歩帰宅者支援対策協議会、もし何かありましたら、教えてほしいと求めました。","respondent":"吉岡防災体制整備担当課長","answer":"４つの協議会、こういったものを構成員といたしまして、駅周辺帰宅困難者対策協議会が設置されてあります。国道１５号徒歩帰宅者支援対策協議会につきましては、こちらは災害発生４日目以降から移動を開始する徒歩帰宅者の支援を目的に活動しておりまして。","id":"exchange-148"},{"speaker":"鈴木（真）委員","kind":"意見","question":"１２年前、たしかすごい人、例えば、私、第一京浜を見ていて、物すごい人が歩いていました。その辺について、改めてもう１回お願いしたいと思いますが、との意見を述べました。","respondent":"吉岡防災体制整備担当課長","answer":"一時滞在施設の拡充を進めているところでありますけれども、方法を考えまして、推進していきたいと考えております。","id":"exchange-149"},{"speaker":"田中委員","kind":"質問・要望","question":"子どもが自由な発想で安全に遊べる場所の１つに、フェンスに囲まれた特定整備路線の用地活用は考えられないでしょうか、伺います。プレーパーク運営者をはじめ、保育園事業者等にも区から声をかけていただきたいと考えますが、見解を伺います。","respondent":"高梨公園課長、大石木密整備推進課長","answer":"プレーパークの常設の設置についてですが、所管である子ども育成課と連携して話を進めてありますが、なかなか次のもう１つといったところについては。は周辺の皆様にとっても、よりよい遊び場… そのような中で、品川区といたしましては、暫定活用として地域の皆様のニーズを受けまして、令和２年度から一時的な利用として活用しています。","id":"exchange-150"},{"speaker":"田中委員","kind":"質問・要望","question":"何か改善策を区として検討されているのでしょうか、伺います。ミニバスケができる公園、広場の設置について、区としてどのようにお考えなのか見解を伺います。","respondent":"高梨公園課長","answer":"そちらについては、点検をして、所管同士で話をして分かりやすいホームページの表記については努めてまいりたいと考えています。なお、公園課のほうに声が多く届いているものではございませんし、なかなか屋外で試合ができる設備を公園内に設置するというのは。","id":"exchange-151"},{"speaker":"田中委員","kind":"質問・要望","question":"候補地７か所は未定とのことを先ほどの質疑で確認しましたが、その認識でよろしいでしょうか。判断する部署はどこになるのか、以上、７点伺います。","respondent":"高梨公園課長","answer":"候補の７公園のうち、検討していますので、まだ現段階ではどこの公園でどのような事業を行うかが決定されているようなものではございません。魅力的な公園、まちづくりとなるように努めてまいりたい、このように考えているところです。","id":"exchange-152"},{"speaker":"田中委員","kind":"質問・要望","question":"セーフティネットとしての役割があるということを本当に忘れないでほしいと求めました。光熱費の問題とか、そういうことも発生してきますので、ぜひそういった視点を忘れずにということを強く申し述べたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-153"},{"speaker":"大倉委員","kind":"提案","question":"あまりにももったいないと思うので、ぜひ活用を含めて検討してほしいと求めましたが、いかがでしょうかという質問です。ドッグランは、ぜひモデルケース的にどこかで１回でもいいからできないかなというようなご提案をしようかなと思ったら、先ほどのご答弁の中でとの意見を述べました。","respondent":"工藤交通安全担当課長、栗原河川下水道課長、高梨公園課長","answer":"今後、どのような形がいいのかというところも含めて、いろいろな意見を参考にしながら慎重に考えていきたいと考えております。… 私からは、目黒川水質浄化対策検討会の実施状況等につきましてご説明します。目黒川水質浄化対策検討会という会議体を設けまして… そういった中でドッグランの設置に際しましては、接している住宅に対しての、鳴き声であったり。","id":"exchange-154"},{"speaker":"大倉委員","kind":"質問・要望","question":"令和４年度、品川区としても、そうした住環境における区民の声は聞いていただけているのかどうかということを教えてほしいと求めました。本当に地域の方からもドッグランの設置の要望が非常にありますので、ぜひ検討していただきたいと思っているのですが、それについて説明を求めました。","respondent":"工藤交通安全担当課長、栗原河川下水道課長、高梨公園課長","answer":"不動前の関係ですけれども、委員ご指摘のとおり、幅広く不動前の町会の方々のご意見もしっかりと聞きながら、慎重に考えてまいりたいと考えています。… 目黒川で一番泥が溜まりやすい区間が、目黒区と品川区のちょうど境の部分、正に今お話がありました雅叙園の辺りというところで認識しております。引き続き… ドッグランのモデル実施に際しましては、モデル実施をできるかどうかも含めて検討を進めてまいりたいというふうに考えてあります。","id":"exchange-155"},{"speaker":"大倉委員","kind":"質問・要望","question":"ぜひよろしくお願いします。ぜひしっかりと取り締まっていただきたいと思うのですけれども、こういったものは、罰則等があったのでしたかということの確認。","respondent":"溝口土木管理課長","answer":"道路法の中で罰則がありますので、しっかりそういった違法な広告物については除却していく、そういったことに取り組んでいきたいというふうに考えているところです。","id":"exchange-156"},{"speaker":"吉田委員","kind":"質問・要望","question":"私からは、目黒川の水質改善について、関連質問させてほしいと求めました。各委員から区民への啓発をどのようにするのかというご質問が出たのですが、どのようにお考えか、ぜひ伺いたいと思います。","respondent":"栗原河川下水道課長","answer":"区として何かというところは難しいのですけれども、東京都と連携して、水質改善に向けた合流式下水道の啓発につきましては検討してまいりたいと考えております。","id":"exchange-157"},{"speaker":"吉田委員","kind":"質問・要望","question":"実はあなたの生活排水が流れ込んでこうなっているのですよというところの啓発が、もう少し分かりやすくされるといいかなと思います。あれはやめてほしいなと、油汚れも全部流せますというのはやめてほしいなというのが私たち生活者ネットワークの意見ですけれども、いかがか尋ねました。","respondent":"栗原河川下水道課長","answer":"例えば、それが昔で言えば、海に流されてオイルボールとして固まってお台場に漂着というような問題もあるということは認識しております。下水道」、そういったＰＲもしていますけれども、引き続き、連携してどういったＰＲができるかは検討してまいりたいと考えております。","id":"exchange-158"},{"speaker":"吉田委員","kind":"質問・要望","question":"油・断・快適でしたか、油を断つことで快適な水環境を守るという、それはむしろ推進しているのは東京都だと思います。ぜひ品川区も活用してほしいということも以前要望させていただいたのですが、油は、改めてご見解を伺います。","respondent":"栗原河川下水道課長、河内環境課長","answer":"下水道局とも連携いたしまして、今お話にありました「油・断・快適！下水道」ですとか、普及啓発については進めてまいりたいと考えております。 併せまして、水質汚濁防止法に関しまして、区のほうでも啓発しています。公共水域に流れる水につきまして、区民の皆さんがご協力いただけますよう、そういったところでもまた啓発を進めてまいりたいと考えているところです。","id":"exchange-159"},{"speaker":"石田委員","kind":"質問・要望","question":"私たち共産党としても、意見や要望を述べてきたのですけれども、アンケートでは賛否は問わないということです。改めて、森澤区長は、この羽田新ルートの区民の理解は得られているかという点について、前区長と同じ立場なのか伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"基本的には、羽田新飛行ルートについては、国策として国の責任において進められていくべきものという区としての受け止めです。今後も地域への丁寧な情報提供、あるいは落下物、騒音環境の軽減に向けた取組を行うことを前提に国は進めていくというところで発言があったものです。","id":"exchange-160"},{"speaker":"石田委員","kind":"質問・要望","question":"今からでも理解は得られたという認識を改めていただきたいと思うのですけれども、いかがでしょうか。解決策というのは、羽田新ルートの何を解決させる策なのか、伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"今委員にご紹介いただいたように、運行開始前の教室型説明会でも様々な意見をいただいております。運行開始後も、これまで区のほうには５５０件ほどの様々な声が寄せられているところです。","id":"exchange-161"},{"speaker":"石田委員","kind":"質問・要望","question":"何を解決、具体的な解決策を国に求めていくと、働きかけるとおっしゃっているのです。こうした中のどこをどのように解決させると思って、その解決というのは、区にとって解決というのは何なのかということをお聞きしたいのですけれども。","respondent":"鈴木都市計画課長","answer":"しっかり制度設計を行いながら、必要な取組を国に求めていく、解決策を求めていくです。","id":"exchange-162"},{"speaker":"石田委員","kind":"質問・要望","question":"新ルートによる被害の解決ということでしょうか。アンケートをとった上で、撤回を求めることも１つの解決策としてあり得るのか、伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"そうした声は、これまでの、先ほどの５５０件の中にも含まれているところです。正にこれからそれを実施し、国のほうで具体的な解決策にしっかり取り組んでいただけるように、検討を行っているです。","id":"exchange-163"},{"speaker":"石田委員","kind":"質問・要望","question":"なので、こうした区民の犠牲をゼロにするよう求めていく、求めていただきたい、それを望んでいると思うのです。やはり今ある被害を解決してほしい、なくしてほしいということが区民の願いだと思うのですけれども、いかがか尋ねました。","respondent":"鈴木都市計画課長","answer":"落下物等のお話もございましたが、正にあってはならないことですし、そうした取組をこれまでも求めてきたところです。実態を正確に分析把握して、国にしっかり届けると、この内容をもって具体的な解決策を国のほうで行っていただくよう働きかけてまいります。","id":"exchange-164"},{"speaker":"塚本委員","kind":"質問・要望","question":"３１９ページ、３５３ページ、３５７ページの輸送管理体制強化費ということで伺っていきたいと思います。教えていただきたいのと、このコンセント式の感震ブレーカー、効果的な使い方についてもお伺いしたいと思います。","respondent":"吉岡防災体制整備担当課長","answer":"不燃化推進特定整備地区、こういったところに比べると、広い地区での配布をするというようなお話を伺っているところです。大きく２つ分けますと、そういった機器ですので、そういった機器の違いがあるというところを把握しています。","id":"exchange-165"},{"speaker":"塚本委員","kind":"確認","question":"一応確認したいのですけれども、どういうことが想定されるのか、それをお伺いしたいと思います。","respondent":"吉岡防災体制整備担当課長","answer":"東京都も制度設計中ですけれども、やはり品川区も含めまして、各自治体のほうでこういった補助事業を幾つかの自治体がやっているところです。","id":"exchange-166"},{"speaker":"塚本委員","kind":"質問","question":"家は１つのコンセントであるわけではないので、木密地域以外でも、もしかしたら。そのようなことも考えられないのかなと思いますけれども、その辺について区のお考えを伺いたいと思います。","respondent":"吉岡防災体制整備担当課長","answer":"区の関わりがない部分ではありますけれども、これから各自治体の声をまた聞いていただけるような機会があるかと思いますので、そういったご提案もさせていただきたいと思います。","id":"exchange-167"},{"speaker":"塚本委員","kind":"質問","question":"相当期間内というのは、はっきりとは決まっていないけれども、２週間程度というふうに言われているそうです。１つは、２週間たちました、その点についてお伺いしたいと思います。","respondent":"森道路課長","answer":"１週間、２週間そのままであったり、区のほうで通行に支障がない範囲内で切除をさせていただいているところです。区としても、引き続き、適正な交通が確保されるように、しっかりと管理をしていきたいというふうに考えております。","id":"exchange-168"},{"speaker":"塚本委員","kind":"質問・要望","question":"これまでもできたというところでしたけれども、実際には、なかなか所有者が同意しない中で本当にやれるのかというのは、なかなかあったところで、そういう中で法改正をすると、さらにという近隣からの要望は強くなってくると思うので、対応を今後ともよろしくお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-169"},{"speaker":"渡辺委員","kind":"質問","question":"３３７ページ、公園管理費で清掃のこと、そして３４１ページ、公衆便所費、そして３２５ページ、水辺利活用事業、この３点を伺います。同時に、公衆便所の点も、こちらも清掃というところから聞きたいのですが、委託先等を説明するよう求めました。","respondent":"高梨公園課長","answer":"そうでないところで差がありますので、一番頻度が高いところでは、１日に３回の清掃を行ってあります。一番頻度が低い公衆便所でも、１日に１回は清掃に回るという形でやらせていただいているところです。","id":"exchange-170"},{"speaker":"渡辺委員","kind":"質問","question":"時代とともに様々なアレンジもできるのかなと思って、就労支援、あるいは拡大できるものは拡大していくべきという思いで見解を伺います。そういう中で、都内で、あるいは２３区の中で、品川区の公園の割合とか立地状況はどうなのだろう、そういうところを説明するよう求めました。","respondent":"高梨公園課長","answer":"福祉団体の就労の場所の確保といった観点で、所管を越えて連携してまいりたい、このように考えているところです。２３区の中での設置の箇所数のデータは、逆に、飛び抜けて少ないというようなところではないという認識です。","id":"exchange-171"},{"speaker":"渡辺委員","kind":"質問・要望","question":"これから伺いたいのは、公衆トイレを増やしてほしい、確認で。そういう意味で、時代に沿ったニーズに沿うという意味で、ぜひ検討していただきたいという思いで伺います。","respondent":"高梨公園課長","answer":"来街者への対応であったり、障害者への対応といったところで、これから高くなってくる側面もあるのかなというふうに考えてあります。様々方策があると思いますので、これから前向きに検討してまいりたいというふうに考えてあります。","id":"exchange-172"},{"speaker":"渡辺委員","kind":"質問・要望","question":"これは何だ、これとの違いは何だというお問合せを結構伺うので、その背景には不安もあるのです。説明を求めました。","respondent":"栗原河川下水道課長","answer":"まとめるに当たりましては、区内の舟運事業者、ＮＰＯの方々、地域の団体の皆様など、様々な意見を伺いながら検討を進めたいと考えております。検討を進める中においても、内容につきましては、引き続き地域の皆様等に意見を伺いながら進めてまいりたいと考えております。","id":"exchange-173"},{"speaker":"渡辺委員","kind":"質問・要望","question":"ですから、何が言いたいかというと、一朝一夕にすぐ成功とはいかないと思います。そういう中で、単年度ではなく、将来的に制度自体が進化していってほしいなと思うのですが、その辺、見解を説明するよう求めました。","respondent":"栗原河川下水道課長","answer":"体験実施ですとか、また、そういったお祭りに来ていただいた方に楽しんでいただいているところです。地域の皆様とよくお話し合いを進めていきまして、必要なイベントの実施であったり、しっかり取り組んでまいりたいと考えております。","id":"exchange-174"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/756395?Template=document&Id=1172#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":137313,"voices":415}},{"id":"r05-20230316-3","meetingId":"r05-c-budget","date":"2023年3月16日","dateIso":"2023-03-16","committee":"予算特別委員会","time":"午前１０時００分～午後 ５時３２分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を184件整理しています。","topics":[{"id":"topic-01","title":"予算特別委員会","agenda":"予算特別委員会","exchanges":[{"speaker":"江野下委員","kind":"質問","question":"３６９ページ、学校２０２０レガシー事業、３８３ページの登下校区域防犯カメラ維持管理費についてお伺いします。学校通学路へは２１２台の設置と伺い、１０年前より軽犯罪が５割減となり、貢献度が高いと伺いました。","respondent":"森学校施設担当課長","answer":"捜査の関係上教えてはいただけないのですけれども、違う犯罪での確認というようなもの、大体月に３０件ほど警察からお問合せがある状況です。","id":"exchange-001"},{"speaker":"江野下委員","kind":"質問","question":"小学校、品川区内では３１校、義務教育学校６校、中学校９校ですから、一施設に４台程度になるのでしょうか。、答えるよう求めました。","respondent":"森学校施設担当課長","answer":"２１２台の内訳ですけれども、委員ご指摘のとおり、１つの学校におよそ２台から５台程度整備されている状況です。","id":"exchange-002"},{"speaker":"江野下委員","kind":"質問・要望","question":"先日もご答弁で、町会・自治会には他区よりも多く支援をしているとも伺いました。ヒヤリハット、重大な事故があった場所にさらなる拡充を要望しますが、いかがか尋ねました。","respondent":"森学校施設担当課長","answer":"こちらの皆様が、年に１回パトロール、品川区通学路安全・安心プログラムに基づく安全安心総点検というものをしていただいております。この場所に防犯カメラをつけたほうがいいという答申等が出された場合には、至急対応するようにしていきたいと、そのように考えてあります。","id":"exchange-003","title":"町会・自治会支援"},{"speaker":"江野下委員","kind":"質問","question":"次に、学校２０２０レガシー事業のブラインドサッカー体験教室について伺います。こちらの体験教室の内容、開催の回数、地域なども示すよう求めました。","respondent":"中谷指導課長","answer":"昨年度はコロナのためオンラインでの実施ということになっておりましたが、中学校９校、体験的な実施をすることができております。コミュニケーションを行っていくときに、いかに相手意識に立たなければいけないかというところを学ぶ、大変貴重な機会になってあります。","id":"exchange-004"},{"speaker":"江野下委員","kind":"質問・要望","question":"８年生が全員体験できるということを確認できました。ぜひ拡充した支援を要望しますが、いかがか尋ねました。","respondent":"中谷指導課長","answer":"観戦という計画と、体験活動とを組み合わせて実施していくことで、効果が出ていくものかなと考えています。定期的にこういったご案内は学校に周知をさせていただいて、希望する学校が手を挙げていくということで、来年度も１つの小学校が観戦予定です。","id":"exchange-005"},{"speaker":"江野下委員","kind":"確認","question":"この質問に当たり、知り合いのママ、お子さんにまもるっちを見せてもらい、機能なども確認しました。こちらについてお伺いします。","respondent":"矢部教育総合支援センター長","answer":"まもるっちの周知についてです。大体校長から朝会の際に目安箱の説明をするのですが、そのときに、まもるっちの相談機能についてもご説明をしています。","id":"exchange-006"},{"speaker":"江野下委員","kind":"質問・要望","question":"１人はやはり「何、とてもいい機能だと思いますので、ぜひ周知の拡充を要望したいと思います。ですから、もう少しＨＥＡＲＴＳの相談機能の拡充というか、また、今までにどのような相談が子どもたちから寄せられていたか、お伺いします。","respondent":"矢部教育総合支援センター長","answer":"まず垣根というのですか、なるべくサッと大人に相談できるところがあるという１つの機関だと思ってもらえたらと考えています。本当に１割ぐらいは、ご家庭のことや、自身のメンタル面での相談があるです。","id":"exchange-007"},{"speaker":"江野下委員","kind":"質問・要望","question":"体のことですね。もう少し相談員を増やすなり、そういった対応を要望しますが、いかがか尋ねました。","respondent":"矢部教育総合支援センター長","answer":"検討します。","id":"exchange-008"},{"speaker":"新妻委員","kind":"質問・要望","question":"支援について、具体的にどのようになっていくのかというところの、少し分からない点を確認させてほしいと求めました。４月からスタートしていくということでよろしいのか、そのようなことをどのように把握していくのかというところを確認したいと求めました。","respondent":"勝亦学務課長","answer":"具体的な支援の方法につきましては、現在情報収集等を行っておりまして、検討しています。対象になられる方は、概数として２００人から３００人程度が、区民の方で都立特別支援学校に通っていると、概数を把握しています。","id":"exchange-009"},{"speaker":"新妻委員","kind":"質問・要望","question":"漏れがないように確認してほしいと求めましたし、区立学校に通う皆さんは給食費を払わないという、そのような流れかと思いますけれども、都立でありますこの学校の方においては、そのお支払いの仕方など、そのようなものはどのようにお考えか尋ねました。","respondent":"勝亦学務課長","answer":"所得制限なしで無償化というように考えてございまして、設置者が東京都となっていますので、区立の学校と同じ方法は取り得ないのかなと考えています。手法につきましても、具体的なものについてはこれから検討してまいりたいと考えています。","id":"exchange-010"},{"speaker":"新妻委員","kind":"確認","question":"次に、教育相談事業費に関連いたしまして、学校制服の選択制について確認します。子どもたちの中での、ＬＧＢＴＱの方への配慮というところで、学校制服の選択制を認めてほしいという、そのような質問を取り上げてまいりました。","respondent":"矢部教育総合支援センター長","answer":"令和５年度、女子のスラックス着用など標準服の選択が可能な学校は、１５校中１４校です。１校につきましては、校舎の建て替えをしておりまして、そのタイミングを見て一度に考えているということを聞いております。","id":"exchange-011"},{"speaker":"新妻委員","kind":"意見","question":"ぜひ進めてほしいけれども、なかなかそこが今は難しいというようなお話をいただいたということで、とても残念がっていました。教育委員会として、その学校に対してはどのように対応されていくのか、お知らせくださいとの意見を述べました。","respondent":"矢部教育総合支援センター長","answer":"ＬＧＢＴＱにつきましては、これまでも研修を繰り返しておりまして、学校のほうも理解はしていると認識しています。現在も個別対応はしておりまして、ズボンであっても、個別によく保護者や本人と相談をして対応するよう指導しております。","id":"exchange-012"},{"speaker":"新妻委員","kind":"質問","question":"最後に、ＰＴＡについてお伺いします。この内訳を説明するよう求めました。","respondent":"宮尾庶務課長","answer":"私から、ＰＴＡ活動支援経費１,０００万６,０００円の内訳についてご説明します。３点目が、実施していただくための経費、こちらの予算額が５２０万２,０００円となっています。","id":"exchange-013"},{"speaker":"新妻委員","kind":"質問","question":"現在、コロナ禍の中でこの３年間、４年目になりますが、ＰＴＡの活動も大変変わってきたなと考えています。今後の考え方として、ＰＴＡの外部委託やＰＴＡの解散ということに対してどのようにお考えか、お伺いいたします。","respondent":"宮尾庶務課長","answer":"委員から案内がありましたように、コロナ禍でというところがありますので、新しい在り方を共に模索していければと思います。","id":"exchange-014"},{"speaker":"安藤委員","kind":"質問","question":"３６３ページ、学事制度検討経費、３７１ページ、不登校児童・生徒支援事業、３６４ページ、教育指導費に関わって、校則について伺います。どのように地域、卒業生など住民の意見を反映させるお考えなのか、伺いたいと思います。","respondent":"勝亦学務課長","answer":"学区の変更も含めてご検討いただきまして、最終的にはその答申に基づいて、教育委員会のほうで決めていきたいと考えています。区民の方のご意見の取り方については、具体的には今後検討していきたいと考えています。","id":"exchange-015"},{"speaker":"安藤委員","kind":"質問","question":"ちょっと伺いたいのですが、数年前に小山小学校から後地小学校への学区変更がありましたけれども、その概要と、当時の変更理由について伺います。学区変更後に、地域や卒業生など住民からの反応はどのようなものだったのか、何かつかんでいる声がありましたらご紹介いただくよう求めました。","respondent":"勝亦学務課長","answer":"人口が増えているところは学区の変更を検討ということでございました。こちらについては、人口が増加しているということを見込んだ上での検討です。","id":"exchange-016"},{"speaker":"安藤委員","kind":"質問","question":"令和４年度の学校別新入学者の増減要因というものが毎年報告されていますが、第三日野小学校、御殿山小学校となっています。浜川小学校、城南小学校については、学区内の住民基本台帳上の児童・生徒数が増えた理由は何だと考えていらっしゃるのか、伺いたいと思います。","respondent":"勝亦学務課長","answer":"浜川小学校、城南小学校の人口増についてのお問合せです。いずれも、近年大規模な集合住宅ができたことによる人口増というように捉えてあります。","id":"exchange-017"},{"speaker":"安藤委員","kind":"質問","question":"このことについて、品川区教育委員会としては、まちづくり部門や企画などの部門の方々に何か思うところはないでしょうか。伺いたいと思います。","respondent":"勝亦学務課長","answer":"学校施設の整備につきましては、そういった開発の状況も踏まえて、可能な限り、ある施設の中で受け入れているところで、学校の教室の整備の計画等を立てているところです。","id":"exchange-018"},{"speaker":"安藤委員","kind":"提案","question":"伺いますけれども、選択制の存廃も検討課題に入れるべきだと思いますが、いかがでしょうか。検討委員会で選択制は見直すべきだ等の意見が出た場合は、区は検討課題に入れる考えがあるのでしょうか、伺いますとの意見を述べました。","respondent":"勝亦学務課長","answer":"平成２８年度に行いました、ブロック制から隣接選択制へと地域に密着した形で、存在意義があるという形で答申も出てあります。そういった意味で、学校選択制の廃止については、現段階のところでは考えてございません。","id":"exchange-019"},{"speaker":"安藤委員","kind":"提案","question":"小・中学校の３０人学級を想定して検討する、最低でも中学校の３５人というものを、やはり想定して検討すべきではないでしょうか。その上で、国を待たずして、区の独自教員も充てて、区としてそれを実施するよう求めたいと思いますけれども、いかがか尋ねました。","respondent":"勝亦学務課長","answer":"そういった意味で、３０人学級の想定は現在のところは予定してございません。品川区では、学級規模を縮小するために区固有教員を採用しているという形ではございませんので、こちらも採用することは難しいかなと考えています。","id":"exchange-020"},{"speaker":"安藤委員","kind":"質問・要望","question":"やはり先を見通した検討が求められると思いますし、整えるということが教育委員会の最大の使命ですので、ぜひ検討をよろしくお願いしたいと思います。今年度も残り僅かですが、２０２２年度の数字、傾向、どうなのか分かる範囲で伺いたいと思います。","respondent":"勝亦学務課長、矢部教育総合支援センター長","answer":"中学校の３５人学級のお話ですけれども、今、法律の中では４０人学級というように定めがありますので、それにのっとって検討を進めてまいりたいと考えています。 昨年度、令和３年度、２０２１年度につきましては、小学生が２２２人、中学生が２７０人です。今年度につきましては、若干増加傾向です。","id":"exchange-021"},{"speaker":"安藤委員","kind":"質問・要望","question":"ちょっと伺いたいのですけれども、不登校ぎみの子どもが登校を希望した場合、きちんと給食を提供してあげるということは可能になるのでしょうか。もういつでも給食を食べに来てください、来なよという、そのような学校にしていただきたいのですけれども、いかがか尋ねました。","respondent":"勝亦学務課長","answer":"来年度から公費のほうで負担する中で、不登校の方、学校にいらっしゃらないものというような形での対応は取ってございません。在籍されている方の給食は、しっかり用意していきたいと考えています。","id":"exchange-022"},{"speaker":"安藤委員","kind":"質問・要望","question":"これも公開するべきだと思うのですけれども、いかがでしょうか。以上３点伺います。","respondent":"矢部教育総合支援センター長","answer":"１２月に示された生徒指導提要ですが、文書のとおり、ホームページ掲載を４月中に行うように指示をしたところです。新しい教員も子どもたちも、同じようなスタンスでスタートを始めようですので、本当にベーシックなところの指示です。","id":"exchange-023"},{"speaker":"安藤委員","kind":"質問・要望","question":"２０２０年度の予算特別委員会で、児童・生徒の意見を聞いて校則の見直しを求めたのですが、品川区教育委員会が以下のように答弁しているのです。だとしたら、私は、こうした姿勢で子どもの考える力や自治の力が育つとはちょっと思えないのですけれども、いかがか尋ねました。","respondent":"矢部教育総合支援センター長","answer":"子どもたちが自分たちで考えて、校則について変えているところもありますし、そこでもかなり校則のことは学校の中でも話し合っております。地域の方にご意見をいただいていると聞いておりますので、そのような事例を広げていければいいなと考えております。","id":"exchange-024"},{"speaker":"安藤委員","kind":"質問・要望","question":"ルールを守ることも大切かもしれないですけれども、なぜこのルールなのだろうなと考えてもらいたい。どのようなルールがいいのだろうかということ、これをみんなで考えて変えていくと、その力を育ててほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"},{"speaker":"松永委員","kind":"質問","question":"初めに、３６７ページのいじめ等防止プログラム経費について伺います。この予算は、いじめ啓発のために生徒皆さんがバッジを作るという事業だとお聞きしておりますが、教職員の皆さんも一緒に参加されているのか尋ねました。","respondent":"矢部教育総合支援センター長","answer":"いじめ根絶バッジのご質問だと認識しました。令和５年度の予算につきましては、教員とともに生徒会等、子どもたちも話し合って進めている事業です。","id":"exchange-026"},{"speaker":"松永委員","kind":"質問・要望","question":"生徒も、先生も使われているということでよろしいでしょうか。１つのものをつくり上げるという方法も、多く授業に取り入れていただきたいと思うのですが、本区の考えを示すよう求めました。","respondent":"矢部教育総合支援センター長","answer":"１年間に１回ですが、そのようなことも取り組んで、またいじめの防止に努めております。ほかのお友達の相談に乗ってあげるとか、またはポスターを掲示したり、そのようなことでいじめ防止の啓発をしている学校もあります。","id":"exchange-027"},{"speaker":"松永委員","kind":"確認","question":"これまで８回、令和２年を除き、毎年行われてきたかと思いますが、この令和４年に行われた協議内容を確認させていただきました。このいじめ根絶協議会にはＨＥＡＲＴＳの皆さんはいらっしゃるのか尋ねました。","respondent":"矢部教育総合支援センター長","answer":"ＨＥＡＲＴＳの活動につきましては、少しお時間いただいている間に調べます。いじめ根絶協議会につきましては、ＨＥＡＲＴＳの参加はあります。","id":"exchange-028"},{"speaker":"松永委員","kind":"質問・要望","question":"これは３月１３日より、給食等も含めてですけれども、どのように対応されるのでしょうか。本区内には、そうしたお子さんはおられるのか尋ねました。","respondent":"矢部教育総合支援センター長","answer":"３月中はこれまでどおりですので、品川区の感染防止、新型コロナウイルスの感染症予防ガイドラインに沿って対応しています。来年につきましては、特別支援については特に強化しながら進めてまいりたいと考えておりますので、強化して推進してまいりたいと考えております。","id":"exchange-029"},{"speaker":"松永委員","kind":"確認","question":"先ほどの令和４年のいじめ根絶協議会の内容についてですが、ヤングケアラーの支援については先日確認させていただきましたので大丈夫です。本区において、この不登校になってしまった子どもたちはどのくらいおられたのか、改めて伺いたいと思います。","respondent":"矢部教育総合支援センター長","answer":"大きく３つに分かれておりまして、学習不振、学力不振ですね。そちらと、もう一つがいじめ以外の人間関係です。","id":"exchange-030"},{"speaker":"松永委員","kind":"質問・要望","question":"例えばＰＴＡにもそうした周知をしていただきたいと考えておりますが、いかがでしょうか。何か成果というか、このような子どもですよというように書いていただけるというお話を伺ったのですが、その辺について伺いたいと思います。","respondent":"矢部教育総合支援センター長","answer":"地域の方が入っていらっしゃる会議がありますので、その辺りでもご意見いただければ、学校でできることはあるかなと考えております。ぜひ書くというような認識でおりますので、例えばいろいろな活躍をされたお子さんであれば、当然記入になります。","id":"exchange-031"},{"speaker":"松永委員","kind":"質問","question":"次に、３６７ページの学校夜間電話対応経費と、３７７ページの学校職員について伺いたいと思います。中学校、義務教育学校前期課程、義務教育学校後期課程を教えてほしいと求めました。","respondent":"中谷指導課長","answer":"現在の教員の欠員状況です。義務教育学校前期課程が１名、義務教育学校後期課程が１名、合計しまして１５名というところになっております。","id":"exchange-032"},{"speaker":"松永委員","kind":"質問","question":"そうした欠員で、教育に影響は出ないのでしょうか。もう時間がないので、最後にこうした先生の募集について、どのように行われるのか尋ねました。","respondent":"中谷指導課長、矢部教育総合支援センター長","answer":"東京都の教員を補充するという考え方なので、いつから教員ができる、そういった情報をうまく活用しながらやっているです。引き続きそのような取組を、進めてまいりたいと思います。 個人面談は、スクールカウンセラーのほうが５３０件、ＳＳＷのほうが１,３４３件です。すみませんでした。","id":"exchange-033"},{"speaker":"澤田委員","kind":"質問","question":"３６７ページ、３７３ページ、順不同でお伺いいたします。市民科・各教科充実経費の中の地域の歴史・文化学習として、現在どのような取組を行っているのか尋ねました。","respondent":"矢部教育総合支援センター長","answer":"こちらは地域の方をお招きして、地域理解を深めることを目的として、行っている事業です。学校に地域の方を招聘して、まちのこれまでの歴史や文化などをご指導いただいている、そのような事業です。","id":"exchange-034"},{"speaker":"澤田委員","kind":"質問","question":"地域の方や町会長などをお招きして、お話を伺うということは分かりました。どなたが、またどのようにして、講師を選定していらっしゃるのか尋ねました。","respondent":"矢部教育総合支援センター長","answer":"講師の選定につきましては、もう本当に昔からいらして、本当に地域のことをよくご存じの方にお願いしています。本区につきましては、その方たちからも情報を得ながら、講師を選定していると認識しております。","id":"exchange-035","title":"町会・自治会支援"},{"speaker":"澤田委員","kind":"意見","question":"地域で実際に生きてこられて詳しい方というか、聞く側の子どもたちの心にも響くと思いますので、ぜひ今後とも続けていただけたらと思います。歴史学者など研究者の方のお話を聞く機会というものもあってもいいのかなと考えますが、区としてのご見解を説明するよう求めました。","respondent":"矢部教育総合支援センター長","answer":"あくまで地域の方、少なくとも区内の方にお願いしたいので、大学の方など、本当にたけた方がいらっしゃれば、ぜひお願いしたい事業です。","id":"exchange-036"},{"speaker":"澤田委員","kind":"質問・要望","question":"市民科や社会科などの授業で、地域の歴史・文化学習として、例えば小学校在学中に一度は必ず品川歴史館に行くということはいかがでしょうか。リニューアル以前にも、品川歴史館へは学びに行かれていたのか尋ねました。","respondent":"矢部教育総合支援センター長","answer":"特に小学校３年生の学習の中に、そちらに関わって、今までも社会科見学の候補地になってございました。当然令和６年度からも、現状でも品川歴史館とは連携して、子どもたちの学習に役立てるような手だてを打ってあります。","id":"exchange-037"},{"speaker":"澤田委員","kind":"質問・要望","question":"続きまして、３７３ページの発達障害教育支援員配置についてお伺いします。増員できるように、様々な方法で発達障害教育支援員の方を募集しておられるとは思いますが、どのようなことを現在行っているのか尋ねました。","respondent":"矢部教育総合支援センター長","answer":"様々子どもたちの支援の人材がおりまして、今ご指摘の発達障害教育支援員の配置についてお答えいたします。今年度５校で実施してございまして、来年度はプラス１０校というように考えておりますので、定着できたらいいと今考えております。","id":"exchange-038"},{"speaker":"澤田委員","kind":"質問","question":"最後になりますが、３６７ページ、いじめ等防止プログラムについてお伺いします。様々な暴力から自分の心と体を守る、暴力防止のための予防教育プログラムが行われていますが、現在の実施状況を示すよう求めました。","respondent":"矢部教育総合支援センター長","answer":"委員がお話しのとおり、子どもたちが被害に遭わないということを前提に、全区内の区立学校の３年生を対象に実施しているものです。","id":"exchange-039"},{"speaker":"澤田委員","kind":"質問・要望","question":"ぜひ今後とも多くの保護者の方に受けていただき、理解を深めていただけますよう、拡充を要望いたします。現在小学校では、何校くらいが小動物を飼育していらっしゃるのか尋ねました。","respondent":"矢部教育総合支援センター長","answer":"現在、小学校で小動物を飼っている学校は、３７校中２２校です。","id":"exchange-040"},{"speaker":"澤田委員","kind":"質問","question":"１５校ぐらいですか、小動物の飼育を推奨していただければなと思うのですが、区としてのご見解をお伺いします。","respondent":"矢部教育総合支援センター長","answer":"小動物ではないかもしれませんけれども、金魚とか、メダカとか、ザリガニとか、蚕とか、そのような生き物についてはどこの学級でもやっていますので、ウサギやモルモットということでなければ、かなりの学校で定着している活動ではないかなと思っています。","id":"exchange-041"},{"speaker":"澤田委員","kind":"意見","question":"そうなのです。心臓がトクトク動くというような、子どもたちはそのような動物を抱っこしたりで大分違ってくると思うので、そちらのほうもぜひとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-042"},{"speaker":"田中委員","kind":"質問","question":"教育費全般で、スピーキングテスト、まもるっち、学校図書館、がん教育、宗教２世等に関する配慮を伺います。自己情報の開示は権利であるという認識が、区全体で少し薄いかなと感じるときがありますが、周知がされていると期待して伺います。","respondent":"中谷指導課長","answer":"実施後には、自分の力を出すことができたというような声をいただいております。１例というのは、無事に２回目を受けたということで、こちらに関しては滞りなく進められております。","id":"exchange-043"},{"speaker":"田中委員","kind":"質問・要望","question":"改善を求めますが、見解を伺います。区立学校以外に通う子どもへの活用周知についても、併せて伺います。","respondent":"宮尾庶務課長","answer":"セーフティ教室に関するお尋ねですが、こちらは警察のご協力をお借りして、登下校中の安全管理方法などを学ぶ教室だと認識しています。参加状況等については、教育委員会のほうでは把握しておりませんが、学校の希望に応じて教室を開催していると聞いてあります。","id":"exchange-044"},{"speaker":"田中委員","kind":"質問・要望","question":"改めて改善を求めるとともに、やはり２０１８年にも訴えましたが、まもるっちを所管するのは教育委員会にすべきと考えますが、見解を伺います。業者の選定や契約はプロポーザルなのかなど、伺いたいと思います。","respondent":"宮尾庶務課長、吉田品川図書館長","answer":"今でも生活安全担当のほうと連携を図りながら、いろいろ意見を出し合いながら、日々改善を図っているところです。このように、いろいろなところで適宜連携、協力をしておりますので、所管を教育委員会に移すという考えはございません。増額の理由としては、国の最低賃金の変更に合わせて、人件費の部分は増額したところになります。","id":"exchange-045"},{"speaker":"田中委員","kind":"確認","question":"現在、この状況は改善できたのでしょうか。１０年スパンで実現すると区も示している中で、計画を立てるべきと考えますが、見解を伺います。","respondent":"吉田品川図書館長","answer":"学校司書につきまして、職員室においてインターネットを使える端末で調べをしている状況については、このまま継続してまいります。今後は利用状況を踏まえ、研究してまいるところです。","id":"exchange-046"},{"speaker":"田中委員","kind":"質問・要望","question":"ですから、注意書についての周知こそ必要だと考えますが、見解を伺います。見解を伺います。","respondent":"矢部教育総合支援センター長","answer":"その方向でパンフレットの周知をしていますけれども、ただ、これも決して接種を強制するものではないという通知も一緒に出しています。きちんと配慮をして、しっかりおうちで判断、保護者と一緒に判断するような支援をしてまいりたいと考えております。","id":"exchange-047"},{"speaker":"田中委員","kind":"質問","question":"ぜひそういったことがないように、当事者の子どもが声を上げにくい環境がつくられてしまうということは非常に問題だと思います。見解を伺います。","respondent":"矢部教育総合支援センター長","answer":"この機会だけで全てを判断するというようには私どもは考えてございませんので、１つの知識として把握して、その後様々な、近くの関係者やご家族と相談して判断していただく、そのような力をつけていると認識しております。","id":"exchange-048"},{"speaker":"須貝委員","kind":"質問","question":"３６４ページ、教育指導費についてお聞きしたいと思います。毎年この品川区に、何名ぐらいの教員が入れ替わりで入っているのか尋ねました。","respondent":"中谷指導課長","answer":"小学校のほうの新規採用が３７名、そして区外からの転入という形ですけれども、１０３名となっています。中学校が、新規採用２０名、区外からの転入が３３名いらっしゃるというような状況になっております。","id":"exchange-049"},{"speaker":"須貝委員","kind":"質問","question":"Ａ、Ｂ、Ｃ、Ｄ、Ｅ、５つの段階で評価されていると思います。それにはなかなか応じてもらえず、逆に押しつけられてしまうような現状があると聞いておりますが、説明を求めました。","respondent":"中谷指導課長","answer":"その現状を見た上での、いかに次の見通しを持ってスキルを身につけさせていくかというところは、とても重要だと考えています。特別な支援を必要とする子どもへの対応、一人ひとりの教職員に応じたスキルを身につけていただくようにということでやってまいりたいと思います。","id":"exchange-050"},{"speaker":"須貝委員","kind":"質問・要望","question":"これは実際そろっているのですか、人数は。両方の免許を持っている方は品川区では実際何人で、もう充足率は相当いいのか尋ねました。","respondent":"中谷指導課長","answer":"固有教員のほうですけれども、こちらの採用についてはこれからも進めてまいりたいと考えています。教職人生の中でより一人ひとりの先生が伸びていくというところであると思いますので、そこをしっかり応援していきたいと考えています。","id":"exchange-051"},{"speaker":"須貝委員","kind":"質問","question":"３年たったら異動できる、では両方の免許を持っている方が品川区に来られて、３年たったら僕異動します、私異動しますと、そのようになってしまう。その辺についてどうか尋ねました。","respondent":"中谷指導課長","answer":"１つの免許を持っていて、全くそちらのほうの指導ができないということではないということは申し上げさせていただければと考えています。東京都のほうには、これからも、免許を２つ持っていらっしゃる方を採用したいということで、働きかけを継続的に行っていきたいと思います。","id":"exchange-052"},{"speaker":"須貝委員","kind":"質問","question":"先ほど欠員というお話もありましたが、教員の離職者、それで欠員になるのでしょうが、何人いらっしゃるのですか。このような実態に対して、どのようにお考えか尋ねました。","respondent":"中谷指導課長","answer":"先ほども申し上げたとおり、今現在の欠員状況は１５名という形になっております。ご家庭の事情というところも含めての、ご本人の総合的な判断というところでのご退職と捉えております。","id":"exchange-053"},{"speaker":"須貝委員","kind":"意見","question":"全部それにしてほしいです、本当は。私は非常に心配しているのですが、すみません、最後に何かご意見がありましたら言ってくださいとの意見を述べました。","respondent":"中谷指導課長","answer":"保護者の対応を、通常は勤務時間内にするのですけれども、勤務時間外に委託のほうで行うというようなこともよくできております。これからも引き続きやってまいりたいと思います。","id":"exchange-054"},{"speaker":"せらく委員","kind":"質問","question":"３７１ページ、マイスクール運営費について、３７９ページ、学校システム運営費に関して質問します。ホームページの仕様が大きく変わるのかなと思いますが、まずこちら、スケジュールを伺います。","respondent":"勝亦学務課長","answer":"ホームページのＣＭＳの変更につきまして、ご予算をいただきまして、来年度中、早い段階でこちらに取り組みまして、秋頃には新しいホームページを立ち上げて、その検証に入っていきたいと考えています。","id":"exchange-055"},{"speaker":"せらく委員","kind":"確認","question":"改編の際にメニューの統一など、必要な情報についてはある程度統一感を持った形にする予定はありますでしょうか。伺います。","respondent":"勝亦学務課長","answer":"新しいＣＭＳに変えまして、できるだけ統一感のある表示にしてまいりたいと考えています。対象については、全ての区立学校を対象とする予定です。","id":"exchange-056"},{"speaker":"せらく委員","kind":"確認","question":"メニューのほう統一していただくということで、比較がしやすくなると助かる保護者も多いと思います。議事録でも少し確認できたのですが、または今まで難しかったところがこのように簡単になるなど、もし決まっているところがあれば示すよう求めました。","respondent":"勝亦学務課長","answer":"新しいものに関しましては、インターネット環境に接続できる端末であれば、更新ができるような形になってあります。操作性が難しいという部分がございましたので、通常の変更のメニューと簡単に更新ができるようなメニュー、それぞれ用意したいと考えています。","id":"exchange-057"},{"speaker":"せらく委員","kind":"質問","question":"お友達と別の学校になると、なかなか情報がないまま入学する方も多いと、この間校庭開放の当番になったときに友人と話していました。学校のホームページの運用の方向性までサポートする講習など、せっかくの機会なのでしたほうがいいかなと思うのですが、いかがか尋ねました。","respondent":"勝亦学務課長","answer":"現在のホームページになかったヘルプデスクというものを設けまして、学校現場からの問合せ等に柔軟に対応できるようにしてまいりたいと考えています。","id":"exchange-058"},{"speaker":"せらく委員","kind":"質問・要望","question":"学校の様々な日常の活動が、インターネット上で確認できるといいと思います。不登校特例校は、図書館だった施設をリニューアルした校舎なので、運動場がなく部活がないといった要望の声もありました。","respondent":"矢部教育総合支援センター長","answer":"全体指導というよりは個別指導になりまして、そのお子さん一人ひとりの進捗や心身の状態を鑑みまして、支援をしています。卒業に向けましても、昨年度は全て９年生、進路が決まってありますので、特例校と大きく差のない対応をしていると考えております。","id":"exchange-059"},{"speaker":"せらく委員","kind":"質問","question":"在籍校が別にあるというところで、例えば責任の所在をめぐるトラブルなどはありませんでしたでしょうか。職員も、元校長先生や教員免許を持つ経験者がいらっしゃるということですが、個別指導ということで、担任制のような形などはしていないのか尋ねました。","respondent":"矢部教育総合支援センター長","answer":"まずお預かりしているのは在籍校ですので、連携をしていますので、マイスクールの情報は全て在籍校にお伝えしているという連携の仕方をしております。個別に来たお子さんについて、大体ＡさんだったらＢ先生というような形で、個別に対応している。","id":"exchange-060"},{"speaker":"せらく委員","kind":"質問・要望","question":"小学校１年生、２年生が対象となっていないというところで、そういったご相談も柔軟に対応していただきたいと考えています。浜川校が教室拡充ということですが、小学生のほうの不登校児童も増えてきていると思いますので、そちらのほうも見てほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-061"},{"speaker":"西村委員","kind":"質問","question":"３７７ページより、学校ＩＣＴ活用経費から情報リテラシー教育について伺ってまいります。学校でのネットリテラシー教育について、改めて小学校と中学校でそれぞれどのように行われているのか説明を求めました。","respondent":"矢部教育総合支援センター長","answer":"４年生になりますと、５年生から７年生につきましては、コミュニケーションを上手に取るルールとマナーなどを指導しております。８年生、９年生につきましても、このような事柄で指導をしています。","id":"exchange-062"},{"speaker":"西村委員","kind":"意見","question":"勘違いとか、誤解とか、いろいろな情報がネットの中にあります。この日本のメディアリテラシー教育が世界に遅れを取っていると言われているのはなぜなのか、また、区の考えを改めて説明を求めました。","respondent":"矢部教育総合支援センター長","answer":"このタブレットが１人ずつ入ったということはとても大きなところでございまして、また生活指導に至るまで、私たちも協議してきたところです。","id":"exchange-063"},{"speaker":"西村委員","kind":"質問・要望","question":"分からないながらも、自分の中から一生懸命答えを導き出したような答えは一生忘れないと思いますので、ぜひ取り組んでほしいと求めました。一度投稿した情報は完全に削除できないというようなことを教えていただきながら、使用の制限だけをするのではない、ご意見を説明するよう求めました。","respondent":"矢部教育総合支援センター長","answer":"情報モラルにかかわらずではありますけれども、そのような話し合い活動は進んでいます。その時と場合、また内容によって、その都度教員のほうが指導していくということは大変効果的だと考えております。","id":"exchange-064"},{"speaker":"西村委員","kind":"質問・要望","question":"閲覧が長過ぎる児童への指導や、家庭教育などを行っていることがあればお知らせほしいと求めました。ご意見説明を求めました。","respondent":"勝亦学務課長","answer":"は家庭の中に学習アプリ等がありますので、そういった調べですとか、そういったアプリを使った学習に活用できるかなと考えています。そういった方については、学校を通じて、ご家庭のほうへ指導、ご協力、家庭でのルールづくり等をお願いしている状況です。","id":"exchange-065"},{"speaker":"西村委員","kind":"質問・要望","question":"引き続き、何かのアラームかなというような視点も私は持っていたいと思いますので、よく見てあげてほしいなと思います。現状の中学生たちのＬＩＮＥですとか、ＳＮＳの活用について、何か現況があれば説明を求めました。","respondent":"勝亦学務課長、矢部教育総合支援センター長","answer":"現状では、そういったＳＮＳ等は、ＧＩＧＡスクール端末の中では使えないようになっているという状況です。学校はタブレットのほうを活用するということですが、生徒、中学生以上はスマートフォンの所持率が高いというふうに認識しています。","id":"exchange-066"},{"speaker":"横山委員","kind":"質問・要望","question":"１点目に、保健運営費についてお伺いいたします。既に倒れているケースがありますが、心停止してからの１０分間が大切なので、すぐにＡＥＤを取りに行くことが求められています。","respondent":"勝亦学務課長","answer":"ＡＥＤにつきましては全校設置済みでございまして、５分以内にこういった対応ができるように、新たに追加配備を予定しているものです。そういった形で、設置場所につきましても、玄関ですとか、入り口の事務室の前ですとか、分かりやすいところに設置している状況です。","id":"exchange-067"},{"speaker":"横山委員","kind":"質問・要望","question":"ＡＥＤの適切な使用方法について定期的に伝えていただきたいということを要望いたしますが、品川区教育委員会のご見解をお聞かせください。子どもたちがスマホなどで盗撮されているのを見かけた際に、大人としてどのような行動を取ることが適切なのか尋ねました。","respondent":"勝亦学務課長、矢部教育総合支援センター長","answer":"もしくは、その講習を受けて専門的な知識を持った方が教員に教えるといった形で、認識は深めてあります。そういったＡＥＤの設置状況ですとか使用方法につきましても、毎年、例えば学校だより等を通じまして… そのようなことも案内をしていますので、都度、学校のほうで助言ができるかなと考えております。","id":"exchange-068"},{"speaker":"横山委員","kind":"質問","question":"３点目に、就学援助費についてお伺いいたします。はコロナ禍において、そうした機会を経験することができなかった児童・生徒の、当時の学年と現在の学年を簡単に説明を求めました。","respondent":"勝亦学務課長、矢部教育総合支援センター長","answer":"令和３年度につきましても、多くの５年生、６年生、７年生の移動教室が実施できない状況でございました。令和３年度につきましては、修学旅行は実施できているという状況です。 令和３年度の修学旅行については、若干行けなかった学校もあります。訂正いたします。","id":"exchange-069"},{"speaker":"横山委員","kind":"質問・要望","question":"先生方の負担ですとか様々、現実的に難しい部分があるというのは分かっています。検討というか、考えていただくということだけはしていただきたいと思っていますが、品川区教育委員会のお考えをお聞かせくだい。","respondent":"勝亦学務課長","answer":"６年生、それから８年生につきまして、移動教室に行けなかった方に代替事業を実施しています。そういった中で、または思い出づくり事業、そういった代替事業をできるだけリアルタイムで実施してきているところです。","id":"exchange-070"},{"speaker":"あくつ委員","kind":"質問・要望","question":"いよいよこの４月、開けやすく、昨年の決算特別委員会で確認させていただいたところです。つい先日この要領が改正されましたが、品川区の教育委員会はご存じか尋ねました。","respondent":"勝亦学務課長","answer":"牛乳の供給に関する要領の改訂についてです。今、委員がおっしゃっていただいた第２条のところに、環境配慮の取組を積極的に実施している者という項目が追加されていると認識しています。","id":"exchange-071"},{"speaker":"あくつ委員","kind":"質問・要望","question":"持続可能な社会の実現が求められる今、決定し、都内全域に学校給食におけるプラスチックストローの削減を波及させていくべきではないでしょうか。都教育委員会は、業界の動きが一層広がるよう国に要領の改正を要望するとともに、価格競争の実施時に環境への配慮も併せて確認するなど。","respondent":"勝亦学務課長","answer":"令和５年度の、品川区への牛乳の供給事業者は、雪印メグミルクになったと聞いてあります。","id":"exchange-072"},{"speaker":"あくつ委員","kind":"質問・要望","question":"２０１８年、プラスチックストロー削減を求める請願が全国で初めて品川区議会で提出されて、都内全てで適用されるという決着になりました。前にも確認しましたが、ＣＯ２も年間約４.７トンの削減効果が得られるということは、何度かこの委員会でも確認しました。","respondent":"勝亦学務課長","answer":"こちらのＳｃｈｏｏｌ ＰＯＰへの容器の変更につきまして、雪印メグミルクから変更に当たって、いろいろご相談をいただいておりました。","id":"exchange-073"},{"speaker":"あくつ委員","kind":"質問・要望","question":"次に、学事制度審議会について伺います。２年前に改築されたばかりの城南小学校ですが、この夏休みに大規模な改修工事を行うと伺いましたが、どのような工事になるのか示すよう求めました。","respondent":"勝亦学務課長","answer":"令和５年度に向けまして、城南小学校の工事です。教室に変更していく、３階の算数少人数教室、こちらも普通教室に転用していく予定になってあります。","id":"exchange-074"},{"speaker":"あくつ委員","kind":"質問","question":"３クラス分増やすということでしょうか。区内で３つ目、この城南小学校で導入されるというお話も伺いましたけれども、げた箱があったスペースも活用すると聞いています。","respondent":"勝亦学務課長","answer":"学事制度審議会につきましては、年度が改まりまして、予定といたしましては７月頃には最初の審議会を開催したいと考えています。具体的には、学識経験者の方お二人、区民の方７名、学校の代表２名という形で、１１名で構成していきたいと考えています。","id":"exchange-075"},{"speaker":"あくつ委員","kind":"質問・要望","question":"お考えになってやられていると思うのですが、途中経過で、その都度出せる情報を出していくというやり方もあります。できるだけ影響が少ないような方法を常に模索していただきたいと思うのですけれども、この点、お考えを説明するよう求めました。","respondent":"勝亦学務課長","answer":"手法はこれから検討してまいりますが、パブリックコメントですとか、そういった方法も考えられると思います。そういったお声をいただきながら、慎重に考えていきたいと考えております。","id":"exchange-076"},{"speaker":"おくの委員","kind":"質問・要望","question":"そこで、憲法２６条に「義務教育は、これを無償とする」とあるとおりに、給食費以外の学用品なども無償化することを求めますが、いかがでしょうか。学用品等を無償化することも、この理念に沿って行うべきだと思いますけれども、いかがか尋ねました。","respondent":"勝亦学務課長","answer":"義務教育の無償化、委員のおっしゃった憲法２６条の義務教育の無償につきましては、基本的には授業料の無償であると捉えられてあります。","id":"exchange-077"},{"speaker":"おくの委員","kind":"質問","question":"では、そういう授業料だけだということであれば、学校給食費の無償化の説明がつかなくなると思いますけれども、いかがか尋ねました。","respondent":"勝亦学務課長","answer":"学校給食費につきましても、基本的には、食材料費は保護者の方の負担というのが、法律、それから考え方の立てつけとなっています。子育て世帯の負担を軽減していく、「子育て・教育で選ばれるしながわ」をつくっていくのだという考えの下に、無償化を行っているです。","id":"exchange-078"},{"speaker":"おくの委員","kind":"質問","question":"そういう視点であるならば、学用品等を無償化しない理由は一体どういうことになるのでしょうか、伺います。お伺いいたします。","respondent":"勝亦学務課長","answer":"支援の形もいろいろございまして、ご負担を軽減していく中で、給食費というものを無償化しようと考えたという判断です。","id":"exchange-079"},{"speaker":"おくの委員","kind":"質問","question":"その理由は何なのかとお伺いしたのですが、今のではお答えになっていないように思われるのですが、いかがでしょうか。もう一度お答え願いたいと思うのですが。","respondent":"勝亦学務課長","answer":"ご支援の中で、まず給食費を無償化していくという考え方です。そういったものに非常に重要なものですので、まず一番大事な食、こちらを無償化していくという考え方です。","id":"exchange-080"},{"speaker":"おくの委員","kind":"質問","question":"それから、もう一つ、昨年お伺いしましたときには、学校給食費も含めて無償にするためには、費用は２３億円かかると答弁いただきました。１０億円、１２億円、いかがか尋ねました。","respondent":"勝亦学務課長、矢部教育総合支援センター長","answer":"そういった中で、一歩踏み出すということで、体ですとか健康のベースとなる食、給食の無償化、こちらを品川区で進めていくという考え方です。個人のお手元に残ったり、個人に還元されたりする性質のものですので、基本的には… 教育総合支援センター所管のもので、自作で、区独自で教材を作成、配布しているものがあります。社会科で「調べ・考え・社会をつくる」という参考資料、それぞれ独自の教材も配布いたしまして、家庭の負担を少しでも軽減しています。","id":"exchange-081"},{"speaker":"おくの委員","kind":"質問","question":"将来、これから先、その点をお伺いしたいと思います。いかがか尋ねました。","respondent":"勝亦学務課長","answer":"今後につきましては、教育委員会、それから区全体の中で、支援の在り方について考えていく考えです。","id":"exchange-082"},{"speaker":"おくの委員","kind":"質問・要望","question":"義務教育の完全無償化を求めて、質問を終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-083"},{"speaker":"松澤委員","kind":"質問","question":"予算書３６７ページ、プレスのほうで学校トラブル相談体制の強化というのがあったので、そこについてお聞きします。心のケアというのですか、そこら辺が少し分からなかったので、ご説明をお願いします。","respondent":"宮尾庶務課長","answer":"令和５年度の当初予算案に学校トラブルの相談委託ということで、１３０万円余の予算を計上しています。的確に対応するために、我々事務局がさらに多角的なアドバイスをいただく必要があると考えまして、こういうものです。","id":"exchange-084"},{"speaker":"松澤委員","kind":"質問","question":"ＨＥＡＲＴＳですかね、実際これは何人で、年間３６０時間の勤務時間をどのように割り振っているのか。重点措置として、年間１２０時間加算申請することができると書いてありましたが、実際そのようなケースがあったのか、説明を求めました。","respondent":"矢部教育総合支援センター長","answer":"週４日勤務、年間約１,６００時間という数で、専門家が６名おります。家庭訪問を実施して、関係機関が出席するケース会議などに参加している、そのような活動です。","id":"exchange-085"},{"speaker":"松澤委員","kind":"質問","question":"設置していくことで、子ども一人一人の生活の質、要はＱＯＬを高めていけるのではないでしょうか。今はＨＥＡＲＴＳにいらっしゃいますけれども、これからどんどん拡充していく、そういった取組についてのご見解を説明するよう求めました。","respondent":"矢部教育総合支援センター長","answer":"少しずつここ数年、予算をつけていただきまして、広げているところです。ぱっと広げれば成果が出るとは思いませんので、一つずつ丁寧に対応しながら、どういう形がいいのかということで少しずつ広げていく、そんな予定です。","id":"exchange-086"},{"speaker":"松澤委員","kind":"質問","question":"今、福祉、医療につなげるというお話が少し出ましたけれども、例えば品川区では、そういうスクールソーシャルワーカーというのがどういうふうにつないでいくのか、その仕組みというのですかね、その仕事を少し詳しく説明を求めました。","respondent":"矢部教育総合支援センター長","answer":"様々なケースがあるのですが、特に不登校のお子さんの対応が多くなっています。そのようなところにつないで、子どもの環境をよくする、そのような仕事をしています。","id":"exchange-087"},{"speaker":"松澤委員","kind":"質問","question":"そうすると、やはりその家庭に何かがあるかもしれないというのですかね。１校に１人ではないですけれども、そういった部分の幅広い拡充というのを、もう一度力強い答弁でお願いいたします。","respondent":"矢部教育総合支援センター長","answer":"ＨＥＡＲＴＳはＳＳＷだけではなくて、心理や警察ＯＢや指導主事が入っているというところが特徴です。はその家庭の背景への支援について、子どもや保護者を支援していくと、一歩一歩進めてまいりたいと思います。","id":"exchange-088"},{"speaker":"松澤委員","kind":"質問・要望","question":"スクールソーシャルワーカー、そしてスクールカウンセラー、養護教諭が担う役割というのを、お話のとおりしっかりと明確化して、それぞれの強みを生かしながら、協働して包括的に課題解決に取り組むことを再度要望しまして、質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-089"},{"speaker":"せお委員","kind":"質問・要望","question":"私からは、３８３ページ、学校給食費無償化、そして、庶務課の学校運営費、３７３ページ、発達障害教育支援員配置についてお伺いします。東京都全体で支援していただきたいという要望を、何かの機会に区からもお伝えしていただきたいですが、見解を説明するよう求めました。","respondent":"勝亦学務課長","answer":"特別な医療的な対応をされている方、できるだけ公平な形で対応できるように、手法を検討していきたいと考えています。そういった中で、支援の拡充について、東京都への要望等についても検討していきたいと考えています。","id":"exchange-090"},{"speaker":"せお委員","kind":"質問・要望","question":"そのような課題が子どもたちの身近に起こっているわけですから、せっかくですから環境学習として。見解を説明するよう求めました。","respondent":"宮尾庶務課長","answer":"それぞれどんな形態であれ業務内容に変わりがないように、統一の仕様でやらせていただいております。もろもろ状況が違うところはありますが、基本的な考え方としては、学校によって差が出ないように統一を図っているところです。","id":"exchange-091"},{"speaker":"せお委員","kind":"質問・要望","question":"この状況で東京都教育委員会は、いわゆる発達障害のお子さんに対してどのような支援を目指しているのでしょうか。どのようなビジョンなのか、ご存じのところがありまたら説明を求めました。","respondent":"矢部教育総合支援センター長","answer":"やはり１年間のスパンで、今までは１年生から６年生までいられたお子さんもいるのですけれども、１年で退室を目指すです。普通の通常の学級から１時間、２時間、そういったことで１年間と捉えております。","id":"exchange-092"},{"speaker":"こんの委員","kind":"質問","question":"例えば５年生は、教材費として１万８０００円強ぐらいかかっているというところですが、どれぐらいご負担いただいているのでしょうか。参考までに伺います。","respondent":"勝亦学務課長","answer":"１校１校の詳細な内訳を把握している状況ではございませんけれども、就学援助で一定程度、平均的な金額を負担しています。小学校１年生ですと、教材費で大体１万円から２万円程度、２万円から３万円程度をご負担いただいている状況です。","id":"exchange-093"},{"speaker":"こんの委員","kind":"意見","question":"今、取り上げました教具ですけれども、小学校６年間の中で二、三年しか使用しないものもあります。学校が購入する教材としていただいて、教材費の負担軽減をというお声があるのですが、こうしたお声について区のご見解を説明するよう求めました。","respondent":"勝亦学務課長、矢部教育総合支援センター長","answer":"例えば顕微鏡、そういったものについては、やはり公的な部分で工面していくというところが基本になろうかと思います。個人のものとして手元に残せるもの、もしくは個人に還元していくものは… 前に使っていたものを１階の算数のお部屋に置いて、工夫としてはありますので、そういうことはできるのではないかなと思っています。","id":"exchange-094"},{"speaker":"こんの委員","kind":"質問・要望","question":"現在、品川区においてこの点検はどのようにされていて、点検表というのはどういう状況になっているのですか。お伺いします。","respondent":"矢部教育総合支援センター長、森学校施設担当課長","answer":"そこを月１回点検して、事務を含めてすぐに対応すると、そんな形で安全点検をしております。 それから、樹木についても点検をしておりまして、今年度は樹木診断を行いました。学校の施設・設備による死亡事故、そもそも事故等が発生しないようによく確認しています。","id":"exchange-095"},{"speaker":"こんの委員","kind":"質問","question":"この点検ですけれども、担任の先生がされるのでしょうか。それとも、これはきちんと専門家が点検するのか、その辺を説明するよう求めました。","respondent":"矢部教育総合支援センター長、森学校施設担当課長","answer":"学校のほうは教職員です。 建築基準法に基づく点検につきましては、専門家が行っております。なおかつ我々も行って、再度点検を行い、状況によっては… 追加です。コミュニティ・スクールでは、委員の方々に、皆さんの目でも点検をということで、お願いしています。","id":"exchange-096"},{"speaker":"こんの委員","kind":"質問","question":"細かく点検表でこことあそことというふうに、いわゆる視点を持っての、そういう点検表ということでよろしいでしょうか。より細かく点検できるようにしておくことが大事かなと、視点を持って見ることが大事かなと思うところですが、何かご答弁がありましたらお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-097"},{"speaker":"こんの委員","kind":"質問","question":"現在、品川区では、既にこうした、いわゆる訪問指導という形で実施をしていると理解しておりますが、その理解でよろしいでしょうか。現在の指導体制と実施の状況も示すよう求めました。","respondent":"矢部教育総合支援センター長","answer":"全ての学校に特別支援教室がございまして、または数人での指導を、ソーシャルスキルを含めてしています。そのような機能をしているところが特別支援教室で、訪問校を週１回程度回って、そのような形になっております。","id":"exchange-098"},{"speaker":"こんの委員","kind":"確認","question":"そうすると、私の理解をまた確認したいのですが、それは品川区としてはもう既にしているという理解でよろしいのでしょうか。確認したいと求めました。","respondent":"矢部教育総合支援センター長","answer":"ただいまご説明いたしました特別支援教室につきましては、東京都の方針に基づいて、全ての小・中学校で品川区においては行っております。","id":"exchange-099"},{"speaker":"こんの委員","kind":"質問・要望","question":"既に品川区として進めてくださっているということが確認できました。いろいろな細かいご要望をお受けいたしますが、どうか引き続きこの体制で、品川区の教育を進めてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-100"},{"speaker":"芹澤委員","kind":"質問・要望","question":"３６７ページのいじめ防止対策費、３６９ページ、学校２０２０レガシー事業、時間があれば、３８３ページの学校維持管理費についてお伺いします。そのような感想もあって、ぜひこういった事業もこれから再開していただきたいなと思うのですが、まずご見解を説明するよう求めました。","respondent":"矢部教育総合支援センター長","answer":"当初おっしゃった自己肯定感につきましては、日本人の奥ゆかしさなども言われておりますので、そこも大切にしながら育ててまいりたいと思います。小動物については、それらの活動の一つとして、様々な活動の中で、子どもたちのよりよい心の醸成を図っていきたいと考えております。","id":"exchange-101"},{"speaker":"芹澤委員","kind":"質問・要望","question":"関連してになりますが、オリンピック・パラリンピックについてもお伺いします。まさにレガシーとして、ぜひこれから拡大していってほしいと求めましたが、ご見解を説明するよう求めました。","respondent":"中谷指導課長","answer":"スポーツ推進課との連携の中で実現できまして、近くの大井ホッケー競技場に徒歩で行って見ることができるということになっておりました。東京都教育委員会からのご案内も集めて、学校のほうに周知をして、参加を促していきたいと考えています。","id":"exchange-102"},{"speaker":"芹澤委員","kind":"質問・要望","question":"全くスポーツに関心のなかった子どもたちが、それを見て、こんなにスポーツって面白いのだなというのをぜひ感じていただきたいという思いです。そこの費用をどうするのだという問題は出てくると思いますが、最後、ご見解を説明するよう求めました。","respondent":"中谷指導課長","answer":"既に実施している学校もありますので、これを共有する予定ですので、子どもを成長させることができるようにしてまいりたいと思います。","id":"exchange-103"},{"speaker":"芹澤委員","kind":"質問","question":"最後に、学校維持管理費の中から人工芝について、今お話があったので、最後に伺いたいと思います。ある程度学校のほうで予算化できないかなと思って、最後、ご意見を説明するよう求めました。","respondent":"森学校施設担当課長","answer":"委員のおっしゃるとおり、今後はこの人工芝と、お祭りであったりそういう集会と、どう一緒にやっていくかというのは課題になってくると思います。養生材等がいろいろありますので、その辺を踏まえながら、様々検討していきたいと考えています。","id":"exchange-104"},{"speaker":"のだて委員","kind":"質問","question":"私からは、３６０ページの教育費全般に関わって、産休・育休代替が埋まらない教員不足について伺います。日経新聞の調査では、欠員が夏休み明けに増えたということで報道しているのですけれども、品川区の状況を伺います。","respondent":"中谷指導課長","answer":"そのうち代替の教員で補充できた数が６９名、そして、時間講師の任用ができた数が４名、現在未補充という状況が６名ということになっております。必要数が２２名、そのうち代替教員で補充済みのものが１９名、未補充が３名という状況です。","id":"exchange-105"},{"speaker":"のだて委員","kind":"質問・要望","question":"区として加配を要望した人数と、実際に配置予定の人数を伺います。こうした仕組みも活用して、来年度は、年度当初から欠員が出ることがないようにしてほしいと求めましたが、いかがか尋ねました。","respondent":"中谷指導課長","answer":"夏に特に集中したという傾向はございませんで、年間を通して比較的散在するような形での欠員ということになっております。そして、令和５年度の状況というところはまだ調整中なので、正確な数が出ないということをご承知おきいただければと思います。","id":"exchange-106"},{"speaker":"のだて委員","kind":"質問・要望","question":"来年度はまだ精査中ということですが、そうすると、国が出した事務連絡で、加配を要望していないということなのか、伺います。","respondent":"中谷指導課長","answer":"最大で４か月前に加配という形で、一定期間ご一緒に働くということが可能になるもので、丁寧な引継ぎなどができるものと考えております。ただ、現在まだその申請を集めている段階だということを、ご承知おきいただければと思います。","id":"exchange-107"},{"speaker":"のだて委員","kind":"質問・要望","question":"これを活用して、来年度、欠員が出ないようにしていっていただきたいと、これは強く要望しておきたいと思います。管理職と一般の教職員が話し合う場をつくって、学力テストや研修など不要不急の業務削減を求めますが、いかがか尋ねました。","respondent":"中谷指導課長","answer":"その副校長補佐を配置する学校に、働き方改革推進部というのを設置していきたいと考えております。確実に、もっと時間の中で心の余裕を持ちながら、子どもと接することができるということにつなげていきたいと考えています。","id":"exchange-108"},{"speaker":"のだて委員","kind":"質問・要望","question":"今年度の特別支援教室の欠員は何人いるのか、伺います。東京都に特別区として要望しているとのことでしたけれども、要望した結果はどうなったのか、いかがか尋ねました。","respondent":"中谷指導課長","answer":"１つ目のご質問の、欠員状況があるのかということですけれども、小学校の特別支援教室で１校、お一人、今欠員がある状況です。２つ目としまして、欠員があるという状況に関して、ぜひ柔軟な対応をお願いしたいということを申し上げているところです。","id":"exchange-109"},{"speaker":"木村委員","kind":"質問・要望","question":"どうぞ頑張ってほしいと求めました。８３運動をさらに近隣区や都内で広げていくべきだと考えますけれども、また取組などはどのようになっているのか、お聞かせほしいと求めました。","respondent":"宮尾庶務課長","answer":"それから、近隣区等へ広げていくという考え方ですが、運動は広がりを見せていると認識しています。今後は、ＰＴＡなどと連携していきまして、啓発グッズの作成、広報紙への掲載など、引き続き周知等に努めていきたいと考えています。","id":"exchange-110"},{"speaker":"木村委員","kind":"質問・要望","question":"最近は、学校が終わった後も、すまいるスクールや学習塾に通うなど、子どもの帰宅する時間が遅くなっているように見受けられます。地域でこのような子どもたちへの見守りをしていくにはどうすべきか、お考えがあればお聞かせほしいと求めました。","respondent":"宮尾庶務課長","answer":"前述いたしました８３運動をはじめ、８３運動といいますのは、大きな力で児童を見守っていければと考えています。掛け合わせて、地域全体で見守る意識、こういったものを醸成していければと考えています。","id":"exchange-111"},{"speaker":"木村委員","kind":"質問・要望","question":"万が一侵入された場合、どのように対処されるのでしょうか。中途半端ではなく本格的に行っていただきたいが、教育委員会としての宣言をいただきたいのですが、いかがか尋ねました。","respondent":"矢部教育総合支援センター長","answer":"マニュアルもご説明いたしますと、学校危機管理マニュアルというのがございまして、このたび見直しを進めました。学校の中で組織的な対応ができるとともに、職員の対応、警察との連携等を全校で確認しています。","id":"exchange-112"},{"speaker":"木村委員","kind":"意見","question":"次に、３８５ページの保健運営費からですけれども、新型コロナウイルスの対応で、３月１３日からマスクの着用が個人の判断となりました。卒業式や入学式の扱いなど、４月以降の取扱いなども、どのようになっているのか説明を求めました。","respondent":"矢部教育総合支援センター長","answer":"入学式等、また４月以降につきましては、国から通知が出る予定ですので、それを踏まえて対応してまいりたいと思います。１点、こちらで啓発ポスター等を使って、子どもたちの心のケアに努めてまいります。","id":"exchange-113"},{"speaker":"小芝委員","kind":"質問","question":"私からは、３８７ページ、学校改築推進経費について、地域とつながる学校の在り方について質問いたします。学校の改築に当たりましてどのような声、期待の声もあったかと思いますが、教えてほしいと求めました。","respondent":"森学校施設担当課長","answer":"その中で、町会長をはじめとした地域の皆様のご意見を賜りながら、改築を進めているところです。計画説明会、工事説明会等を行いまして、それから近隣の皆様への説明等も。","id":"exchange-114"},{"speaker":"小芝委員","kind":"質問","question":"その中で何か期待の声とか、そういったものはありましたか尋ねました。","respondent":"森学校施設担当課長","answer":"期待の声というところは、大体どの改築につきましても、待っていましたというような、いい学校にしてくださいと、そのような声援のようなご意見はよく賜るところです。","id":"exchange-115","title":"町会・自治会支援"},{"speaker":"小芝委員","kind":"質問","question":"期待する声というのは、地域で子どもを育てている就学前のお子様を持つ保護者だけではなく、近隣の町会・自治会の方など様々だと思います。地域とのつながりというのも恐らく意識されて、詳しいことが分からないので、そのあたりを教えてほしいと求めました。","respondent":"森学校施設担当課長","answer":"同じく第四日野小学校ですけれども、桜の木を残したいところだったのですが、どうしても老朽化等で伐採するしかない。その木の枝を落として接いでいくということで、伐採してしまった木の材料を用いまして、モニュメントを設置するということも検討したりしております。","id":"exchange-116","title":"町会・自治会支援"},{"speaker":"小芝委員","kind":"質問・要望","question":"私の知る限りでも３つの団体が、そのような状況で、学校等で練習をしている状況です。そのたたけない理由として、恐らく近隣住民への配慮もあるかなと思いますが、そのあたり、ぜひ教えてほしいと求めました。","respondent":"森学校施設担当課長","answer":"当然、伝統文化の教育等はとても重要なことだと思っていますし、地域の皆様とのつながりはとても大事だと考えております。当然整備してまいりますけれども、無音室であったり防音室までは求められておりませんので、今の現状ではなかなか難しいというのが現状です。","id":"exchange-117"},{"speaker":"小芝委員","kind":"質問・要望","question":"スタジオに入るまでに２つの扉があって、そうするとほとんど音が聞こえてこない、外部に漏れてこないという遮音性でございました。教育機関も一緒になって、伝統文化を守る取組を展開していただきたいと思いまして、要望で終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-118"},{"speaker":"たけうち委員","kind":"提案","question":"まもるっちの私立小学校等への拡充を提案し、保護者からの要望が多かった中学生への拡充について、会派としても何度も求めてまいりましたが。その後も、会派として継続して小学生への配布を求めておりますが、改めて現在の考え方をお伺いしたいと思いますとの意見を述べました。","respondent":"矢部教育総合支援センター長、宮尾庶務課長、勝亦学務課長","answer":"比較的軽度のところで、学校、または関係機関で対応して、いじめを防いでいると、解決に向けて進んでいると解釈しています。関係機関と連携して… 特に１年生がまもるっちを頼りにする一方で、学年が上がっていくにつれまして、それも少しずつ下がってくるというふうに傾向としています。… ヘルメットに関しまして、いざというときにかぶっていただくときに、なかなか取り回しが難しいという部分があります。","id":"exchange-119"},{"speaker":"たけうち委員","kind":"質問・要望","question":"こういう文集は、これを生徒が読む機会の確保とか、どのような活用をされているかというのを教えてほしいと求めました。子どもたちがやはり自主的に避難をするのが大事だよと言われた中で、今の学校での避難訓練の現状を教えてほしいと求めました。","respondent":"矢部教育総合支援センター長、宮尾庶務課長","answer":"中学生の主張の内容ですけれども、各学校に戻りまして、生徒からしっかり報告をしていると聞いております。 考え方のところですけれども、基本的にまもるっちにつきましては、一義的な所管としては地域振興部であると考えています。地域で守る意識を醸成する… こちらは予告を大体してからやるのですが、予告なしという避難訓練は必ず入っておりますので、各学校でもそのような抜き打ちで指導をしております。","id":"exchange-120"},{"speaker":"たけうち委員","kind":"提案","question":"我々も提案してまいりましたが、いろいろなことに夢があったのですが、今はなかなか。ありがとうございましたとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-121"},{"speaker":"高橋（し）委員","kind":"質問","question":"３６１ページの委員会運営費に関連してですが、教育委員会は首長、区長からの独立性ということが、教育委員会の特性の一つと認識しております。これはどのような内容か、改めてご説明をお願いします。","respondent":"宮尾庶務課長","answer":"教育委員会は、区長部局から、今、委員からお話がありましたように、一定程度独立して、一定程度権限を有している、独立した機関であると認識しています。","id":"exchange-122"},{"speaker":"高橋（し）委員","kind":"質問","question":"教育委員会の責務、権能について、地方教育行政の組織及び運営に関する法律第２１条で、教育委員会の職務権限が定められています。その第１項について、改めてご説明をお願いします。","respondent":"宮尾庶務課長","answer":"地方教育行政の組織及び運営に関する法律第２１条には、教育委員会の職務権限ということが記されておりまして、具体的に１１項目の教育委員会が有する権限について、明記されているところです。","id":"exchange-123"},{"speaker":"高橋（し）委員","kind":"確認","question":"しかし、議題として供された形跡の存在が確認できていません。このような経緯について、教育委員でもある教育長の見解を伺います。","respondent":"宮尾庶務課長","answer":"伊藤幼稚園の廃園に関することにつきましては、今年度、教育委員会で２回ご審議いただきました。その中で様々な議論をいただきまして、教育委員会として承認をしたというものです。","id":"exchange-124"},{"speaker":"高橋（し）委員","kind":"質問","question":"次に、令和４年１２月１３日開催の令和４年第１７回教育委員会定例会における陳情審査、品川区立幼稚園の閉園に関する陳情についてお伺いします。なぜ教育委員会事務局が教育委員の皆さんに、どうしてこれを陳情審査できたのか、教育長のご見解をお伺いします。","respondent":"宮尾庶務課長","answer":"１２月１３日の定例会における陳情審査です。保育課長の説明に先立ちまして、私ども教育委員会事務局の学務課長からもきちんと説明をした上で、保育課長に説明を求めたという経緯があります。","id":"exchange-125"},{"speaker":"高橋（し）委員","kind":"質問","question":"教育委員会の議決、議会の議決がないのに、東京都に報告しているのでしょうか。それを伺います。","respondent":"宮尾庶務課長","answer":"今後、廃園の時期から見まして適切な時期に、教育委員会で条例の改正の審議というのは当然に行うと認識しています。","id":"exchange-126"},{"speaker":"高橋（し）委員","kind":"質問","question":"東京都に報告していないと受け取ってよろしいのか尋ねました。","respondent":"勝亦学務課長","answer":"廃止について条例が決定しておりませんので、報告等はまだ行っておりません。","id":"exchange-127"},{"speaker":"高橋（し）委員","kind":"質問","question":"令和６年度に開設されます。教員の確保・養成について、教育委員会として現在どういう準備をしているか、その状況を伺います。","respondent":"矢部教育総合支援センター長","answer":"小学校の免許を持った先生をということで、都の教員を配置するよう、指導課と連携して、今、配置に向けて進めています。ただ、在籍するお子さんの数に関わりますので、今それぞれ連携して進めているところです。","id":"exchange-128"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"逆に言うと、そういった形で指導教員を品川区は確保して、６年度に向けてやっていけるのでしょうか。その準備について先ほど伺ったのです。","respondent":"中谷指導課長","answer":"令和６年からのスタートになりますが、当然、おっしゃっていただいているとおり、令和５年度からの準備が必須と考えていますので、現在から、教員の専門性を持つ方の確保というところで動いて、やらせていただいております。","id":"exchange-129"},{"speaker":"高橋（し）委員","kind":"意見","question":"ということは、令和５年度にどれぐらいの方が応募してきて、その準備をやっていただけるのか、私は非常に不安です。その志、情緒をつくるというのはすばらしいことなのですが、その人材確保について、もう一度どのような決意で進めるか、お願いしますとの意見を述べました。","respondent":"中谷指導課長","answer":"例えば特別支援教育に特化して、特別支援学級や教室での指導経験がある方を引っ張ってくるということについて、今年度からやらせていただいております。","id":"exchange-130"},{"speaker":"鈴木（博）委員","kind":"質問","question":"３８５ページ学校管理費、保健運営費からブコラムとエピペンについて順不同にお伺いしてまいりますので、よろしくお願いいたします。ブコラムについてお伺いします。","respondent":"勝亦学務課長","answer":"口から投与できるブコラムが承認されたことにより、緊急時の投与がより迅速に対応できるようになるものと認識しております。現在てんかん発作時の対応のお申出をいただいている児童・生徒は５名、うち座薬は４名、お尋ねのブコラムについては１名となっています。","id":"exchange-131"},{"speaker":"鈴木（博）委員","kind":"意見","question":"これに関連して、同じように教職員が注射可能なアナフィラキシー対応のアドレナリン自己注射エピペンに関してもお尋ねします。アナフィラキシーショック治療薬であるエピペンの使用があれば、その使用実績に関してもご報告をお願いいたしますとの意見を述べました。","respondent":"勝亦学務課長","answer":"体調に異常がなかったものが乳とゴマのアレルギーの２件、体のかゆみ等を発症したものが乳とアーモンドのアレルギーの２件です。現在、エピペンを携帯している児童・生徒に関しましては約２３０人おりますけれども、今年度エピペンの投与実績はございませんでした。","id":"exchange-132"},{"speaker":"鈴木（博）委員","kind":"質問","question":"２００８年頃、チョウの食草を栽培し、チョウの飼育が行われたとお聞きしております。区内の小・中学校でチョウの食草の栽培とかチョウの飼育などが現在も行われているか、そういう学校があるかどうかお伺いしたいと思います。","respondent":"勝亦学務課長","answer":"最近まで鮫浜小学校ではチョウの食草の栽培が継続されておりましたが、改築工事となりましたので、休止となったと聞いてあります。しかしながら今年度、校庭や外構の整備が終了いたしまして、来年度からチョウの食草栽培を再開する予定となっております。","id":"exchange-133"},{"speaker":"鈴木（博）委員","kind":"質問","question":"はいろいろと自然保護、チョウに関する活動が続いているということをお聞きしまして、非常に喜ばしい限りだと思います。これに関してはいかがか尋ねました。","respondent":"勝亦学務課長","answer":"こちらは特色ある教育活動の中で予算を組み実施をしています。こうした生き物や自然に関する活動について、各学校の活動を後押ししてまいりたいと考えています。","id":"exchange-134"},{"speaker":"鈴木（博）委員","kind":"質問","question":"次に、しつけ教育について伺います。品川区のご見解はいかがか尋ねました。","respondent":"矢部教育総合支援センター長","answer":"一概に答えられませんけれども、成長過程でルールやマナーの理解、自己肯定感が育まれてこなかったことも可能性として考えられます。委員ご指摘のような事例に結びつかないように、学校においても引き続き力を入れて指導してまいりたいと考えております。","id":"exchange-135"},{"speaker":"鈴木（博）委員","kind":"質問","question":"品川区の教育でも、ぜひ自己肯定感を高めるようないろいろなその取組を積極的にしていただけるようにお願いして、質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-136"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私は、３８３ページの学校給食費の無償化について伺いたいと思います。これは区立小・中学校だけでなく、私立の小学校に通う子どもも含めて、品川のすべての子どもの給食費無償化を求めて質問したいと思います。","respondent":"勝亦学務課長","answer":"特別支援学校に通われている方、２００人から３００人と把握しています。申し訳ございません、小・中学校の別については、現状数字を把握してございません。","id":"exchange-137"},{"speaker":"鈴木（ひ）委員","kind":"確認","question":"私立・国立も含めて給食費の無償化もすべての子ども、すべての子育て家庭を対象にすべきではないかと思いますが、いかがでしょうかということです。それなので、すべての子どもを対象にすべきだと思いますが、いかがか尋ねました。","respondent":"勝亦学務課長","answer":"なぜ今回区立学校の無償化なのかです。予算等を行っておりますので、そちらのほうは教育委員会としてまず無償化ができるものとして、実施しているものです。","id":"exchange-138"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"品川区としてどう考えるかというところはどうでしょうかというのを、どこになるのでしょうか、伺いたいと思います。あったらその課題ついても伺いたいと思います。","respondent":"勝亦学務課長","answer":"区立学校以外という部分です。そういった中で設置者の違う学校を選び取っていただいているという部分で、まずは区立学校の無償化を教育委員会として進めるというふうな考えです。","id":"exchange-139"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"教育委員会は所管するところがそうなのでということですけれども、私立とか特別支援学校の教育というのは、ではどこになるのですか。そこのところをこのように無償化すべきだということを答えていただけるところはどこになるのか尋ねました。","respondent":"勝亦学務課長","answer":"都立特別支援学校については都立、私立についても基本的には東京都が情報集約、所管しているものと考えております。","id":"exchange-140"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"では都立の特別支援学校に行っている子どもたちや私立の子どもたちをこの品川区ではどうするかということは、話し合う場所がないということですか。そこのところを伺いたいと思っているので、区としての考え方をどのように考えるべきかというところを伺っているので。","respondent":"勝亦学務課長","answer":"都立の特別支援学校に通われている方、様々な進路の中でまずは区立学校の給食について無償化というところで、進めているところです。","id":"exchange-141"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"私はぜひとも「すべての」と区長がこれだけ強調しているわけですから、特別支援学校もやる方向でと言っているわけですから、そこのところも。では、まもるっちは私立の子どもたちにも行っていると思うのですけれども、それはどういう経過で実現したのか尋ねました。","respondent":"勝亦学務課長","answer":"特別支援学校につきましては、特別支援学校については、実施に向けて検討しているという状況です。まもるっちの経緯については所管ではございませんので、私立は別の窓口で個別に対応している状況ということで、まもるっちについては理解しています。","id":"exchange-142"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"はということで研究課題ということですけれども、これだけすべての子どもたち、すべての子育て家庭ということで区長自らが強調して言われているわけですから、ぜひとも区長のほうからも、すべての子どもたち、すべての子育て家庭、こういうことで実現の方向にしてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-143"},{"speaker":"若林委員","kind":"質問・要望","question":"それから３７９ページの学校環境整備事業について、体育館の舞台照明について改めてお伺いいたします。しっかりとペースを進めていただきたい、また児童・生徒の思いに応えてほしいという意味で、要望も含めてお聞きいたします。","respondent":"矢部教育総合支援センター長、森学校施設担当課長","answer":"発達障害に起因する児童・生徒の問題行動に対して、学校が早期に気づいて家庭と連携し、対応しようとする姿勢も浸透しつつあるです。きちんと対応してくださる方とか、お子さんとその支援員とのマッチングもありますので… 委員からご案内のありました舞台照明のＬＥＤ化ですけれども、今年度小学校２校、来年度は中学校２校を実施する予定です。","id":"exchange-144"},{"speaker":"若林委員","kind":"質問","question":"ここをしっかりモデルという意味では検証して１年間見て、また次年度は１０校に増やしてと。これもいわゆるモデルという言葉使いが先ほどありましたけれども、この１年間、この５校でこの３者、これの評価をお聞きしたという意味です。","respondent":"矢部教育総合支援センター長","answer":"この発達障害教育支援員が配置されたら、そこにいる学習支援員、介助員は今回は配置しないという条件でスタートしました。学習支援員を配置したという学校がありますので、学習支援員、介助員は配置しない予定で当初はあります。","id":"exchange-145"},{"speaker":"若林委員","kind":"提案","question":"学習支援員は品川区では２００８年に導入されて、私も２００５年にこのことを提案させていただいて、３年後に導入されたと。そこが一番大きな目的なわけですから、進め方、ここは少し確認をさせてくださいとの意見を述べました。","respondent":"矢部教育総合支援センター長","answer":"特別支援、Ｂさんのためにどのような支援が必要かということで、月１回程度会を催しています。これからも進めてまいります。","id":"exchange-146"},{"speaker":"若林委員","kind":"質問・要望","question":"基本的には学習支援員と介助員はこれから配置を控えていくという一つの方向はお聞きしておりますけれども、先ほど申し上げましたように品川区の強みをしっかり生かしてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-147"},{"speaker":"松本委員","kind":"質問","question":"本日は３６１ページ学校職員被服貸与費、３７３ページ教職員被服貸与費、３６７ページいじめ防止対策費について伺います。最初に学校職員被服貸与費、教職員被服貸与費について伺います。","respondent":"中谷指導課長","answer":"令和５年度は安全靴のみの購入という予算立てをしております。背景としましては、安全靴以外の品物の在庫が非常にあるというところを確認したことによる減額というものになります。","id":"exchange-148"},{"speaker":"松本委員","kind":"質問","question":"ほかの区だとよく問題になるのが、トレーニングウエア、運動着の関係とかです。この辺りについては、当区の場合は貸与はしていないという理解でよろしいのか尋ねました。","respondent":"宮尾庶務課長","answer":"教職員につきましては、先ほどご答弁させていただいたとおり、防災服のみということになります。","id":"exchange-149"},{"speaker":"松本委員","kind":"確認","question":"当区の場合はどうなっているのかというところで確認させていただきました。なので、ここの部分はしっかりと定めてほしいと求めましたが、いかがか尋ねました。","respondent":"宮尾庶務課長","answer":"それぞれが、例えば先生方なら先生方とも同様に定めているところです。特段我々は課題があるというところは認識してございませんので、これからも適切にこのやり方にのっとって執行させていただければと考えています。","id":"exchange-150"},{"speaker":"松本委員","kind":"質問","question":"総括的なというか概括的な規程はきちんと公開されていると思うのですけれども、今の個別のこういう服ですみたいなのはどこに定めがあるのでしょうか。定めがあるのは分かったのですけれども、どこに定めてあるのか、もう一度お伺いします。","respondent":"宮尾庶務課長","answer":"こちらにつきましては、文字どおり別に定めるということで、この被服貸与規程を受けまして、事務局のほうで意思決定をとって適正に管理しています。","id":"exchange-151"},{"speaker":"松本委員","kind":"質問","question":"その定められているものの表題は何になるのか尋ねました。","respondent":"宮尾庶務課長","answer":"すみません、今そのタイトルにつきましては、すみません、今手元に資料がございませんが、この規程にのっとりましてそれぞれ内部で意思決定を取って、それにのっとって執行しています。","id":"exchange-152"},{"speaker":"松本委員","kind":"質問・要望","question":"これは要望というところでお願いしたいと思います。今日は特に中でもいじめの被害者についてお伺いしたいのですけれども、特にこのＩＣＴを活用したフォロー体制についてお伺いできればと思います。","respondent":"矢部教育総合支援センター長","answer":"いじめにかかわらず、まず本人と保護者にお話を聞きながら、どういう形がいいかというのは相談をしております。今やっている１年１組の授業とか５年１組の授業を配信して、子どもたちも自分の学校に来たという非常に効果的な方法だと捉えております。","id":"exchange-153"},{"speaker":"松本委員","kind":"質問","question":"ではいじめの加害者との関係でどうなのかというところを少しお伺いしたいのですけれども、よくやはり加害をした児童・生徒が教室にいるので、一方。では、いじめ防止対策推進法上で認められている別室登校について、品川区ではそういった実績があるのかお伺いいたします。","respondent":"矢部教育総合支援センター長","answer":"どのように対応するかということになりますので、当然別室、もしかしたら被害者の方が同じ校舎内にいることすら苦手な場合もあるかもしれません。","id":"exchange-154"},{"speaker":"松本委員","kind":"質問","question":"今の進めているというところで実績があるのかどうか伺っているので、実績としてそういう事例があるのでしょうか。伺います。","respondent":"矢部教育総合支援センター長","answer":"実績はつかんでございませんが、ないとは申し上げられないです。今はここまでです。","id":"exchange-155"},{"speaker":"吉田委員","kind":"確認","question":"ただ、予算書の３７３ページに５,３３２万５,０００円ですか。１５校は分かりましたけれども、少々予算的にどうなのかと思ったので説明を求めました。","respondent":"矢部教育総合支援センター長、宮尾庶務課長","answer":"こちらにはまとめたことしか計上してないと伺っていますので、すみません、少しフォローしていただいていいですか。ですから、来年度の派遣につきましては計上されているです。 会計年度任用職員の給与面に関しましては、今年度から全庁的に、それまで各課に計上していたものが人事課のほうに移行するということになってあります。","id":"exchange-156"},{"speaker":"吉田委員","kind":"質問・要望","question":"何かやはり同じような仕事をするのであれば、同じような報酬であってほしいと思って伺ったので、後で分かったらぜひ教えてください。普通学級に障害児を通わせているお子さんの親の付添いを学校から求めることはないというご答弁をいただいております。","respondent":"矢部教育総合支援センター長","answer":"その辺りを私たちも注視しながらモデルを進めてまいりたいと思っています。学習支援員、介助員につきましては、ＮＰＯ団体にお願いをして委託をしております。","id":"exchange-157"},{"speaker":"吉田委員","kind":"質問","question":"すみません、一気に聞いてしまえばよかったのですけれども、確実に増えているということについての、例えば過去５年間で何人から何人に増えたとか、そういう実績で増えたということが分かるようなことがあったら説明を求めました。","respondent":"矢部教育総合支援センター長","answer":"５年前、平成３０年からです。通常の学級に配置した学習支援員・介助員が３９２名、令和元年が４５７名、令和２年が５１８名、令和３年が５６３名、本年度５２４名となっています。","id":"exchange-158"},{"speaker":"吉田委員","kind":"質問・要望","question":"親の付添いを学校から求めることはないということだったのですが、やはりそれは限りなく、そういう強いお願いだというふうに受け止めるのが現状です。教員を支援するほうが妥当なのかというふうに思うのですけれども、教員を支援する形で、ぜひ見解があったら伺いたいと思います。","respondent":"矢部教育総合支援センター長","answer":"それが、以前からお伝えしてまいりましたとおり、教員の支援につながっていると考えています。どうやってその子のことを理解するかということに基づいておりますので、教員のほうの研修もしっかりして、いいクラスを作りたいと思っています。","id":"exchange-159"},{"speaker":"吉田委員","kind":"質問","question":"２回選挙がありましたから２回目に行ったけれども、この点について品川区の公立学校の方針はどのようなものなのか伺いたいと思います。子どもたちが小動物を飼う場合の関わり方、昔はよく飼育係とか結構人気の係があったと思うのですけれども、今はどうなのか尋ねました。","respondent":"勝亦学務課長、森学校施設担当課長","answer":"現状、例えばウサギに関しましては１日、ふんですと１センチ大のものが大体１００個から２００個ぐらい出るとは聞いております。現場のそれぞれの飼育の状況ですとかそういった不適切なことがないか… やはり働き方改革等もありますので、今は委託のほうに、警備会社にお願いをして餌やり等を長期休暇についてはお願いしています。","id":"exchange-160"},{"speaker":"吉田委員","kind":"質問","question":"たまたまその方がご覧になった２回が、少々考えにくいかなと思います。ぜひその辺についての見解を伺いたいと思います。","respondent":"勝亦学務課長","answer":"改善の対応につきましては学校にお声を掛けていただいたですけれども、教育委員会のほうで一定程度、獣医師会と連携しながら飼育の方法ですとか動物の面倒等を見ておりますので、教育委員会のほうに言っていただければ対応できるかと考えています。","id":"exchange-161"},{"speaker":"吉田委員","kind":"質問・要望","question":"皆さんもこの動物を飼うということについては価値を置いておられるようなので、ぜひその方向で進めてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-162"},{"speaker":"渡部委員","kind":"質問・要望","question":"５年、ではこの界隈の学校が大丈夫なのかというのもあるわけですから、しっかりそこは進めてほしいと求めました。入れないというのもあるわけですから、隣接校からという形のものを変える予定はないのですねという確認と、あと学区域のほうは。","respondent":"勝亦学務課長","answer":"そういった意味では、引き続き学校選択制は隣接校の形で実施していきたいと考えています。学区の変更が考えられる場合、校区教育協働委員会の中でもご意見ですとか周知、適時考えていきたいと考えております。","id":"exchange-163"},{"speaker":"渡部委員","kind":"質問・要望","question":"そういうような思いでお伺いさせていただきました。その学校は、何かしら実は簡単に欠員が何名ですでは片付かなくて、それなりのことを教育委員会でいろいろやっているのか尋ねました。","respondent":"中谷指導課長","answer":"欠員に対する考え方ということでご質問いただきました。そのお休みされる期間に対して教員を置いていくという考え方で、情報をすぐに配置に生かせるようにということで努めているところです。","id":"exchange-164"},{"speaker":"渡部委員","kind":"質問・要望","question":"それは見てみたいとは思うのですけれども、すごく有用であると思いますので、引き続き研究を進めていただいて続けてほしいと求めました。管理職先生は役職定年がついてしまって、そうしたら校長先生を終わって６０歳過ぎて役職定年が来てしまうから、その辺の考え方を説明するよう求めました。","respondent":"中谷指導課長","answer":"今後、定年退職が１０年間という年月を経ながら、だんだん６０歳から６５歳に移行していくというような時代を迎えていきます。考え方としては現在の再任用の方と同じで定年退職以降、６５歳になるまでの間を暫定再任用管理職ということで働くような形となります。","id":"exchange-165"},{"speaker":"渡部委員","kind":"意見","question":"ではいわゆる校長先生として残っていただく方は、６０歳で一回そこで区切りをつけてもらって退職という形をとって、違う形の再任用ということですね。６５歳までそのランクを下げたと言ったら失礼だけれども、そうした上で残れるという仕組みでいいのですよねとの意見を述べました。","respondent":"中谷指導課長","answer":"校長先生もしくは副校長先生、それ以降の考え方としては基本的に降任ということになりまして、役職ですと主幹教諭以下の役職になっていくと。こういったものも複層で併せながら任用していくという形になります。","id":"exchange-166"},{"speaker":"渡部委員","kind":"質問","question":"実際この国のほうの学習指導要領と、品川区の結局品川区立学校教育要領との違いというのが、よその区はこういうのを作っていないわけではないですか。全部読んでいれば分かるのかもしれないのだけれども、国と品川区の主に違うところというのを少しアピールというか教えていただけますか。","respondent":"中谷指導課長","answer":"そして９年間の一貫教育を進めているというところが最も特徴的なところかと思います。これに関しては、品川区はいち早く取り組んで、今充実しているところと認識しております。","id":"exchange-167"},{"speaker":"渡部委員","kind":"質問・要望","question":"けれども、やはりしっかりと子どもたちが生き抜く力というのはある程度の競争も私は必要だと思います。その学習の中でこれからもしっかり品川区は取り入れてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-168"},{"speaker":"大倉委員","kind":"質問・要望","question":"どのように１名増やしていくか、人材確保について教えていただきたいのと、どのようにお考えか教えてください。改築して取り壊しする前にはぜひ学校見学をしたいというようなご要望、今までもあったかと思うのですが、その点に関してはどのようにお考えか。","respondent":"矢部教育総合支援センター長、中谷指導課長、森学校施設担当課長、勝亦学務課長","answer":"全部入っているわけではなく、少し余裕がある場合は複数でも構わないということにしましたので、２人原則ですが、そこは応相談になります。… 例えば野球部などですと、改革推進期間に新入部員をできるだけ学校のほうを減らしていくような取組を進めるというような事例があります。… そことの兼ね合いを見合いながら、地域のお声があるようでしたらそういう見学会も進めていきたいということは考えてあります。… 変更の理由ですけれども、現行のホームページのシステムが平成２４年にできてあります。","id":"exchange-169"},{"speaker":"大倉委員","kind":"質問・要望","question":"非常に私も今まで一般質問等でも求めてきたところであるので、そういうことはどうなっているのかということ。４Ｋのハイクオリティな３Ｄモデルで表現され、ドラッグすれば３６０度回転しながら閲覧ができるというもので、いかがか尋ねました。","respondent":"矢部教育総合支援センター長、勝亦学務課長、森学校施設担当課長","answer":"部活動指導員の公募ですが、例年１２月から１月ぐらいに区のホームページで上げさせていただいています。必ず外部の外の端末でもパスワード等でアクセス制限をして、更新にあたっては必ず管理職の確認、承認を経て公開するような対応をとります。… 区の方針等もありますので、そういうことを幅広く検討しながら、今のところはそこまで先進的なのはまだです。","id":"exchange-170"},{"speaker":"大倉委員","kind":"質問・要望","question":"ＤＸを進めていくというところでは、ぜひいろいろ研究して進めていっていただきたいなと思います。当然、またこれから学校を選択していこうという方たちの一つの参考になるのかなと思うのですが、そうしたことの検討についてはいかがか尋ねました。","respondent":"森学校施設担当課長","answer":"委員ご案内のとおり、新しい技術は児童・生徒もわくわくするようなことになるかもしれないとは思っております。世の中の要請、区民の皆様からの要請も鑑みながら判断して検討してまいりたい、研究してまいりたいと考えています。","id":"exchange-171"},{"speaker":"石田委員","kind":"質問","question":"私からは、３６４ページの教育指導費でいいのか、命の安全教育について伺いたいと思います。熱心に取り組む学校もあれば、品川区はこの生命の安全教育についてどのような姿勢で取り組まれていくのか、まず伺いたいと思います。","respondent":"矢部教育総合支援センター長","answer":"委員ご案内の教育につきましては大変重要だと認識しておりますので、令和５年度はすべての学校、全学年で取り組みます。ただその後、私どももどのような資料かというのは、指導主事が授業のほうはよく見ておりますので、その際に情報をつかんでいきたいと思います。","id":"exchange-172"},{"speaker":"石田委員","kind":"質問","question":"いかがでしょうかというのと、あと、この歯止め規定がやはりあるのですね。どうやってそうした性犯罪・性暴力から自らを守るのかというのが分からないままになるのではないかと思うのですけれども、いかがか尋ねました。","respondent":"矢部教育総合支援センター長","answer":"一番肝要なのは、ここに目標を置いてきちんとした指導をできるように、我々のほうもきちんと見て指導してまいりたいと考えています。一つ一つ、一歩一歩進んでいると考えていますので、我々としましてはこちらの生命の安全教育のほうの推進に注力していきたいと存じます。","id":"exchange-173"},{"speaker":"石田委員","kind":"質問・要望","question":"この生命の安全教育については、学校等でこの性について、また性被害を受けたなど相談を受ける体制の強化も求められております。相談ができなくなるということもあると思いますので、教育委員会としても子どもを守る立場から進めていただきたいと思うのですが、いかがか尋ねました。","respondent":"中谷指導課長","answer":"教職員がこういったお子さんからの相談を受けたときの初期対応というものが非常に大事になってくると考えています。４月からが本格始動になるかと思いますが、どうやって体制を組んでいくかというところをしっかり進めてまいりたいと考えています。","id":"exchange-174"},{"speaker":"石田委員","kind":"質問","question":"教職員ではなくて、地域の大人や保護者への性教育も必要だと思います。そういった相談を受けてもどう答えることが正解か分からなくて困るという声も寄せられておりますので、教育委員会としてはどうお考えか尋ねました。","respondent":"矢部教育総合支援センター長","answer":"保護者の、また大人の性教育を学校がどこまでやるかというところもあるのですが、保護者として必要な知識を共有する場というのは保護者会とか報告会などであるのかなとは思っております。","id":"exchange-175"},{"speaker":"塚本委員","kind":"質問","question":"私からは、初めに３７５ページ図書館運営費、それから３７１ページマイスクール運営費についてお伺いしていきます。図書館として区内１０か所、あと分館が１か所ありますけれども、どのような状況になっているのか現況を説明するよう求めました。","respondent":"吉田品川図書館長","answer":"図書館では、コロナ対策で行ってきた人との距離を空けて座るというところも、２月１０日以降はやめてきたところです。まだその辺の周知については時間がかかるものと考えております。","id":"exchange-176"},{"speaker":"塚本委員","kind":"意見","question":"こういうことで、もう少し使えるようにしてもらいたいというような話を聞きました。このことについて、こういった受験生の声について区としてどのように今お考えになるかということと、それについても説明を求めました。","respondent":"吉田品川図書館長","answer":"令和３年の秋口ぐらいから、閉めていた部屋を何か利用できないかということを考えたところ、今使っているところです。席についても１０席ほどしかございませんので、今、図書館ではそういう勉強スペースがありますよというところを紹介しているところです。","id":"exchange-177"},{"speaker":"塚本委員","kind":"質問","question":"今、多目的室というので、これは品川図書館だけでしょうか。こういった座席のスペースの拡充について何かしらの手が打てないものか、その件についてお伺いしたいと思います。","respondent":"吉田品川図書館長","answer":"その中で、今年度からは大崎図書館と大崎図書館の分館においても、多目的室を利用した学生向けの勉強スペースを用意しています。今後につきましては、その各施設の状況等を踏まえまして検討してまいりたいと思います。","id":"exchange-178"},{"speaker":"塚本委員","kind":"質問","question":"不登校との関係において伺いたいのですけれども、まず、今不登校の児童・生徒というのが増えているといろいろなところで伺っております。タブレットによるオンライン授業というのか、どのような状況にあるのか、最初にお伺いいたします。","respondent":"矢部教育総合支援センター長","answer":"不登校のお子さんにつきまして、タブレットの活用は、在籍校のほうでかなり頻繁にされていると認識しています。学校とも連携して、お子さんがマイスクールの中でもオンライン授業がさらに進むように、在籍校と連携して進めるというのは課題です。","id":"exchange-179"},{"speaker":"塚本委員","kind":"質問・要望","question":"この不登校、また不登校気味の児童・生徒の方々に対しても、大いにこれは活用できるところは活用していただきたい。ぜひ今後、課題は課題として認識されていると思うのですけれども、一層の活用に向けての検討等を進めていただきたいとお願い申し上げます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-180"},{"speaker":"渡辺委員","kind":"質問・要望","question":"昨年１２月の令和４年第４回定例会、本会議場でも粗々のことを伺いました。私たちも強い要望として伺って、あるいは希望も言った中で、ご答弁の中で次年度には少なくとも各学校１つの部活動が地域移行できるようにという点。","respondent":"中谷指導課長","answer":"部活動の地域連携に向けた部活動指導員を拡充していくということにつきましては、令和５年度に拡充という形で進めさせていただきたいと考えています。","id":"exchange-181"},{"speaker":"渡辺委員","kind":"質問","question":"私も少し理解に苦しんでいるのですが、ひとつ予算書はまだ準備が難しいのかなと思いながらも逆に伺います。１２月ですから間に合わなかったのか、あるいは私たちは議会人ですから議会として、いつこういう質疑をすると翌年の事業に間に合うのか。","respondent":"矢部教育総合支援センター長","answer":"部活動指導員の倍増ですので、こちらの会計年度任用職員で先ほどお話があったとおり、３６５ページの職員給与費の中に含まれているです。","id":"exchange-182"},{"speaker":"渡辺委員","kind":"質問","question":"そういう思いで今伺っていますので、ここなどは当初予算ベースで令和４年よりも総額で言えば横ばいあるいは減少している事実があるのです。それはこれまで負担感があったのかどうかも含めての課題の整理、今後の教員の関わり、この辺をテーマに説明を求めました。","respondent":"中谷指導課長","answer":"それから、教員の意識ということで、３月１５日時点で今２３２名の中学校・義務教育学校後期課程の教員から回答を頂いております。今、この２つの地域スポーツクラブをまずは設置するということで、文化スポーツ振興部と連携して考えております。","id":"exchange-183"},{"speaker":"渡辺委員","kind":"質問・要望","question":"それを踏まえて最後ご答弁いただきたいのは、その辺品川らしさ、その辺を十分踏まえて現場の先生たちをしっかり応援できる。これが品川らしさだと思っているので、経費のことはもうご答弁はいいので、ぜひその未来を語ってほしいと求めましたので、ご答弁をお願いします。","respondent":"中谷指導課長","answer":"やはり一番大切なのは、このとても大切な学校時代に、どういった仲間と共にどういったことに集中して、どのような感動体験を積み重ねてきたか。そういった経験を、地域移行という形になったとしてもそこをしっかり保証するということをやっていきたいと考えています。","id":"exchange-184"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/756395?Template=document&Id=1174#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":124522,"voices":436}},{"id":"r05-20230322-3","meetingId":"r05-c-budget","date":"2023年3月22日","dateIso":"2023-03-22","committee":"予算特別委員会","time":"午前１０時００分～午後 ６時４４分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を154件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"湯澤副委員長","kind":"質問","question":"そこでまず、区は逼迫する区民生活をどのように捉え、現在どういった生活支援を行っているのかをお知らせください。ちょうちんの電気はつけないとお伺いしておりますが、そういった事態をどう受け止め、どのような対策を取っているのかも示すよう求めました。","respondent":"久保田企画部長、伊崎地域振興部長","answer":"具体的には、第４回定例会におきまして、約８億円の各種支援策を議会にご提案し、議決を頂き、現在、各施策を進めているところであります。引き続き、区民の生活状況等の把握に努めまして、区として適切な支援を進めてまいります。 物価高騰への対応経費としての直接の助成制度ではございませんが、活動活性化の支援策として実施している補助金を活用していただくことが可能です。今後も状況を注視して、適切な支援に努めてまいります。","id":"exchange-001"},{"speaker":"湯澤副委員長","kind":"質問・要望","question":"様々な支援メニューがあることは確認できましたけれども、寄り添う形での支援体制の強化をお願いしたいと思います。そういった要望に対して、区や東京都へ予算要望をしていただき、区のご見解を示すよう求めました。","respondent":"久保田企画部長","answer":"次に、区の独自支援策の実施についてですが、現在、国や東京都では、直接給付を含みます経済支援等の実施に向け、検討を進めております。区としましては、引き続き区民の生活状況等の把握に努めるとともに、国や東京都の動向を注視しながら、適切な支援を実施してまいります。","id":"exchange-002"},{"speaker":"湯澤副委員長","kind":"質問・要望","question":"物価高騰で打撃を受けている事業者や団体からの要望は、会派からも引き続き要望しますので、その時々に必要な支援を行える体制を要望いたします。健康支援についても、令和５年度の予算案には、会派より要望しておりました帯状疱疹ワクチン接種の一部助成も盛り込んでいただきました。","respondent":"福内健康推進部長","answer":"区におきましては、区民の健康を守るため、基本健診やがん検診、歯科健診等を実施しています。２年に１回の受診となっており、がんの死亡率を減少させることを目的としたがん検診実施のための指針に従い、実施しているものです。","id":"exchange-003"},{"speaker":"湯澤副委員長","kind":"確認","question":"受診によって早期発見されているケースもあるということが確認できましたが、今後は受診率を上げるための取組が重要であると考えております。民間自動車保険会社のように、期限が迫るとお知らせするようなサービスも、受診率を上げる取組かと思いますけれども、ご見解を示すよう求めました。","respondent":"福内健康推進部長","answer":"それ以外は基本的にその年度内となっておりますが、胃がん検診の未受診者は翌年度まで受診可とするなどの対応を取っております。今年度、肺がん検診でも同様の取組を行っており、これらの効果を見極め、今後も効果的な受診促進策を検討してまいります。","id":"exchange-004"},{"speaker":"湯澤副委員長","kind":"質問・要望","question":"続いて、災害についてお伺いします。そこで、主に修正内容がどういったものなのか、また、いつ起きてもおかしくない大災害に備え、できるだけ早い作成を望みますが、いかがか尋ねました。","respondent":"滝澤災害対策担当部長","answer":"これまでの経験から、風水害編としての記述の独立性や内容の充実を図るとともに、富士山火災などの複合災害についても内容を検討してまいります。令和５年度に入りましたら直ちに修正作業を開始し、令和６年１月には修正計画を決定できるようにしてまいりたいと考えています。","id":"exchange-005"},{"speaker":"湯澤副委員長","kind":"質問・要望","question":"備蓄は、現存するもので足りるのでしょうか。そのような帰宅困難者の命を守る区独自の取組について、国や東京都に対して予算の拡充を求めるべきと考えますが、それぞれご見解を示すよう求めました。","respondent":"滝澤災害対策担当部長","answer":"分散している帰宅困難者に安全に帰路についてもらえるよう、正しい情報を共有し、連携した帰宅行動が取れるべく対策を講じていく必要があります。引き続き、国や都と連携しながら、帰宅困難者対策を一体的に推し進めてまいります。","id":"exchange-006"},{"speaker":"湯澤副委員長","kind":"質問・要望","question":"今後もリアル訓練と並行して行い、時代や世代にマッチした開催によって訓練参加率を上げていくべきと考えますが、区のご見解をお知らせください。動物以外のペットもいて、大変難しい課題であるかと思いますけれども、ペット同行避難について、区のご見解と今後の取組について示すよう求めました。","respondent":"滝澤災害対策担当部長","answer":"５２か所の全ての区民避難所においてペット同行避難の受入れを可能にする取組について、地域を交え、検討を活性化させてまいります。さらに、本年５月に実施する区職員による自主避難施設開設訓練や、１２月に実施する区内一斉防災訓練における区民避難所訓練においても。","id":"exchange-007"},{"speaker":"湯澤副委員長","kind":"質問・要望","question":"次に、犯罪から区民を守る取組についてもお伺いします。どういった対応をしているのか、区のご見解と今後の区民への啓発方法について示すよう求めました。","respondent":"伊崎地域振興部長","answer":"区内４警察署からのご案内も含めて約５,０００台を貸与しており、今後もさらなる周知に努め、ご希望の方に行き渡るように努めてまいります。さらに、家族や一般の方でもできる未然防止策についても啓発などを行っており、今後も継続してまいります。","id":"exchange-008"},{"speaker":"湯澤副委員長","kind":"質問・要望","question":"無料貸付機も５,０００台貸与されているということでありますけれども、アポ電で捕まる指示者役も氷山の一角にすぎないと言われております。自動通話録音機とともに、録画機能つきのテレビインターホンの設置助成をすることも検討ほしいと求めましたが、いかがか尋ねました。","respondent":"伊崎地域振興部長","answer":"今ご指摘にあったように、宅配業者を装った犯罪など、区民の方のご不安になるような犯罪が続いているということは認識しております。はこういった防犯対策の情報を周知することにより、被害の未然防止を図ってまいりたいと考えております。","id":"exchange-009"},{"speaker":"湯澤副委員長","kind":"提案","question":"ご提案した録画機能つきのテレビインターホンにつきましては、区民が安心して生活できるような先行区としてご検討ほしいと求めました。少子化トレンドを反転させるものでありますけれども、品川区は少子化を現在どう捉えているのか、課題と取組についてお知らせくださいとの意見を述べました。","respondent":"久保田企画部長","answer":"令和５年度に本格的に実施いたします行政評価によりまして、改善を実現しまして、財源を生み出してまいりたいと考えているところです。３つの無償化であります、第２子以降の保育料の無償化、様々な事業につきましては積極的に進めてまいりたいと考えているところです。","id":"exchange-010"},{"speaker":"湯澤副委員長","kind":"質問・要望","question":"子育て事業も令和５年度には様々取り組まれておりますし、自民党からの要望も多く採用していることに関しまして大変うれしく思っております。子育てプランに対して相談やアドバイスを行える伴走型支援も有効であると考えますが、ご意見を伺います。","respondent":"柏原子ども未来部長、福内健康推進部長","answer":"こちらは区のホームページでもＰＤＦ化しておりますけれども、今後の利便性を考えて、電子ブック化できないかというところの検討も今しています。こちらも来年度、リニューアルを予定してございまして… 区はこれまでも、妊産婦ネウボラ相談から始まり、支援が必要な方へ、子育てサービスの提供や保健師の訪問など、伴走型の支援を実施してまいりました。","id":"exchange-011"},{"speaker":"湯澤副委員長","kind":"質問・要望","question":"今後、拡充していただきたいと考えますが、いかがでしょうか。プレッシャーを感じることのない、積極的に子育てに参加できるような取組が今後さらに必要だと考えますので、区のご見解を示すよう求めました。","respondent":"福内健康推進部長","answer":"状況を見ながら見直すとともに、これまでの父親学級での利用者の声も踏まえ、プログラムを検討してまいります。それぞれのニーズに沿った教室を行っており、それらの教室を利用していただき積極的に子育てに参加できるよう、周知などの工夫を行ってまいります。","id":"exchange-012"},{"speaker":"湯澤副委員長","kind":"質問","question":"学校のマスク着用についてもお伺いしますが、教育委員会では今年の２月に全児童・生徒に向けて。例えば、区長が子どもに対してメッセージの動画を配信するといったことも防止策の一つと考えますが、いかがか尋ねました。","respondent":"米田教育次長","answer":"しながわ学校２０２０レガシーとして、スウェーデン在住の障害者スポーツの選手と質疑応答を行ったりするなどの活動を実施している学校もあります。これまでも学校向けに、しながわネットＴＶのＹｏｕＴｕｂｅ番組等を作成してきましたが、今後についても検討してまいります。","id":"exchange-013"},{"speaker":"湯澤副委員長","kind":"質問・要望","question":"次に、高齢者・障害者支援についてお伺いします。認知症の正しい知識とともに多くの区民に知っていただくべきと考えますが、区のご見解を示すよう求めました。","respondent":"今井福祉部長","answer":"特に検診受診後の継続的な関わりを強化すべく、訪問看護ステーションとの連携の下、受診後の伴走的な支援をさらに予定しております。今後も、認知症になってもその人らしく住み慣れた地域で暮らせる地域づくりを、区民の皆様と共に進めてまいりたいと考えております。","id":"exchange-014"},{"speaker":"湯澤副委員長","kind":"質問・要望","question":"区内２か所に認知症ミーティングセンターを開発・設置されましたので、まず、その成果と見えてきた課題についてもお知らせください。当事者が安心して生活できる取組ですので、今後もニーズに合わせて拡充を図ってほしいと求めましたが、課題や展望があれば示すよう求めました。","respondent":"今井福祉部長","answer":"事業の成果としましては、今年度、今、副委員長がおっしゃったとおり、２か所で開始いたしております。認知症地域支援推進員の協力の下、令和５年度は計３か所の拠点へと拡充すべく、強化を図ってまいりたいと考えております。","id":"exchange-015"},{"speaker":"湯澤副委員長","kind":"確認","question":"大きく６つの項目に分けて、問診票を、自分の気持ちを確認しながらチェックしていくものであります。ご案内した、より高齢者が人生設計をしやすくなると考えますが、見解を示すよう求めました。","respondent":"今井福祉部長","answer":"平成２７年３月より、品川区社会福祉協議会が意思決定支援ライフプランノートを作成・出版し、ご本人の意思決定支援を実施しております。このように、お元気なときから将来のことを考えていっていただきますよう、社会福祉協議会等と連携して進めていきたいと考えています。","id":"exchange-016"},{"speaker":"湯澤副委員長","kind":"質問・要望","question":"高齢者・障害者グループホーム２００人分の整備について、増設を要望しておりましたので、賛同いたします。交渉の際には、地域性を踏まえながら事前の打合せをするのが非常に重要だと考えますが、用地獲得に向けた課題と今後の取組について示すよう求めました。","respondent":"今井福祉部長","answer":"民生委員をはじめ、住民の皆様に丁寧に説明を重ねて、今後も整備の必要性を説明してまいります。事業者またはオーナーに、そのようなことを周知強化いたしまして、今後の障害者グループホームの整備を確実に進めていきたいと考えております。","id":"exchange-017"},{"speaker":"湯澤副委員長","kind":"質問・要望","question":"しっかり近隣住民の皆さんの理解を得て、整備目標の実現に向けて引き続き取り組んでいただきたいと要望いたします。区はデフリンピック大会の啓発活動をどのように行っていくのか、また区民の認知目標値があれば教えてほしいと求めました。","respondent":"山崎文化スポーツ振興部長","answer":"フラッグ応援の実施、壮行試合等々を通じて、啓発活動をしっかりやっていきたいと。振動と光によります、音を体感できるものなどで工夫して音楽会を実施したり、しっかり力を入れて実施してまいりたいと考えるところです。","id":"exchange-018"},{"speaker":"湯澤副委員長","kind":"質問","question":"例えば大会が開催される２０２５年までには、まずは職員の１００％を目指すべきと考えますが、ご見解をお伺いします。こういった手話とスポーツの実際のエピソードを理解促進の題材として取り入れることも検討されてはいかがかと思いますが、ご見解を示すよう求めました。","respondent":"山崎文化スポーツ振興部長","answer":"手話の人気の高まりといったものも、ひとつ、区の施策に取り込んで相乗効果を狙う視点というのは必要かなと思ったところです。様々、福祉部をはじめとしまして庁内連携を図るなど、工夫できるものは対応・検討して、力強く啓発をしてまいりたいと思うところです。","id":"exchange-019"},{"speaker":"湯澤副委員長","kind":"提案","question":"様々ご提案させていただきましたが、手話の理解促進が２３区トップクラスとなるような取組を期待いたしまして、私からの質問を終わります。ありがとうございましたとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-020"},{"speaker":"鈴木（真）委員","kind":"質問","question":"就任後間もない時点での編成であり、大変なご苦労や、十分満足のいくものではなかったかとも思いますが、いかがでしょうか。森澤区長として、この長期基本計画に対してどのように捉えているのかについてお伺いします。","respondent":"森澤区長","answer":"４つの重点政策を中心に、ウェルビーイングの向上に向けて、積極的に区政を前に進めていきたい。このように考えております。","id":"exchange-021"},{"speaker":"鈴木（真）委員","kind":"質問","question":"しかし、区長の任期４年間のうち２年間が、区長の区民に対する思いを実施していくには厳しいのではないかと感じております。「誰もが生きがいを感じ、令和５年度中に総合実施計画の検討を行うべきではないかと考えますが、いかがか尋ねました。","respondent":"久保田企画部長","answer":"総合実施計画は、基本構想と長期基本計画が示します基本方針や政策に沿って、令和６年度までの３か年の行政計画であります。総合実施計画の改定作業は、令和５年度の区政に関するアンケート、令和６年度に行っていきたいと考えているところです。","id":"exchange-022"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"ただ、やはり先ほど申し上げたように、区長の方針が出てくる中で、計画の前倒し、また改定するのは当然ではないかと私は思います。新たな方向性を出していってほしいと求めましたが、その辺をもう一回お答えいただいてよろしいか尋ねました。","respondent":"久保田企画部長","answer":"総合実施計画に基づきまして様々な事業を計画していますけれども、０歳児おむつ宅配定期訪問事業など、子育て支援に力を入れて進めているところです。","id":"exchange-023"},{"speaker":"鈴木（真）委員","kind":"質問","question":"改めて別の質問ですが、当初予算案のプレス発表にモデル事業実施が示されていました。今後の品川区としてのモデル事業、また新規事業ということで考えたとき、どのように考えているか、その点についても説明を求めました。","respondent":"久保田企画部長","answer":"モデル事業に関する認識ですけれども、事業目標や対象・効果等を検証しまして、よりよい事業スキームを進めていくために必要な取組と考えています。時代に合わせて変えていきたいという考えもありますので、モデル事業の実施も含め、積極的な事業展開に努めてまいります。","id":"exchange-024"},{"speaker":"鈴木（真）委員","kind":"質問","question":"ただ、モデル事業の実施や新たな事業を立ち上げるためには、事業に関わる職員の方の数の面での問題はないでしょうか。そして、一部の職員の方に過度な負担がかからないような体制づくりを希望しますが、いかがか尋ねました。","respondent":"堀越総務部長","answer":"それから、これも同じような考え方でございまして、事業を推進する対応を図る上で必要な人材をしっかりと確保していきたいと思ってあります。","id":"exchange-025"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"都が実施した場合、都からの補助金は、歳出予算４億９,０００万円の２分の１、２億４,５００万円の歳入が見込まれると考えてよろしいのでしょうか。２億４,５００万円は一般財源からの支出であり、ぜひ子育て関係の別途事業に上乗せしてほしいと求めましたが、いかがか尋ねました。","respondent":"柏原子ども未来部長","answer":"考えているところが実行された場合には、２億３,４００万円の歳入の見込みというところで、考えているものです。今後、様々な施策展開を検討していますので、そうした事業にぜひ活用していきたいというところで検討してまいりたいと思っているところです。","id":"exchange-026"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"この６億円を子育てに使っていただきたいと、私は令和元年の決算特別委員会で要望いたしました。その要望に対し、引き続き保育の質の向上に向けて様々な事業展開をしていきたい」とのご答弁を頂きました。","respondent":"柏原子ども未来部長","answer":"その後、区独自の施策といたしましては、例えば保育園での特別支援保育の巡回相談の拡充。在園児のＩＣＴ体験事業拡充、区の独自施策についても、そういった財源を保育の質の向上に向けて使わせていただいたといったところです。","id":"exchange-027"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"もう一点、子育て支援についてお伺いいたします。親が子どもの病気のケアを実地に学ぶ、病気の子どものケア教室の実現を、本会議や委員会においても要望しております。","respondent":"柏原子ども未来部長、福内健康推進部長","answer":"今後、エリアごとの病児保育の施設といいますか、そういったところの拡充に向けては、随時検討を続けているといったところです。品川区子ども・子育て支援事業計画といった中で、その拡充に向けて検討を進めていきたいといったところで… 今年の２月の品川保健センターの乳幼児健診で、服薬の情報の入手方法、服薬について知りたい時期等についてアンケートを実施したところです。","id":"exchange-028"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"先ほどの病児保育ですが、第二期品川区子ども・子育て支援事業計画ということですが、これは令和２年度から６年度までです。この計画で改定するということは、実施は令和７年度以降になると考えてしまうのではないかと思うのですが、その辺はいかがか尋ねました。","respondent":"柏原子ども未来部長","answer":"第二期品川区子ども・子育て支援事業計画は、令和２年度から６年度の計画ですけれども、計画そのものの見直しを行ってあります。そうした中で、実際にその施設を進めていくときには、柔軟な対応を区としては図っていきたいというところで考えているものです。","id":"exchange-029"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"中間見直しということで、ぜひ検討を早めに進めてほしいと求めましたので、これは要望します。八潮南特別養護老人ホームについては、当初の運営設計が見込みのとおりいかず、運営が厳しかったと伺っています。","respondent":"今井福祉部長","answer":"令和５年度となりますが、既存部分については日陰等の住環境を考慮しまして、合計で約１５０床を整備する予定です。今後の特別支援学校の卒業生の受皿としてのニーズに応えるため、今回の増改築計画に合わせ、検討しております。","id":"exchange-030"},{"speaker":"鈴木（真）委員","kind":"質問","question":"特別養護老人ホームについて、お伺いいたします。併せて、個室と多床室の利用料、また多床室に対する入所希望についてもお聞きいたします。","respondent":"今井福祉部長","answer":"直近の申込みにおきまして、多床室のニーズですけれども、全体の約半分、５０％程度の方が多床室のみを希望されている状況です。こうしたニーズも勘案しながら、今回の増改築計画では、多床室を可能な範囲で残す計画と考えております。","id":"exchange-031"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"どの程度の医療的ケアが必要な方への対応ができるのか、また、そのための地域連携はどうなっているのでしょうか。以前から通所の日数を増やしていただきたいとの要望もお受けしていますが、現在の通所状況とレスパイト事業の実績についても示すよう求めました。","respondent":"今井福祉部長","answer":"今後も、個々の健康状態に合わせてご相談の上、対応していきたいと考えております。医療的ケアが必要な方への対応のための地域連携につきましては、令和４年度から、保護者や職員からの相談にも対応しています。","id":"exchange-032"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"障害児の保護者の就労支援や、一時休息の場を提供する日中一時支援は３事業者だと思いますが、就労する方も増えていると聞いています。こちらの状況についてもおっしゃっていただくよう求めました。","respondent":"今井福祉部長","answer":"保護者の就労の増加により、まだ区としては整備を進め、開設していきたいという状況と認識しております。支援の質の確保等に一定の課題があることから、現在担うべき役割や機能、対象者数と今後の在り方を検討していると聞いております。","id":"exchange-033"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"私どもの会派の澤田委員からも、その中でもインクルーシブ遊具というものの活用もしてほしいと求めましたので、これは要望とします。平成２８年４月の熊本地震の後、お話を伺っていた中で、非常に大きな課題であると感じました。","respondent":"滝澤災害対策担当部長","answer":"そして備蓄倉庫や避難倉庫などへの輸送、さらには区内避難施設や備蓄倉庫における在庫管理に至るまでを、１つの物流業者に委託しております。令和４年度の新たな物流体制における実績を踏まえまして、本年２月には、災害時にも体制を強化したところであります。","id":"exchange-034"},{"speaker":"鈴木（真）委員","kind":"質問","question":"令和５年度に実施予定となっておりますが、どういった物資、また機材を入れていくのでしょうか。その活用について、どのように輸送体制の強化につながっていくのかについても示すよう求めました。","respondent":"滝澤災害対策担当部長","answer":"５２か所の区民避難所の倉庫などは、新年度から借り上げ予定の民間倉庫は、効果的な物資を区民避難所などへ届ける体制を構築するものであります。","id":"exchange-035"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"これらの支援物資は、どのように災害時の輸送拠点に集約することになるのでしょうか。もう一点、協定は輸送以外にも数多くあると思いますが、種類と件数についても示すよう求めました。","respondent":"滝澤災害対策担当部長","answer":"民間業者との連携についてでありますが、大規模災害時における支援物資の輸送や在庫管理の業務などを円滑に行うためには、物流計画の専門家や。災害時の効率的な物流システムの構築に努めるとともに、協定事業者と連携し、さらなる物流体制の強化を図ってまいります。","id":"exchange-036"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"支援物資が避難所に届かなかったという過去の大規模災害の教訓を活かし、引き続き、輸送体制の強化を図ってほしいと求めました。そこで、災害対策担当部長が様々な場面で体験されたご苦労を品川区の防災に活かしてほしいと求めましたが、いかがか尋ねました。","respondent":"滝澤災害対策担当部長","answer":"その中で、発災から１週間程度経過した頃からの避難者への生活支援や、被害を受け混乱している自治体の対応なども目の当たりにさせていただきました。引き続き、区長・副区長のご指導を受けながら、災害対策における先進自治体を目指し、その体制整備に尽力してまいります。","id":"exchange-037"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"これらのイベントと、この広場が連携できるよう、早くから折衝するべきだと思いますが、お考えをお聞きします。何回も要望しておりますが、さらなるご努力をお願いいたしますが、この点につきましてもお答えをお願いいたします。","respondent":"有江都市整備推進担当部長","answer":"具体的な整備内容を検討するとともに、関係者との協議を行っており、令和５年度中に整備計画として取りまとめていく予定です。今後とも、地域と調整を図りながら、大井町駅周辺全体の活性化につながるよう、検討を進めてまいります。","id":"exchange-038"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"ＪＲ東日本の赤レンガ車庫の存続を求める声もありますが、新庁舎のどこかにレガシーとして残すような検討はできないでしょうか。多額の寄附を求めるのではなく、新庁舎の建設を皆さんでお祝いしたいという気持ちからの考えです。","respondent":"榎本新庁舎整備担当部長","answer":"名入れをしたレンガが老朽化した場合に、その対応策等もあらかじめ検討しておく必要があると考えています。様々な工夫をして、新庁舎建設に当たって区民の思いを何らかの形で表せるような寄附の取組を幅広く検討していきたいと考えております。","id":"exchange-039"},{"speaker":"鈴木（真）委員","kind":"質問","question":"私の議会での質問はこれで最後となりましたが、「新時代のしながわ」を推し進めていただくことを希望いたしまして、質問を終わります。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-040"},{"speaker":"新妻委員","kind":"質問","question":"併せて、その中で展開される主要な子育て支援に関する事業を伺います。このような中、区長が子育て支援を第一に取り組む意義をお伺いいたします。","respondent":"久保田企画部長","answer":"子ども支援を第一に取り組む意義ですが、経済活動の衰退だけではなく、地域や社会全体の活力が失われかねないと認識しております。国や東京都においても重要課題と認識しておりまして、様々な施策の実施に向け、検討を進めております。","id":"exchange-041"},{"speaker":"新妻委員","kind":"質問・要望","question":"区議会公明党の重点要望であり、第２子の保育料の無償化は、都議会公明党が一昨年の都議選で１番目に掲げた公約です。そして、今後の品川区の所得制限なしの考え方と、ベーシックサービスについて区の認識をお伺いいたします。","respondent":"久保田企画部長","answer":"子育て支援施策の中で所得制限がある事業についてですが、区で実施しております児童手当や認証保育所保育料助成、また。区としましては、今後の議論、動向等を注視してまいりたいと考えているところです。","id":"exchange-042"},{"speaker":"新妻委員","kind":"質問・要望","question":"次に、０歳児おむつ宅配定期訪問と、区議会公明党が早期の実施を求めていた出産・子育て応援事業についてです。そこで、出産したばかりのご家庭が、どの支援を利用できるのか混乱のないように、分かりやすい丁寧な周知を求めますが、見解を伺います。","respondent":"福内健康推進部長","answer":"本事業はできるだけ早期に実施したいと考えていますが、事業の開始時期も含め、検討しているところです。ネウボラ面談の際に説明するとともに、受けられるサービスを掲載するなど、丁寧な周知に努めてまいります。","id":"exchange-043"},{"speaker":"新妻委員","kind":"質問・要望","question":"その新規事業を注視し、区民が利用できるよう、分かりやすい周知を要望します。さらに、区として不妊治療の支援拡充も視野に入れていただきたいと要望しますが、見解を伺います。","respondent":"福内健康推進部長","answer":"調査の協力と費用の助成を行い、また凍結卵子を活用した生殖補助医療への助成も実施し、自己負担の在り方を検討するという事業内容とのことです。都が今年度１月から開始した精神医療の助成につきましても、十分に周知に努めてまいります。","id":"exchange-044"},{"speaker":"新妻委員","kind":"質問・要望","question":"見解を伺います。事実婚の方々への区のお考えをお伺いいたします。","respondent":"堀越総務部長","answer":"それから２点目の、民間での活用に関してですけれども、そういったところを活用して積極的に取り組んでまいりたいと思ってあります。そのような考え方の中で、生活上の不便の軽減に努めていきたいと、ご協力いただけるよう取り組んでまいりたいと思ってあります。","id":"exchange-045"},{"speaker":"新妻委員","kind":"質問・要望","question":"庁舎内に１地区の担当課が設置されることは珍しく、区が八潮地域のこれからに力を注いでいることが分かります。これまで開催された八潮みらい懇談会と部課長級の庁内会議の開催数と、会議の内容、そして令和５年度の開催について示すよう求めました。","respondent":"伊崎地域振興部長","answer":"八潮みらい懇談会の令和５年度につきましては、意見交換を行いながら、各団体の取組につなげていく予定としております。各所管との連携を図りながら、必要に応じて情報提供を行うなど、丁寧に進めるように努めてまいります。","id":"exchange-046"},{"speaker":"新妻委員","kind":"質問・要望","question":"款別審査でも伺いましたが、２０２５年度の開設に向けて、つくり上げていってほしいと要望します。併せて見解を伺います。","respondent":"柏原子ども未来部長","answer":"説明や、こちらとしても考えてありますので、そのように進めていければと思っているところです。具体的にはこれからの検討というところになってまいりますので、近隣のご利用等も含めて検討を進めていければと思ってあります。","id":"exchange-047"},{"speaker":"新妻委員","kind":"意見","question":"八潮団地内には、平成２４年に開設された、品川区重症心身障害者通所事業所ピッコロがあります。先ほどの総括質疑では移転とありましたけれども、どのような検討をされているのか、お知らせくださいとの意見を述べました。","respondent":"今井福祉部長","answer":"特別支援学校の卒業生の受皿としてということですが、生活介護の拡充を求める声も上がっていることから、同施設内の移転も含めて検討しています。今後、利用者数の拡充も含めて、実際に運営する事業者または利用の状況を踏まえて、十分検討していきたいと考えています。","id":"exchange-048"},{"speaker":"新妻委員","kind":"質問・要望","question":"併せて伺ってまいります。部課長級の庁内会議でも共有していただき、地域の声がいち早く具現化されるよう要望いたしますが、見解を伺います。","respondent":"今井福祉部長、中村都市環境部長","answer":"八潮南特別養護老人ホームの脇に駐車している２台のバスのうち１台につきましては、今、調整を進めているところです。今後も利用者や障害者団体の皆様の声を聞きながら、よりよい運営を支援してまいります。 八潮五丁目地区全戸配布により実施してきまして、７５名の参加の下、ご意見を頂きながら今検討してまいったところです。令和５年６月中の策定・公表を目標として、現在、取組を行っているところです。","id":"exchange-049"},{"speaker":"新妻委員","kind":"確認","question":"ピッコロのバスの件は、２０２２年度からピッコロの前にとめられるようになるということで、確認させていただきました。これらに関して、区の認識と対応をお伺いいたします。","respondent":"中村都市環境部長","answer":"来年度も勝島人道橋につきまして、引き続き設計および関係機関との調整を進めて、令和６年度の着工に向けて検討を行っていくという考えです。客席が約７５０席のミュージカル劇場が予定されているということと、その劇場の隣に商業施設が設置されるということ、あと。","id":"exchange-050"},{"speaker":"新妻委員","kind":"質問・要望","question":"今後も勝島地域の発展に向けてご尽力ほしいと求めました。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-051"},{"speaker":"こんの委員","kind":"質問・要望","question":"品川区が掲げる、「一人ひとりをささえ、伸ばす子育て・教育で選ばれるしながわ」にふさわしい幼児教育の体制を求め、質問いたします。そこでまず、品川区における幼児教育の重要性および必要性について、ご見解をお聞きします。","respondent":"柏原子ども未来部長","answer":"生涯にわたる人格形成および学習の基礎を培うといったところで大変重要なものであるという認識で、区としても思っているところです。区の幼児教育のパイオニアといいますか、先駆者、第一人者といったところでの役割を果たしていただいているものと考えています。","id":"exchange-052"},{"speaker":"こんの委員","kind":"提案","question":"伺います。教員増員のため、運営費の増額等、支援の拡充を提案しますとの意見を述べました。","respondent":"柏原子ども未来部長","answer":"各園における、どういった支援が必要なのかというのをよくお聞きして、必要な支援というものを検討してまいりたいと思ってあります。特別支援保育等の部分についても同様でございまして、どういった支援ができるかというのをそれぞれ検討しながら進めていければと思ってあります。","id":"exchange-053"},{"speaker":"こんの委員","kind":"質問・要望","question":"相談後に保護者や園児を適切なサポートにつなぐ体制がないため、園をサポートする体制が課題となっていますが、区の認識を伺います。今後はアウトリーチの観点から、私立幼稚園に対しても、区立と同様の訪問支援の実施を要望します。","respondent":"今井福祉部長","answer":"保護者のご依頼によりまして実施するもので、子どもへの直接支援と職員への間接支援を行うほか、保護者の不安を取り除く支援を行っているものです。今後、各所管課や品川児童学園の運営事業者と連携して、お子さんや保護者へのきめ細やかな支援を行ってまいります。","id":"exchange-054"},{"speaker":"こんの委員","kind":"質問","question":"初期消火体制の強化について伺います。そこでまず、品川区における火災の状況について、年間の総件数、１日の平均件数、総焼失面積など、現状を示すよう求めました。","respondent":"滝澤災害対策担当部長","answer":"死傷者は３６名、うち亡くなられた方は６名です。電気関係によるものが４割、たばこによるものが２割、ガスコンロによるものが１割です。","id":"exchange-055"},{"speaker":"こんの委員","kind":"質問・要望","question":"街かど消火栓は、区議会公明党が、２０１３年の第１回定例会より、幾度となく初期消火体制の強化を求めてきた中で、モデル配備されたものです。そこで、確認します。","respondent":"滝澤災害対策担当部長","answer":"区民消火隊やミニポンプ隊に配備した、それぞれの機器などの定期的な設備点検を実施して、初期消火機材の確実な稼働に努めてまいります。加えて、消火活動に係る区民への啓発や、区民消火隊などへの訓練実施の支援に力を入れてまいります。","id":"exchange-056"},{"speaker":"こんの委員","kind":"提案","question":"Ｃ級ポンプについては筒先にガンタイプノズルの導入検討を、また街かど消火栓については、例えば木密地域や防災広場への配備の検討を提案します。それぞれ、ご見解を説明するよう求めました。","respondent":"滝澤災害対策担当部長","answer":"ご提案いただいたノズルについては引き続き細部の情報収集を実施いたしますが、消防団による訓練指導を含め、課題があるものと認識しております。街頭などに配備する場合は、設置場所の確保や管理方法に課題があるものと認識しております。","id":"exchange-057"},{"speaker":"こんの委員","kind":"質問・要望","question":"そこでまず、優良マンションの認定事業について、区独自基準の具体的な内容と基準を設ける狙いについてお伺いします。救助や救出に必要なバールや工具、簡易トイレなどの購入費を助成するなど、インセンティブを検討してはいかがか尋ねました。","respondent":"中村都市環境部長、滝澤災害対策担当部長","answer":"で、地域の中の一員であるという認識の下に、地域コミュニティの重要性というものをやはり理解していただくことが重要だと考えております。災害への備えも重要であると考えまして… 令和５年度からは、支援の対象となる世帯数も１３万１,０００世帯に倍増させる予定であります。","id":"exchange-058"},{"speaker":"こんの委員","kind":"質問・要望","question":"最後に、若者支援についてお尋ねします。若者の生活困窮について、また住環境をめぐる現状について、区のご所見を伺います。","respondent":"久保田企画部長、今井福祉部長","answer":"コロナ禍や物価高騰等は区民を直撃し、経済的な負担や不安を抱える方が多いと認識しています。生活や、住環境の確保に困窮しているものと、区として認識しているものです。 私からは、住居確保給付金の利用状況と、困窮する若者への福祉的な支援についてお答えいたします。特に若い方々については、履歴書の書き方支援、面接シミュレーションなどを行う就労準備支援をご利用いただいているところです。","id":"exchange-059"},{"speaker":"こんの委員","kind":"質問・要望","question":"そこで今後、若者への支援を考える上で、若者の生活困窮の実態調査を検討してはいかがでしょうか、ご所見を伺います。今後、低所得の若者が安定した生活の基盤を築けるよう、セーフティネット住宅家賃低廉化補助による積極的な家賃助成を要望します。","respondent":"久保田企画部長、中村都市環境部長","answer":"若者の生活困窮実態調査の実施についてお答えいたします。委員ご質問の、若者の生活困窮実態調査につきましては、各窓口での把握状況や今後の社会経済情勢等を踏まえ、必要性を含め検討してまいります。 所得の低い方など、登録された民間住宅ということで、区としてもこうした方々への支援は非常に重要なことだと考えております。自立を促進するための区の政策としても、この制度を適宜適切に実施してまいります。","id":"exchange-060"},{"speaker":"石田委員","kind":"質問・要望","question":"私からは、羽田新ルート撤回と、２３区で最低の整備率の障害者グループホームと特別養護老人ホームの増設を求めて質問します。この間の一般質問で羽田新ルートについて、反対表明すべきと求めてきましたが、反対とは絶対に言わない。","respondent":"中村都市環境部長","answer":"騒音環境軽減の取組、さらに区民への丁寧な周知、そして説明を継続していただくように求め続けてまいりました。したがいまして、賛否といったことではなく、区が求めていることに対してしっかりと国として対応していただくといった考えです。","id":"exchange-061"},{"speaker":"石田委員","kind":"質問・要望","question":"なぜ言わないのか伺ったのと、あと、森澤区長は羽田新ルートに賛成なのか、反対なのか。これを伺いましたので、明確にお答えほしいと求めました。","respondent":"中村都市環境部長","answer":"現在、区の求めにより固定化回避検討会も実施されているという現状を踏まえるということと、それから。そういった現状におきまして、現在、賛否ということではなくて、国に対してしっかりと対応していただくといった立場です。","id":"exchange-062"},{"speaker":"石田委員","kind":"質問・要望","question":"区民の皆さんが３年にわたって被害を受けて、そして撤回を求める声を上げていますけれども、結局、どちらなのでしょうか。伺います。","respondent":"中村都市環境部長","answer":"そして、そのご意見を分析し、具体的な解決策を検討するよう、国に働きかけてまいります。アンケートの内容については検討中ですけれども、分析結果を踏まえ、国に対応を求めてまいります。","id":"exchange-063"},{"speaker":"石田委員","kind":"質問・要望","question":"区としては、反対も撤回も求めないということでしょうか。改めて国へ、羽田新ルートへの反対表明をすることを求めますが、いかがか尋ねました。","respondent":"中村都市環境部長","answer":"区としましては、現在、国により検討が進められている固定化回避検討会において、早急に結論を出すように国に求め続けております。区として区民アンケートにより、区民の皆さんの地域特性などの実情を把握しまして、国に対し必要な対応を求めていくといった所存です。","id":"exchange-064"},{"speaker":"石田委員","kind":"質問・要望","question":"森澤区長が掲げる障害者グループホーム１００人分は、いつ頃どのように進めようとしているのか、伺います。伺います。","respondent":"今井福祉部長","answer":"この方針に加えて、事業者が活用しやすい手法を検討することで、実際の整備を促進してまいりたいと考えております。今後も、障害者の方のご希望を尊重し、個別に対応していく考えに変わりはございません。","id":"exchange-065"},{"speaker":"石田委員","kind":"質問・要望","question":"区が責任を持って、区立で増設することが必要だと思いますが、いかがでしょうか。重度の方も入れるグループホームの今後の計画はあるのか、伺います。","respondent":"今井福祉部長","answer":"出石つばさの家で、区内にあります民設の障害者グループホームと連携を図り、適切なサービスの実施や人材確保に努めていく考えです。令和６年４月に開設を予定しております出石つばさの家につきましては、今後、入所に向けて進めてまいります。","id":"exchange-066"},{"speaker":"石田委員","kind":"質問・要望","question":"特別養護老人ホームについては、民生費でも伺いましたが、「９０歳になっても半分が入れない。待機者ゼロになるのか、足りないと思いますが、いかがか尋ねました。","respondent":"今井福祉部長","answer":"民生費の中でご説明しました、登録名簿を区から各施設へ提供し、各施設から順番にお声がけする仕組みになっております。小山台でも整備を進めるところですが、必要に応じて入所をご利用いただけるよう、引き続きニーズ把握を行ってまいります。","id":"exchange-067"},{"speaker":"石田委員","kind":"質問・要望","question":"もう分かっている、確定している数字で、取り下げている方の人数を伺いたいと思うのです。それをお聞きしたので、お答えほしいと求めました。","respondent":"今井福祉部長","answer":"は施設などの仕組みを整えまして、なるべく品川区の中で、身近なところで暮らしていただけるように進めてまいりたいと考えています。区としても、入居の状況につきましては、一定、整備を進めて改善していきたいという考えに違いはございません。","id":"exchange-068"},{"speaker":"石田委員","kind":"質問・要望","question":"家族が特別養護老人ホームに入れずに相談に来た５０代男性から話を伺いました。第９期の介護保険事業計画に、小山台住宅等跡地以外の増設計画はあるのか、伺います。","respondent":"今井福祉部長","answer":"特別養護老人ホームを含めた施設の整備につきましては、今後も取り組んでまいりたいと考えております。第９期の介護保険事業計画を立てるに当たりましては、現在のニーズなどを踏まえた上で適切な計画を立ててまいりたいと考えております。","id":"exchange-069"},{"speaker":"石田委員","kind":"質問・要望","question":"コロナの影響や物価高騰で暮らしが大変なときに、自治体がすべきことは福祉や社会保障を充実させて暮らしを支えることです。福祉・暮らし最優先の区政に転換こそと求めて質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-070"},{"speaker":"中塚副委員長","kind":"質問","question":"そして、現在品川区で暮らしている、住んでいる人にも、選ばれるというのはどういう意味なのか、伺います。そして、「攻めと守り、戦略的な予算編成」と言いますが、攻めとは具体的にどの事業か、守りとは具体的にどの事業か、それぞれ伺います。","respondent":"久保田企画部長","answer":"令和４年度策定の総合実施計画の推計値が最新であり、総人口は２０４１年にピークを迎えると推計しており、想定を書いたものではありません。経常的に必要な事業や公共施設の老朽対応、これまで確実に実施してきました事業を滞ることなく進めていくこと、基金の積立てなども行い。","id":"exchange-071"},{"speaker":"中塚副委員長","kind":"質問","question":"３つの無償化で、再開発によるタワーマンションへの転入を進め、開発マンションの販売を伸ばしたいのが狙いなのではないでしょうか。「選ばれるしながわ」とは、開発マンションを購入させて人口増を進めたい、品川区のまちづくり戦略なのか、伺います。","respondent":"久保田企画部長","answer":"３つの無償化をはじめ、様々な新規事業を実施し、取り組んでいくことと考えております。品川区が進める各施策を、転居先を選ぶときの判断基準の一つとしてお考えいただければと考えているものです。","id":"exchange-072"},{"speaker":"中塚副委員長","kind":"質問","question":"なぜならば、森澤区長の施政方針からは、住民福祉の言葉が一言もないからです。区長が考える「新時代のしながわ」とは、住民福祉の増進をどのように位置づけているのか伺います。","respondent":"久保田企画部長","answer":"区長が施政方針で述べました、健康、住まい等の安定を図るというものです。４つの重点施策をはじめ、施政方針に掲げる各施策を推進しまして、福祉の増進に努めてまいります。","id":"exchange-073"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"区長は区立３幼稚園の閉園をなぜ撤回しないのか、理由を伺います。こうした前区長の対応は適切だったと思うのか、私は反省すべきだと思いますが、いかがか尋ねました。","respondent":"柏原子ども未来部長","answer":"幼稚園のニーズの変化に対応して、単独で設置の３園の閉園の中止ということは考えてはございませんけれども、幼保一体施設の幼稚園につきましては。保護者会や未就園児の会でのご説明、進め方に対して、柔軟な対応を取らせていただきました。","id":"exchange-074"},{"speaker":"中塚副委員長","kind":"質問","question":"私が伺ったのは、区立３幼稚園閉園をなぜ森澤区長は撤回しないのかと伺いました。保護者の声を受けて柔軟な対応と言いましたが、やはり適切ではなかったと思っているのか、反省はあるのか、改めて伺います。","respondent":"柏原子ども未来部長","answer":"そういったことに対しましては、そういったお言葉を受け止めて、柔軟な対応等もさせていただきました。今後につきましては、より適切な進め方というのを考えていきたいと思ってあります。","id":"exchange-075"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"検討内容ですが、具体的に区立園の名前を挙げて、閉園する園数も具体的に数字を挙げているのか伺います。数字を伺いますが、認可保育園の４月入園について、第１次および第２次の不承諾通知数は何人か。","respondent":"柏原子ども未来部長","answer":"その検討の内容です。区内のどの地域にも同じ子育て支援が提供できるような計画の策定に向けて、そのありようを検討しているといったものです。","id":"exchange-076"},{"speaker":"中塚副委員長","kind":"質問","question":"私が伺ったのは、今までとこれからと、その役割に何か違いがあるのかしっかりご説明ください。先ほど、具体的な区立園名を挙げて検討しているのか、数を挙げて検討しているのかと伺いました。","respondent":"柏原子ども未来部長","answer":"現在の役割というのは、新しいニーズ、状況の変化にどう対応するのが区立保育園のあり方かというところを検討しているといったところです。あり方検討の中の内容のところですけれども、その方向性、ありようを検討しているといったものです。","id":"exchange-077"},{"speaker":"中塚副委員長","kind":"質問","question":"４月入園でこの状態ですから、年度途中はさらに困難。４月入園と併せて、品川区の役割だと思いますが、いかがか尋ねました。","respondent":"柏原子ども未来部長","answer":"我々が検討しています、区として対応できるかというところ、我々はそこが求められているというところも１つ重要な視点だと考えています。","id":"exchange-078"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"これを追い出しと呼ばずに何と呼ぶのか、伺います。根拠条例や裁判の経過なども含めて、説明を求めます。","respondent":"有江都市整備推進担当部長","answer":"原則として等価で、新しくできる再開発ビルの床の権利に置き換える手続でございまして、従前の権利は都市再開発法第８７条の規定によりなくなります。区としましては、法令に基づく手続を適正に進めるとともに、事業主体であります再開発組合に対して働きかけていく考えです。","id":"exchange-079"},{"speaker":"中塚副委員長","kind":"質問","question":"追い出しそのものだと思いますが、なぜこれを追い出しとは認めないのか、改めて伺います。そして、不法占拠や裁判について、つまり誰が誰を不法占拠として裁判で訴え、誰がその家から出ることになるのか説明するよう求めました。","respondent":"有江都市整備推進担当部長","answer":"にぎわいの創出など、まちの課題を解決するために、地域主体で検討されているまちづくりにつきましては支援していく考えです。裁判につきましては、我々は区の立場としてご回答という立場にございませんので、答弁は控えさせていただきたいと思います。","id":"exchange-080"},{"speaker":"中塚副委員長","kind":"質問","question":"こうした追い出しの実態をなぜ認めないのか、改めて伺います。いかがか尋ねました。","respondent":"有江都市整備推進担当部長","answer":"緊急性が高い地域において、適切な補助金を活用して事業が実施されるものでありますので、開発企業の利益を増やすためのものとは考えてございません。","id":"exchange-081"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"「区民とともに進める新時代のしながわ」と言いますが、一体どこが「区民とともに」でしょうか。再開発事業の中止を求めて、質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-082"},{"speaker":"松永委員","kind":"質問","question":"早期発見によって進行を遅らせることは可能であるとお聞きしますが、約７３１万円についての、どのように推移されているのでしょうか。そして、もの忘れ検診を受けたがらない方もおられるとお聞きしますが、本区としてどのような対策を取られているのか尋ねました。","respondent":"今井福祉部長","answer":"令和４年現在は１５医療機関でございましたが、令和５年度は、相談員も含めた拡充を検討しております。認知症初期集中支援チームが対応して、早期発見と医療介護サービスにつながるように支援を進めていきたいと考えております。","id":"exchange-083"},{"speaker":"松永委員","kind":"質問","question":"先ほど伺いましたが、もの忘れ検診で早期発見することができた方、いわゆる認知症と診断された方について、どのくらいおられるのでしょうか。伺います。","respondent":"今井福祉部長","answer":"今後も認知症高齢者の増加が高齢者人口の増加とともに見込まれております。先ほど２４６人の方が受診されたと申しましたが、何らかの疑いありとの診断を受けた方は、５４人という結果でございました。","id":"exchange-084"},{"speaker":"松永委員","kind":"質問","question":"続けて、認知症カフェについて伺います。今後についても伺います。","respondent":"今井福祉部長","answer":"令和５年度につきましては、家族介護者向けの認知症家族向け勉強会を新たに開催予定でおります。令和５年度におきましては、それから質の充実について、区としても支援してまいりたいと考えております。","id":"exchange-085"},{"speaker":"松永委員","kind":"質問","question":"現在、認知症サポーター養成講座を修了された方はどのくらいおられるのでしょうか。そして、修了された方について、運転免許のように更新やレベルアップを図る取組があるのか尋ねました。","respondent":"今井福祉部長","answer":"現在、１２月までの受講者数は７１１人ですが、これまで延べ１万９,７７１人の方に受講していただきました。ステップアップ講座を実施しているとともに、認知症サポーター養成講座受講修了者の方が自ら様々な検討を進めておられるところです。","id":"exchange-086"},{"speaker":"松永委員","kind":"提案","question":"しなバスの試行運行が開始されてから約１年が経過したのですが、現在の利用状況と収支率はどのくらいでしょうか。併せて伺いますとの意見を述べました。","respondent":"中村都市環境部長","answer":"予算書に記載のコミュニティバス試行運行実施経費ですが、８,９０３万７,０００円ということで、６,１３６万３,０００円。そして、シルバーパスを見込みますと２８.６％といった状況になっております。","id":"exchange-087"},{"speaker":"松永委員","kind":"質問・要望","question":"なぜ、このことを質問したかといいますと、この試行運行におかれましては、収支率が５０％を超えなければ、廃止も含めた見直しと伺っていたからです。しなバスを検討していく過程で、区民アンケートやワークショップなど、ルートに関する様々な要望があったとお聞きしております。","respondent":"中村都市環境部長","answer":"導入検討の中で頂きました、こういった方針の策定や、あと候補ルートの選定の際にも反映してまいりました。残りの２路線につきましても、実施できるかどうかというところはまだ不明ですけれども、検討を引き続きしていきたいと考えております。","id":"exchange-088"},{"speaker":"松永委員","kind":"質問","question":"今後こうしたボールを使った遊び場を増やしていくことは考えているのでしょうか。併せて伺います。","respondent":"稲田防災まちづくり部長","answer":"このキャッチボール場ですが、今までも地域の要望をお聞きし、広さや周辺の状況など条件を整理いたしまして設置してきたところです。","id":"exchange-089"},{"speaker":"松永委員","kind":"質問","question":"本区内に２２か所あるとのことですが、キャッチボールの音や声などについて、近隣住民からはどのような声が上がっているのでしょうか。そこで伺います。","respondent":"稲田防災まちづくり部長","answer":"天井部分、２２か所のキャッチボール場のうち１０か所で、天井部分にネットを設置している状況です。危険なボール遊びをしていて危ないとか、バットを振っているなど、利用のルールへの遵守の声が寄せられている現状があります。","id":"exchange-090"},{"speaker":"松永委員","kind":"質問・要望","question":"キャッチボール場の上部にネットがあり、対策が取られているところは、１０か所と伺いました。ぜひ、子どもたちが全力を出せるグラウンドにしていただきたいと考えていますが、区の今後の対策について示すよう求めました。","respondent":"稲田防災まちづくり部長","answer":"今後の対策の検討についてですが、まず１つは、バットによる打撃など、キャッチボール場では禁止している行為による場外への飛び出しもあります。","id":"exchange-091"},{"speaker":"松永委員","kind":"質問","question":"そうした中で、特に犬を飼われる方について伺いたいと思います。そこで、本区内にはドッグランはどのくらい設置されているのか尋ねました。","respondent":"稲田防災まちづくり部長","answer":"大井ふ頭中央海浜公園内の、しおさいドッグランというのがございまして、これが１か所あります。ペット用トイレの公園の設置状況についてですけれども、区が管理する公園におきましては、ペット用トイレの設置はないという状況です。","id":"exchange-092"},{"speaker":"松永委員","kind":"質問・要望","question":"そこでドッグランについてですが、広さや柵の高さなどの基準について決まりはあるのでしょうか。ドッグランをつくるに当たり、近隣住民への対策はどのようにされていかれるのか尋ねました。","respondent":"稲田防災まちづくり部長","answer":"近隣住民の方への対応ですが、ドッグランを設置するためには、公園の近隣にお住まいの方々の理解を得ることが不可欠です。ドッグランを設置していくとなれば、周辺住民の方々、十分な理解を得られるために丁寧な説明を行っていく必要があると考えているところです。","id":"exchange-093"},{"speaker":"松永委員","kind":"質問","question":"以前、私が質問させていただいた際、ペット同行避難ができる避難所は数か所だったかと思いますが、現在どのくらいあるのでしょうか。区内には５２か所の区民避難所があるとお聞きしますが、その中に、ペット同行避難ができる避難所は何か所あるのか尋ねました。","respondent":"滝澤災害対策担当部長","answer":"次に、令和３年度から開始している自主避難施設開設訓練において、ペットや同行避難者用のスペースを設置する訓練を行っております。令和４年９月に実施した東京都・品川区合同総合防災訓練の避難所運営訓練においても、ペット受入要領についての訓練を実施いたしました。","id":"exchange-094"},{"speaker":"松永委員","kind":"質問","question":"ここで質問ですが、今後本区は、ペット同行避難ができる避難所の方向性について、どのようにお考えでしょうか。例えばペットの同行をお断りする方法なども含めて、改定も視野に入れて進めていただければと思うのですが、いかがか尋ねました。","respondent":"滝澤災害対策担当部長","answer":"５２か所、全ての区民避難所において、避難所運営マニュアルにペットの同行避難に関する内容を整備してまいる所存であります。既にマニュアル改定が進められている区民避難所においても、ペット同行避難に係る訓練を実施し、検証と改定を行ってまいります。","id":"exchange-095"},{"speaker":"松永委員","kind":"質問","question":"そこで本区は、このペット用備蓄物資について、どのように考えているのでしょうか。ペットの同行避難についてですが、獣医師会やペットショップ、消防署等との連携はどのようにされているのか尋ねました。","respondent":"滝澤災害対策担当部長","answer":"今後は、地域の皆様の声を聞きながら、公助として確保すべき物資の必要性について検討してまいります。まだ具体的な連携を図れてはおりませんが、災害時におけるペット用備蓄物資の支援や、各種支援団体との連携を模索してまいります。","id":"exchange-096"},{"speaker":"松永委員","kind":"質問・要望","question":"そこで伺います。本区には現在どのくらいの私道があるのか尋ねました。","respondent":"中村都市環境部長","answer":"私道ですけれども、区内の私道の長さは、約１４５キロメートル。公道の長さが約３８０キロですので、およそ私道が３割、公道が７割ということになります。","id":"exchange-097"},{"speaker":"松永委員","kind":"質問","question":"そこで、私道を公道にしたい場合は、どのようにすればよろしいのでしょうか。この助成を行うための条件について併せて伺います。","respondent":"稲田防災まちづくり部長、中村都市環境部長","answer":"私道をお持ちの方、権利者の方々から、様々な理由により区道として寄附できないかというお問合せを頂くことがあります。周辺の交通状況など、現場状況等に鑑みながら、私道を区道に寄附する場合の検討が進められていくものです。 それから、道路の幅員が２.５メートル未満、そして１.２メートル以上のものは、工事費用の９０％を区が負担。このようになっております。","id":"exchange-098"},{"speaker":"松永委員","kind":"質問・要望","question":"ぜひ、こうした助成制度を区民の皆様に周知していただきたいと考えていますが、現在どういった取組をされているのでしょうか。そして、不動産、建設業の皆さんとの連携は取られているのか尋ねました。","respondent":"中村都市環境部長","answer":"そして、窓口に置いてあるチラシなどを基に地域へＰＲしていただくこともあります。改めまして、引き続き様々な機会を捉え、業者の方への協力をさらに求めてまいりたいと考えております。","id":"exchange-099"},{"speaker":"松永委員","kind":"意見","question":"こうしたトラブルを少しでも解消できるよう、しっかりと場所を把握し、不安のない住宅環境づくりに取り組んでほしいと求めました。以上で、イノベーションしながわの総括質疑を終わりますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-100"},{"speaker":"いながき委員","kind":"提案","question":"２０２３年度の予算は、１２月に区長が決まり、方向性について伺います。以上、３つ伺いますとの意見を述べました。","respondent":"久保田企画部長、黒田財政課長","answer":"区民とともに進める新しい品川区政を実現するスタート元年ということでありまして、可能な限り早期に、区民に対する情報提供を実施したものです。今後も、適正な情報公開の事務に努めてまいります。 事業の実施内容や規模について検討した上で、確保できる歳入の見込みなどを踏まえて、全体的な予算案として取りまとめております。緊急相談対応経費は、またプログラミング講座につきましては、参加人数の想定などを精査したものです。","id":"exchange-101"},{"speaker":"いながき委員","kind":"質問・要望","question":"それに関してもお伺いします。開発事業者に手厚く、福祉に厳しいと取られかねないと思われますが、以上３点、見解を伺います。","respondent":"久保田企画部長、黒田財政課長","answer":"１点目の情報公開、様々な広報媒体を使いまして、情報提供に努めてまいりました。できる限り早く、公開する提供するタイミングはありますけれども、区民の皆さんに知らせていきたいと考えております。令和４年度の予算と比べますと増額しておりますので、あくまでも所管の要求と予算案の差ですので、減額したというものではございません。","id":"exchange-102"},{"speaker":"いながき委員","kind":"質問","question":"これがなぜ、どこが減額となったのか、その理由と内容も伺います。生活者ネットワークの質問に対し答弁されましたが、昨年１２月２０日の第４回定例会での質疑で、見解を伺います。","respondent":"久保田企画部長","answer":"これらにつきましては、我々企画部としましても考え、こうした金額の予算の範囲の中で区民アンケートを実施していきたいと考えているところです。","id":"exchange-103"},{"speaker":"いながき委員","kind":"質問","question":"返信方法はどうなっているのでしょうか。その３点をお伺いします。","respondent":"久保田企画部長","answer":"教育委員会と連携しながら、学校を通じて実施していくということで、具体的な内容については検討しています。ネット回答等もありますので、そちらを活用していただくことで個人からの回答もできますし、個別の対応を図ってまいりたいと考えております。","id":"exchange-104"},{"speaker":"いながき委員","kind":"質問・要望","question":"返信だけでも個人別のものとしていただきたいというのと、アンケートはあくまでも区長部局で責任を持って実施してほしいと求めました。以上、見解を伺います。","respondent":"久保田企画部長","answer":"同調圧力等のお話もありましたが、子ども一人一人の意見を聞くためにどうしていこうかということで、検討しているものです。アンケートの実施は区長部局で実施するものでありまして、これらにつきまして教育委員会のご協力を頂きながら進めていきたいと考えているところです。","id":"exchange-105"},{"speaker":"いながき委員","kind":"質問・要望","question":"２０１９年８月に設立された羽田空港周辺振興協議会とはどういった団体でしょうか。見解を伺います。","respondent":"久保田企画部長、中村都市環境部長","answer":"アンケートの集計についてですが、私ども、区民一人一人の意見を大切にしまして、きちんと公平に、かつ、きちんと集計いたしまして実施いたしますので、ご心配の点には至らないと考えています。羽田空港周辺の地方公共団体が実施します周辺地域のさらなる発展・活性化に資することを目的に設立ということになっております。","id":"exchange-106"},{"speaker":"いながき委員","kind":"質問","question":"そもそも地方公共団体である品川区が、行政として差し障りがないのかと心配になりますが、その点はどのようにお考えでしょうか。見解を伺います。","respondent":"中村都市環境部長","answer":"防音工事に活用ですけれども、これは、これまで新飛行ルートの実施に伴いまして、区としても国へ要望してまいりました。今、国でしっかりと実施してきていただいたというところで、対象につきましては全て完了していただいたといった認識です。","id":"exchange-107"},{"speaker":"いながき委員","kind":"質問","question":"今後ほかにも任意団体の方から助成金のお話があった場合、区民や議会に先に示してほしい気がするのですけれども、それはいかがでしょうか。それも見解を、２つ伺います。","respondent":"中村都市環境部長","answer":"区が羽田空港と連携した地域振興の計画策定支援といった助成項目を活用しているということですので、それは、区が申請したものです。たしか以前にもお答えをしたかと思いますけれども、それから浜川公園、この協議会の助成を使う旨の報告をしていると認識しております。","id":"exchange-108"},{"speaker":"いながき委員","kind":"質問・要望","question":"検討した会議の議事録の開示を求めます。その見解も伺います。","respondent":"榎本新庁舎整備担当部長","answer":"もともとは１０月１７日に答申する予定でいたわけですけれども、答申日を先延ばしにして１２月１９日になったという形です。新庁舎建設候補予定地にどういう新庁舎を建てるかというのが大本ですので、また別途検討するということで、そういうふうに整理したものです。","id":"exchange-109"},{"speaker":"いながき委員","kind":"質問","question":"見解を伺います。見解を伺います。","respondent":"榎本新庁舎整備担当部長","answer":"変更という形で言っていますけれども、最新の官民連携手法を導入し、区民負担の軽減を進めていくという形にしたものです。逆に言うと、日頃の部課長との調整、区長との調整等について、全部、議事録をそろえているということはありません。","id":"exchange-110"},{"speaker":"いながき委員","kind":"質問","question":"計画変更になったという、その計画がどこに示されているのかというのをお尋ねしました。お伺いします。","respondent":"榎本新庁舎整備担当部長","answer":"計画変更になったというのがいまいち分からないのですけれども、建設予定地に新庁舎を整備するという答申内容そのものは変更しておりません。それで、跡地活用の考え方は、改めて付加的に項目を整理して示したというものです。","id":"exchange-111"},{"speaker":"いながき委員","kind":"質問","question":"第二庁舎の取扱いが、当初残すというところから変更になった、そこの部分がどこに書いてあるのかという質問でした。それを伺います。","respondent":"榎本新庁舎整備担当部長","answer":"第二庁舎を残すというのは、答申案の本文の中に、たしか書いてあります。考え方を示すに当たって、別途検討しますということで、本文にも書いてあるものです。","id":"exchange-112"},{"speaker":"いながき委員","kind":"質問","question":"どうやって合意形成を図られるのでしょうか。お尋ねします。","respondent":"榎本新庁舎整備担当部長","answer":"説明会というより、その旨、周知したところです。いろいろな形で周知・啓発というか、ご意見をもらう等、いろいろな形を考えていきたいです。","id":"exchange-113"},{"speaker":"いながき委員","kind":"質問","question":"であるならば、１０回前後の会議を、このタイトなスケジュールの中で本当に実施できたのでしょうか。伺います。","respondent":"榎本新庁舎整備担当部長","answer":"それについては、関係部局が調整して集まった形です。その会議は、逆に言うと、資料を出した１２月２８日以前に行った形になりますので、その会議を複数回経た中で、最終的に資料をつくったという形です。","id":"exchange-114"},{"speaker":"いながき委員","kind":"質問","question":"それを教えてください。であるならば、早川先生からはどういったお言葉があったのか、できれば全て一言一句、教えてほしいと求めました。","respondent":"榎本新庁舎整備担当部長","answer":"策定委員会の早川委員長からの説明を伺った際には、２度の選挙戦を踏まえた判断で、よりよい方向を目指していく姿勢に違和感はないということ。","id":"exchange-115"},{"speaker":"いながき委員","kind":"質問","question":"今後、今後、自分たちが出した答申が変更される可能性があることをお伝えすることになるのでしょうかというのをお尋ねしたかと思うのですが。委員長を務めてくださった早川先生が、納得されたというふうに品川区が感じられたのは、どこをもってして納得されたと思われたのか尋ねました。","respondent":"榎本新庁舎整備担当部長","answer":"要は、新庁舎の予定地にどういうものを建てて何を入れるかというのを決めるのが諮問事項であり、その形での答申をまとめたものです。どういう形にするのかという委員会の在り方等も含めて、今後、検討していきたいと思います。","id":"exchange-116"},{"speaker":"いながき委員","kind":"質問","question":"その方たちはどのようにして納得されたと品川区はお考えでしょうか。この２つをお尋ねします。","respondent":"榎本新庁舎整備担当部長","answer":"何かの機会にお会いする関係があれば、私からも説明していきたいと考えています。１０月１７日に、答申と策定に違いがあるということは、認識していると考えています。","id":"exchange-117"},{"speaker":"いながき委員","kind":"確認","question":"私がほかの市の方から聞いた認識とは、品川区はかなり違うのだなということが、今確認できました。以上、伺います。","respondent":"滝澤災害対策担当部長","answer":"３時間は近所の方と救助・消火活動を行い、３日間は公的援助なしで生き延びる備えをすることも必要と言われております。区の共助の好事例等につきましては、今、区ではそのような事例を含めて、共助のための訓練参考資料などを作成して、配布・共有しています。","id":"exchange-118"},{"speaker":"いながき委員","kind":"質問","question":"町会に限らず自主的な訓練を促すような仕組みづくりはされていますかというのもお尋ねしていたのですけれども。この２点を伺います。","respondent":"滝澤災害対策担当部長","answer":"区では、先ほど申し述べた品川区災害対策基本条例の中で、防災区民組織というものを設定しております。その防災区民組織を通じて、その組織と防災部門が一体となり、情報共有をして、防災訓練などについて助言・発信しています。","id":"exchange-119"},{"speaker":"いながき委員","kind":"質問","question":"こちらについていかがでしょうか。伺います。","respondent":"滝澤災害対策担当部長","answer":"１つ目は訓練支援についてですけれども、基本的には町会単位で防災区民組織に対して支援を行っているものです。それから２点目の質問についてですが、区内に２８か所の備蓄倉庫がありまして、区内の区有施設５２か所の中にもそれぞれ倉庫を準備している状況です。","id":"exchange-120"},{"speaker":"いながき委員","kind":"質問","question":"それと、情報発信もしてほしいと思います。見解を伺います。","respondent":"滝澤災害対策担当部長","answer":"品川区では、ゲーム感覚で避難所運営を体験できるコンテンツを導入し、幅広い世代での普及などにも努めております。今回、引き続き、いろいろな手段で防災の自助・共助を普及してまいりたいと考えております。","id":"exchange-121"},{"speaker":"いながき委員","kind":"質問・要望","question":"ぜひとも進めてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-122"},{"speaker":"藤原委員","kind":"質問","question":"それと、南側、西側、そして北側のオープンスペースは、建築上、建設上、きちんと確保されているでしょうか。それと、西大井駅周辺の再開発はどういう状況になっているか尋ねました。","respondent":"中村都市環境部長、有江都市整備推進担当部長","answer":"そして、夏から稼働予定です。これも予定どおりです。 現在、西大井一丁目・二丁目の２つの地区におきまして、まちづくり協議会がそれぞれ設立されております。まちの課題や将来のまちづくりの方向性など、地権者の皆さんでご検討されております。","id":"exchange-123"},{"speaker":"藤原委員","kind":"質問・要望","question":"ですから、あそこは３０キロが上限ですけれども、私は２０キロでもいいと思います。ですから、ゾーン３０も含めて、これから検討していってほしいと求めましたが、いかがか尋ねました。","respondent":"中村都市環境部長、有江都市整備推進担当部長、稲田防災まちづくり部長、山崎文化スポーツ振興部長、伊崎地域振興部長","answer":"そういった利便性が低下しているといったところの懸念もＪＲに伝えながら、引き続き、西口改札の要望について求めてまいりたいと考えております。… いわゆる開かずの踏切ということで認識しておりますけれども、地域としましては非常に複雑な状況であるということを認識しております。… 路側帯はカラー化を行いまして、歩行者が通る部分と車が通る部分を、視覚的に分けて対応している。","id":"exchange-124"},{"speaker":"藤原委員","kind":"質問","question":"それと、マスタープランの改定をしましたが、いつ正式に発表になるのでしょうか。ＪＲのただ１つの駅みたいな形でマスタープランに載っていたのですけれども、どういうふうに変わっていくのか、説明を求めました。","respondent":"中村都市環境部長","answer":"マスタープランの改定につきましては、昨日ホームページで公表したというところで、まだ報告が間に合わなくて申し訳ありません。今後もにぎわい創出の取組、それから防災性の向上といった、まちの動きをさらに進めたいと考えております。","id":"exchange-125"},{"speaker":"藤原委員","kind":"質問・要望","question":"この課１つにこれだけ任せて、組織的には大丈夫でしょうか。大事だと思っているのですけれども、維持していっていただきたいと思うのですが、いかがか尋ねました。","respondent":"今井福祉部長、福内健康推進部長、伊崎地域振興部長","answer":"高齢者地域支援課で進めてまいりますけれども、認知症サポート係には、適切に事業を執行していきたいと考えています。６０歳以上になっても、今後… しながわ出会いの湯ですが、こちらは地域の公衆浴場を利用して、高齢者の方が気軽に参加できるお楽しみプログラムと入浴サービスを実施して。… 事業収入についても、令和４年度は少し復活してきましたが、まだコロナ前には戻り切れていない状況にあります。","id":"exchange-126"},{"speaker":"藤原委員","kind":"質問・要望","question":"その辺についていかがでしょうか。この辺についてどう思いますか。","respondent":"今井福祉部長","answer":"例えば要介護度改善ケア奨励事業や看護師の確保支援、施設、法人の中で給料などというものに反映されてきたという経緯もあります。ご紹介いただきました、区としましても、緊急事態宣言の発出以降も介護サービス業務継続支援金というのを支給させていただいた実績もあります。","id":"exchange-127"},{"speaker":"藤原委員","kind":"質問","question":"そして、法人にとおっしゃいましたけれども、介護士と介護従事者の方に直接渡してほしい。いかがか尋ねました。","respondent":"今井福祉部長","answer":"処遇改善のために、昨年の１０月からベースアップ等、支援加算としてされたところです。７１事業所のうち、今後どのような支援が必要であるかというのは、また法人とお話ししながら進めていく課題だと認識しております。","id":"exchange-128"},{"speaker":"藤原委員","kind":"質問","question":"本当に、事務的なことが大変ですから。これで、本当の評価というのはできるのか尋ねました。","respondent":"久保田企画部長","answer":"新公会計制度基本方針に基づき実施するものでありまして、令和４年度、試行的に実施したです。いわゆる区民参加の方を入れまして政策評価を実施いたしまして、新たな政策の推進に必要な財源確保に努めていきたいと考えております。","id":"exchange-129"},{"speaker":"藤原委員","kind":"質問","question":"外部評価に絡んだらという質問をしようと思ったのですけれども、外部を入れるというお話ですけれども、将来。その辺については、いかがか尋ねました。","respondent":"高山監査委員事務局長","answer":"それから政令指定都市、それから中核市などでは実施が義務づけられておりますが、特別区においては導入は任意といったものです。かなり質の高い監査を実施できていると考えていますので、今後、導入などが検討されていくものと理解しております。","id":"exchange-130"},{"speaker":"藤原委員","kind":"質問","question":"そうしたら、何年後はいずれ、ＡＩ監査というのが出てくるのではないですか。その辺についてはどうですかというのと、退職が目立つということがあると思うのですけれども、この退職の状況を説明するよう求めました。","respondent":"高山監査委員事務局長、堀越総務部長","answer":"監査委員制度につきましては、地方自治法を根拠とするものでございまして、こちらにつきましては、法令の定めに基づきまして、設置は必置です。効率的かつ精度の高い監査を実施していくという意味で、こうした動きを捉えて… 年代別に見ますと、２０代、３０代の職員が多いという状況です。ほかの区、流動性の高まりがありまして、転職のハードルが低くなっているのではないかと見ているところです。","id":"exchange-131"},{"speaker":"藤原委員","kind":"質問・要望","question":"これは、ゆゆしき事態ではないのですか。いかがか尋ねました。","respondent":"堀越総務部長","answer":"面接は採用の段階ではしっかりと対応して、その後のいろいろな自分の人生の設計の中で、そういう判断をされたと見ております。そういうことも図りながら、職員の定着と、それから能力の発揮をしてもらうような環境をしっかりと整備していきたいと考えております。","id":"exchange-132"},{"speaker":"藤原委員","kind":"質問","question":"でも、２０代、３０代で、５０人ぐらい退職してしまうのでしょう。何回も伺ってしまいますけれども、ここはしっかり、将来の品川区を担ってくれる方のために、。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-133"},{"speaker":"せらく委員","kind":"質問","question":"１つ目に、空き家ホットラインは、主に近隣住民からの相談窓口となり、今年度は何件のご相談がありましたでしょうか。２つ目に、無料の空き家専門相談窓口では、特に所有者の相談窓口として、専門家に無料で相談できるということですが、相談内容の内訳を伺います。","respondent":"中村都市環境部長","answer":"そして、管理督促通知を１１９件出しております。それからリフォームをして、また家族で使いたい、それから相続に関する相談といったものもあると聞いております。","id":"exchange-134"},{"speaker":"せらく委員","kind":"質問","question":"ある程度管理されているところに対して、一時的な利用としての登録などをして、少しでも区で管理できることにメリットはありますでしょうか。入院・介護施設に入る等、区内の引っ越しで住民票異動の際にご案内など、取り組んでいることがあれば説明を求めました。","respondent":"中村都市環境部長","answer":"把握していれば、有効活用あるいは、ご指摘のように管理不全の予防としてのメリットはあると考えております。これもアプローチを早期にできれば、非常に予防には役立つと、区としては考えております。","id":"exchange-135"},{"speaker":"せらく委員","kind":"提案","question":"適地があれば駐輪場の整備がされるのだろうと思うのですが、９０％台の利用状況では、まだ整備の検討には至らないのでしょうか。お考えを伺いますとの意見を述べました。","respondent":"稲田防災まちづくり部長","answer":"駐輪場も検討の一つとして考えるところでございまして、駅周辺というところで、適地の確保はなかなか難しい現状があります。今後もそれぞれの駐輪場で、利用状況を見ながら、工夫をしながら、区民の皆様が使いやすい駐輪場運営に引き続き努めてまいりたいと考えております。","id":"exchange-136"},{"speaker":"せらく委員","kind":"確認","question":"民間の駐輪場も同じようにロックがかかるところが多いと思いますが、そちらも連携して満空確認はできそうでしょうか。説明を求めました。","respondent":"稲田防災まちづくり部長","answer":"連携というところでは、積極的に連携の検討を行うなどして、自転車利用者の利便性の向上に努めていきたいと考えております。今後におきましても、利用状況をやはりよく把握しながら、そのラック幅にも対応していきたいと考えております。","id":"exchange-137"},{"speaker":"せらく委員","kind":"確認","question":"開始後１か月で１,０００件の利用があったと確認しました。そして、まだ電子申請の項目に見受けられなかったところで、保育所の入園申請書類についての電子申請の移行の計画を伺います。","respondent":"久保田企画部長","answer":"こちらにつきましては、令和５年３月７日から、国のぴったりサービスで受付を開始しているところであります。これらにつきましても、品川区電子申請サービスにおいても、近日中にこれとのリンクを登録する予定であります。","id":"exchange-138"},{"speaker":"せらく委員","kind":"質問・要望","question":"利用者側の最初の面談はファミリーサポートセンターで行うということですが、これを、Ｚｏｏｍなどを使ったオンライン面談にするはいかがでしょうか。ご見解を伺います。","respondent":"柏原子ども未来部長","answer":"対応可能な提供会員をご紹介するといったところもありますので、なかなかそこの課題をクリアしなくてはいけないというところを認識しています。改定予定で今考えてありますので、ご提案いただいた内容も含めて、検討してまいりたいと思ってあります。","id":"exchange-139"},{"speaker":"せらく委員","kind":"質問・要望","question":"提供会員はあらかじめスケジュール登録などをしているのでしょうか。伺います。","respondent":"柏原子ども未来部長","answer":"その後、電話等で対応可能な提供会員に連絡を取っているということで、個別の調整マッチングをしているといったところです。スケジュールの登録ですけれども、例年１月に提供会員向けのアンケートを実施しています。","id":"exchange-140"},{"speaker":"せらく委員","kind":"質問","question":"これまで学校と保護者間の連絡方法について度々質問をさせていただきましたが、連絡のオンライン化はできますでしょうか。伺います。","respondent":"米田教育次長","answer":"今後の改修の中において、より安全に情報発信をすることができるようになるため、積極的に学校からのお知らせなどのデジタル化を推進してまいります。情報伝達の確実性や安全性も図りながら、オンラインの活用をさらに進め、保護者や教職員の負担軽減に努めたいと考えております。","id":"exchange-141"},{"speaker":"せらく委員","kind":"質問・要望","question":"単純な事務作業において、業務量の軽減・効率化になると思いますが、お考えを伺います。そういった点、生徒と先生の間で認識の確認などはしていらっしゃいますか。","respondent":"米田教育次長","answer":"情報教育の中において、メリット、デメリットもしっかり学びながら取り上げていく必要があると認識しております。その信頼性や必要性を自ら考えることの大切さを学んでおり、正しい知識と活用、思考することの大切さなどを醸成する指導の工夫を図ってまいります。","id":"exchange-142"},{"speaker":"せらく委員","kind":"質問","question":"次に、区職員の働き方について質問いたします。コロナ禍でテレワークを取り入れているということですが、来年度の体制について、テレワークのできる環境づくりの現状と今後の展望を伺います。","respondent":"堀越総務部長","answer":"テレワークに適する業務について、希望する職員が支障なくテレワークを実施できるよう、積極的に取組を進めていくという考えであります。様々準備や対応を行っているところでありますが、それと並行いたしまして、一定のルール整備について今検討を進めているところです。","id":"exchange-143"},{"speaker":"せらく委員","kind":"質問","question":"段階的に窓口もオンラインにして、利用者も職員も自宅で対応できるような環境をつくっていくべきだと考えますが、計画など、区の見解を伺います。伺います。","respondent":"久保田企画部長","answer":"オンライン化については、令和７年度末までに品川区の全ての手続をオンライン化していくという予定で進めているところです。情報推進課が中心となって活用支援を実施しておりまして、職員を育成しながら、内製化を進めてまいります。","id":"exchange-144"},{"speaker":"せらく委員","kind":"質問・要望","question":"時には厳しい要望やクレームもあるかと思いますが、そうした状況においても、専門的かつ丁寧な対応をしていただけて非常に心強いです。こういった声の共有はしていらっしゃるのか尋ねました。","respondent":"堀越総務部長","answer":"広報広聴課で受理した区民の声には、区政に対するご意見、それから職員対応への苦言のほかに、職員への感謝のお言葉も頂いてあります。感謝の声も含めまして全て、区長まで内容を見た上で、所管に送付して対応しています。","id":"exchange-145"},{"speaker":"せらく委員","kind":"提案","question":"提案としては１つ、窓口の職員へありがとうなど、ホームページ上に「ありがとう」メーターのような形で載せてもいいかもしれません。最後にお考えを伺いますとの意見を述べました。","respondent":"堀越総務部長","answer":"引き続き、職員が前向きに仕事に取り組めるよう、共有を図ってまいりたいと思っています。まずはそのことを踏まえながら、また職員が前向きに仕事に取り組むよう、どのようなことが可能か検討させていただきたいと考えています。","id":"exchange-146"},{"speaker":"せらく委員","kind":"質問・要望","question":"区民の相談を受けた議員からの要望に対応していただくといったケースも十分あると思いますので、議員側も積極的に伝えたいと考えています。以上で質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-147"},{"speaker":"渡辺委員","kind":"質問・要望","question":"私たちの委員会質疑、予算化されたこと、さらなる拡充への要望など、熱意あるやり取りがありました。区民の生命を守り、区民の幸せを強く意識した行政と議会の連携をお約束し、品川区議会自民党の意見表明とします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-148"},{"speaker":"若林委員","kind":"質問・要望","question":"公明党は来年度予算編成の過程において、前区長ならびに新区長にそれぞれ予算要望を行いました。本委員会での会派からの意見・要望を真摯に受け止められ、今後の区政へ活かされるよう要望し、意見表明といたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-149"},{"speaker":"のだて委員","kind":"質問・要望","question":"潤沢な予算があるのですから、所得制限は撤廃し、港区並みの１３万７,０００円まで拡充することを求めます。区民への説明責任を果たせないリニア新幹線は、国に中止を求めるべきです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-150"},{"speaker":"大倉委員","kind":"提案","question":"オリンピック・パラリンピックのレガシー活用、多様性の推進など、各課題への積極的な取組も求めます。今回の予算特別委員会において、我が会派の所属議員が質問の中で指摘・提案した各項目を真摯に受け止め、予算を執行することを強く要望いたしましてとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-151"},{"speaker":"吉田委員","kind":"提案","question":"生活者ネットワークは、今からでも両計画の中止を国に対して求めるべきと主張いたします。その他、ここまで生活者ネットワークが指摘・提案させていただいた意見を予算執行に活かしていただくことを要望し、意見表明といたしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-152"},{"speaker":"須貝委員","kind":"質問・要望","question":"世界は、国を守るウクライナを見捨てずに、世界平和をぶち壊すプーチン政権を倒すべきです。以上で、品川改革連合の意見表明を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-153"},{"speaker":"松本委員","kind":"提案","question":"区民からの要望も多かった給食費の無償化、第２子保育料無償化、子育て政策が予算案に反映された点は高く評価いたします。予算の執行や今後の施策に反映していただくよう要望するとともに、改善を徹底していただき、区民サービスの向上が図られることを求めとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-154"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/756395?Template=document&Id=1176#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":136652,"voices":343}},{"id":"r05-20230327-10","meetingId":"r05-cm03","date":"2023年3月27日","dateIso":"2023-03-27","committee":"議会運営委員会","time":"午前１０時３０分～午前１１時１３分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を8件整理しています。","topics":[{"id":"topic-01","title":"令和５年第１回定例会","agenda":"令和５年第１回定例会","exchanges":[{"speaker":"石田委員","kind":"質問","question":"区長に伺いますけれども、こうした品川区の教育改革を根本から変えなくてはいけないという認識はあるでしょうか。そして、今回の人事が、こうした役割を期待しての人事なのか、伺いたいと思います。","respondent":"森澤区長","answer":"先ほど申し上げましたとおり、学校、そして児童・生徒を取り巻く環境というのは、本当に多様化していて、複雑化しています。地域分野での経験を活かして、新たな課題にも積極的に取り組んでいただきたい、そのように考えております。","id":"exchange-001"},{"speaker":"若林副委員長","kind":"質問・要望","question":"副委員長というよりも、会派の代表として、質問というか、意見というか、要望という形です。理解できるようなご説明、いわゆる丁寧な説明をしていただきたいという要望を伝えします。","respondent":"森澤区長","answer":"承知いたしました。","id":"exchange-002"}]},{"id":"topic-02","title":"議事日程(5)および追加議事日程","agenda":"議事日程(5)および追加議事日程","exchanges":[{"speaker":"石田委員","kind":"提案","question":"今回の人事の提案についても、抜本的転換が必要なこれまでの教育行政を続けるものです。行政との独立性を保たれるべきですが、教育委員会を主催し代表するという２つの役割を併せ持つ、文字どおりのワントップとして位置づけられましたとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-003"}]},{"id":"topic-03","title":"議長会等の報告","agenda":"議長会等の報告","exchanges":[{"speaker":"大倉委員","kind":"質問・要望","question":"くにば議員の欠席の件ですが、現在も治療中ということで確認を取っておりまして、通院しながら体調回復に努めているということでありますので、皆様にご報告をさせてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"小芝委員","kind":"質問・要望","question":"意見表明の趣旨に沿った意見を表明されてしかるべきではないのかといった意見が出ましたので、報告といいますか、お話しします。その辺を、是正も含めて検討していただきたいです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"田中委員","kind":"質問","question":"４月２６日の幹事長会は、現職が行かれます。これは、落選した人が次の議会のことを話し合うということにとても違和感があるというか、それは別か尋ねました。","respondent":"渡辺委員長","answer":"取りあえずご発言を頂いて、問題提起をされて、それぞれでご理解くださいということにとどめします。取り上げる、取り上げないも含めて検討いただくという考え方で、今日は収められればと思います。","id":"exchange-006"},{"speaker":"安藤副委員長","kind":"意見","question":"特に制限する方向で動くべきではないと考えていますので、私たちとしましては、特に意見表明の時間に制限を設けることは必要ないと思っています。これは意見ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-007"},{"speaker":"あくつ委員","kind":"意見","question":"なぜ、今、安藤副委員長は時間の制約はすべきではないとおっしゃるのか。いろいろなご趣旨、お考えがあるので、各会派の良識にお任せしたいなというのが感想ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-008"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/881920?Template=document&Id=5502#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":14594,"voices":70}},{"id":"r05-20230526-6","meetingId":"r05-cm05","date":"2023年5月26日","dateIso":"2023-05-26","committee":"区民委員会","time":"午後 ２時５０分～午後 ３時４７分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を21件整理しています。","topics":[{"id":"topic-01","title":"第３１号議案、令和５年度品川区一般会計補正予算（歳出 区民委員会所管分）","agenda":"第３１号議案、令和５年度品川区一般会計補正予算（歳出 区民委員会所管分）","exchanges":[{"speaker":"山本委員","kind":"質問・要望","question":"１つ目、防災対策等の観点からも、町会・自治会活動を通じた地域コミュニティの活性化は必要だと考えております。質問ですけれども、今回、申請回数を２回から３回に増やしたという背景について教えていただきたいと考えています。","respondent":"宮澤地域活動課長","answer":"令和４年度、２回申請した町会・自治会というものが９件ありました。いろいろな事業を、そういった意欲のある町会・自治会での活動というものを後押しするために、３回とするものです。","id":"exchange-001"},{"speaker":"えのした委員","kind":"意見","question":"やはり子どもたちの経験の場が大分失われているので、体験の場ですとか、大変よい事業だなと思うのですけれども。ちなみに、例えば参加を促すような事業というものは、何か具体例はありますかとの意見を述べました。","respondent":"宮澤地域活動課長","answer":"ボウリング大会だとか、そういったところで様々町会・自治会が工夫して、子ども向けの事業というものを実施しているという部分です。","id":"exchange-002"},{"speaker":"えのした委員","kind":"意見","question":"ボッチャやボウリングなどというものも、子どもたちは大変楽しめる、もちろん町会・自治会の方がいらっしゃるので、高齢者が一緒に楽しめるのではないかなと思いますが、（２）に新たに立ち上げた事業とあるのですけれども、その中で本当に新しいなというものはありますかとの意見を述べました。","respondent":"宮澤地域活動課長","answer":"行っている事業の傾向として、町会・自治会との親睦を深めるというところで、レクリエーションのバスツアー等をやっているところがあります。その中で工夫している事例としては、防災をテーマに防災施設へ行くというような取組をしている町会・自治会もあります。","id":"exchange-003"},{"speaker":"横山委員","kind":"確認","question":"先行、区内だけではなく、そういった部分をどのようにこちらの支援と一緒に伝えていくのかというようなところを確認できたらと思いました。もう一度確認できたらと思うのですが、告知などもしていくのかなと思うのですけれども、どのように伝えていくのかというようなところ。","respondent":"宮澤地域活動課長","answer":"あわせて、品川区町会・自治会連合会ホームページでお知らせもしていく予定です。その中で全ての町会・自治会に、１つずつ丁寧に説明していきたいと考えております。","id":"exchange-004"},{"speaker":"横山委員","kind":"質問・要望","question":"まず教えていただきたいということと、その辺り、今どのように活用されているのかというところも教えていただきたいと思いました。そちらまでお願いします。","respondent":"宮澤地域活動課長","answer":"そのために、先ほど申しましたとおり、全ての町会・自治会に丁寧に説明していくというところが大事だと思っています。町会・自治会のお話を聞くと、町会・自治会の高齢化や担い手不足というところにつきましては、課題として認識しております。","id":"exchange-005"},{"speaker":"横山委員","kind":"質問","question":"次に、省エネルギー対策設備更新助成金のほうなのですけれども、こちらの説明チラシの配布方法について教えていただけたらと思いました。個人事業主の方にも、ぜひ伝わるような形でお願いしたいなというような思いがあっての質問なのですけれども、お願いします。","respondent":"小林商業・ものづくり課長","answer":"申請方法をまとめました説明チラシを作りまして、１つは、または区の施設です。そういったメディアのほか、紙のチラシでも事業者の方にお伝えするような、そのような機会をつくってまいりたいと考えています。","id":"exchange-006"},{"speaker":"横山委員","kind":"確認","question":"は確認になるのですけれども、上限８０万円に至らないケースの場合は、こちらは別に件数を制限するものではないという理解でよろしかったでしょうか。１０万円以上の設備というところなのですけれども、根拠だけ確認をさせていただけたらと考えています。","respondent":"小林商業・ものづくり課長","answer":"もし金額がそれより少ない助成の申請ということでありましたら、予算の範囲内ではそれを超えるような対応というものもある程度考えております。こちらは品川区のこのような産業支援の助成金におきまして、基本的に設備更新などにあたりまして１０万円を１つの基準としています。","id":"exchange-007"},{"speaker":"横山委員","kind":"確認","question":"ガソリン代であったり、そうしたものを抑えることができるような１０万円以上の設備というような形で、基本的に考えればよろしいのでしょうか。ちょっとその辺り、確認をお願いします。","respondent":"小林商業・ものづくり課長","answer":"実際に今後チラシなり、なるべく事業者の方にこのようなものが該当するのだなということが分かりやすいように進めてまいりたいと考えております。","id":"exchange-008"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"新規事業定着化補助金のほうも、今まであった事業ということで、実績が分かれば教えていただきたいということ。この４月からもう申請されている件数がどれくらいあるのか伺いたいということと、これはこの令和６年３月３１日までで、伺いたいと思います。","respondent":"宮澤地域活動課長","answer":"この４月を過ぎてから、児童参加地域事業補助金につきましては６件、新規事業定着化補助金については１件という状況です。それと事業の実施期間は令和６年３月３１日までとしておりまして、今回の拡充部分については時限的措置として、今年度についてという状況です。","id":"exchange-009"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"専門家からも第９波の可能性も指摘されていますし、ＷＨＯでは、同時に警戒は怠らないようにということが呼びかけられていると思うのです。ですから、区としてもそこは呼びかけていただきたいなと思うのですが、いかがか尋ねました。","respondent":"宮澤地域活動課長","answer":"事業実施に関しましては、模擬店などが出て飲食を伴うものもあれば、いわゆるレクリエーションをするようなタイプというものも様々あります。町会・自治会への補助金の支援の中にも、そういったものを活用していただきながら、円滑に事業を行っていただきたいです。","id":"exchange-010"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"ポストコロナとはいえ、５類になったとはいえ、まだまだ心配な部分もあるので、そうした対応もしながら進めていくというところで理解しました。１品のみではなくて、何品買っても上限８０万円で５分の４の助成だということでいいのかという確認と、数が分かれば教えてほしいと求めました。","respondent":"小林商業・ものづくり課長","answer":"一括申請をしていただければ、８０万円の上限というのはあるのですが、それについては助成金の対象になるように審査をしてまいります。","id":"exchange-011"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"そうすると、もし２００件を超えるようなことがあった場合に、さらに上乗せということができるのかどうかということ。ガス代の高騰に対応する区独自の支援策を進めるべきだということを一般質問等でも求め続けてきているところですけれども、今回これが融資等ではなく。","respondent":"小林商業・ものづくり課長","answer":"我々のほうで令和４年度に実施しました、新型コロナウイルス等対応助成というところで補正予算を組んだものがあります。これまで融資あっ旋というところを中心に説明してきたのではないかという、ガス代、これは日本銀行の統計で企業の物価統計というものがありますが。","id":"exchange-012"},{"speaker":"藤原委員","kind":"確認","question":"町会・自治会の予算が足りないからどうにかしてくれないかという声もあって、まず１つ確認として、それでいいのか尋ねました。","respondent":"宮澤地域活動課長","answer":"委員のご指摘のありましたとおり、ポストコロナに移行しまして、活動再開というこのタイミングで支援をするです。","id":"exchange-013"},{"speaker":"藤原委員","kind":"質問・要望","question":"でもこの制度が、見たときに難しいとか、申請する手間がかかるのではないかと思ってしまうと、しないところもあるかもしれないではないですか。今回この補正予算に反対しているという意味ではなくて、その辺についてはいかがか尋ねました。","respondent":"宮澤地域活動課長","answer":"町会・自治会が行う活動というものは非常に様々と認識しております。それとは別に、今回事業にターゲットを絞って拡充するというところで、両面使って様々支援していきたいという状況です。","id":"exchange-014"},{"speaker":"藤原委員","kind":"質問","question":"何かこう大きいイベントなどをするといっても、今、最大限で助成する金額は大体１０万円ぐらいではないですか。その辺についてもう１回答弁していただけますか。","respondent":"宮澤地域活動課長","answer":"そういった助成金を活用して、様々な町会・自治会活動に、現状つなげていただいているです。それと併せまして、それぞれの目的に応じた各種補助金の支援メニューというものも用意して、両面で引き続き支援していきたいと思っているところです。","id":"exchange-015"},{"speaker":"藤原委員","kind":"質問","question":"次に、省エネルギー対策設備更新助成金だからしようがないのだと思うのですけれども、あえて伺います。でも、介護のことをしている施設などは、介護事業者に対しての助成というものも新たにという話も出ているぐらいではないか尋ねました。","respondent":"小林商業・ものづくり課長","answer":"その費用の部分が苦しいというところで、我々のほうもどのような支援がいいのかということで、ご指摘のようなところも含めて検討いたしました。ただ、これは永久にといいますか、長期間にわたってずっと支援するということはちょっと難しいのであろうと。","id":"exchange-016"},{"speaker":"あくつ委員","kind":"質問","question":"残りの５億円の使途という中で、１億７,０００万円ということですから、かなり大きい金額をここに投入されているのです。先ほどなぜ２００件にしたのかというところで、その辺り、どうしてこのような形になったのかというところをもう少し詳しく説明を求めました。","respondent":"宮澤地域活動課長、小林商業・ものづくり課長","answer":"新規事業定着化補助金の６年目以降の考え方ということです。それを立ち上げて定着できるように、町会・自治会の、その立ち上げから５年目までというところを補助させていただいているです。ただ、そこまで具体的に書いているものではございませんけれども、中小企業支援に使っても大丈夫ですよということは書いてあったところです。","id":"exchange-017"},{"speaker":"あくつ委員","kind":"質問","question":"後段の部分につきましては、そのような都道府県レベルであるというところと、２３区でも額は小さいけれども同種のものがあると。なるほどなというところ、しかも個人事業主まで、業種含めて広いというところでいいアイデアだなと思ったので質問させていただきました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"せらく委員","kind":"質問","question":"それを踏まえてお伺いしたいことがあるのですけれども、やはり地域の拠点となる場所も必要になってくるのではないかなと考えているところです。町会・自治会の拠点となる会館がまだまだ整備されていないという現状を伺ったところでしたので、もしございましたらお聞かせほしいと求めました。","respondent":"宮澤地域活動課長","answer":"補助金のメニューというものを用意していますので、そういったものも相談を受けながら、さらに補助金という形での支援というものをしています。会館というところに限らずに、活動の拠点となる部分を賃貸借する場合の補助というものも用意しています。","id":"exchange-019"},{"speaker":"山本委員","kind":"質問・要望","question":"要望として先ほどちょっと申しそびれてしまったので、２０１ある町会や自治会、仕組みづくりをご検討いただきたいというところでございました。２回から３回に増やしたというところで、まだやっていないところにもぜひご活用いただきたいというところでございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"第９波など新たな感染拡大が起きた際には、感染拡大防止の対策を迅速に行っていくことを区からもお伝えいただきたいですし、要望したいと思います。私たちも常々求めてきた直接支援、さらなる直接支援を区としてやっていただきたいなということも要望して、賛成します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/753456?Template=document&Id=2956#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":18460,"voices":68}},{"id":"r05-20230526-7","meetingId":"r05-cm05","date":"2023年5月26日","dateIso":"2023-05-26","committee":"厚生委員会","time":"午後 ２時５５分～午後 ４時４０分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を29件整理しています。","topics":[{"id":"topic-01","title":"第３１号議案、令和５年度品川区一般会計補正予算（歳出 厚生委員会所管分）","agenda":"第３１号議案、令和５年度品川区一般会計補正予算（歳出 厚生委員会所管分）","exchanges":[{"speaker":"鈴木委員","kind":"提案","question":"交付限度額の確認通知は６月下旬を予定していますと書かれているのですが、これとはまた、出されるということになったのか。今回の品川区が出されたということの関係を教えていただきたいのと、提案をされた、その理由も併せてお伺いをさせてほしいと求めました。","respondent":"豊嶋生活福祉課長（生活支援臨時給付金担当課長兼務）","answer":"これで今、準備を進めているところです。そして４月１２日と、３本にわたって事務連絡等々が出ている中、区としてこのタイミングで議会に上程するということを決定いたしました。","id":"exchange-001"},{"speaker":"鈴木委員","kind":"質問","question":"その計画に基づいて調査を５月頃に実施、それで限度額の通知が６月下旬と書かれていたので、柔軟にそのように品川区にこれだけ地方創生臨時交付金が来ますという限度額が示されたということなのか尋ねました。","respondent":"豊嶋生活福祉課長（生活支援臨時給付金担当課長兼務）","answer":"５月２９日という日付がありますので、それは我々でも認識して、準備を進めているです。既に示されておりますので、その中でそれを使いながら、もちろん一般財源も使いながら進めていくです。","id":"exchange-002"},{"speaker":"鈴木委員","kind":"確認","question":"令和５年度も３回にわたって臨時交付金を出す方向ということで書かれているのですけれども、この後１０月と、その点も確認させてください。それなのに発熱外来とかはいまだに続けていると伺っているのですが、そこのところは検討されなかったのか、そこの点についても伺いたいと思います。","respondent":"豊嶋生活福祉課長（生活支援臨時給付金担当課長兼務）、若生健康課長","answer":"計画を３回に分けて提出するということは書かれているのですけれども、給付金が３回とは我々は認識しておりません。通知については以上です。限りある財源の中でどのような形で支援策を講じていくかというところは、区としても総合的に検討した結果、今回のようなものになったです。","id":"exchange-003"},{"speaker":"鈴木委員","kind":"質問・要望","question":"推奨事業メニューの中にも書かれていることですので、ぜひ支援のほうはご検討いただきたいということで、要望させてほしいと求めました。これを対象に加えた理由というのは、どういうことで対象としたのか、その理由についても伺いたいと思います。","respondent":"豊嶋生活福祉課長（生活支援臨時給付金担当課長兼務）","answer":"苦しんでいる人がいるであろうというところから、対象を少しでも拡大したいというところで、区のほうで均等割まで拡大をしようということを決定したです。","id":"exchange-004"},{"speaker":"鈴木委員","kind":"質問・要望","question":"周知をどうしていくのかというのはかなり議論になって、どう周知をしていくかというところでは具体策があるのか、その点も伺いたいと思います。その点も確認させていただきたいのですけれども、家計急変世帯としてこの制度を使えます、その点についても伺いたいと思います。","respondent":"豊嶋生活福祉課長（生活支援臨時給付金担当課長兼務）","answer":"考え方も同じ考え方を扱って、令和５年の１月から８月の月で見ていくということにはなりますが、対象になる方には支給をするというものです。ありとあらゆるところで網を張って、知らなかったということが起きないように、我々の中でも誠心誠意対応していきたいと考えています。","id":"exchange-005"},{"speaker":"鈴木委員","kind":"質問","question":"こういう給付金という制度があるので対象者にはぜひ知らせてほしいというところは、今まで２回、その点についても伺いたいと思います。４,１００世帯ということなのですが、どういう世帯ぐらいまでが対象になるのかというところで、そこら辺のところをご説明いただけたらと思います。","respondent":"豊嶋生活福祉課長（生活支援臨時給付金担当課長兼務）","answer":"非課税の方と均等割の方でどれくらい違うかという目安だけはありますので、今この場で口頭で大変申し訳ございませんが、お伝えできればと思います。３人世帯になりますと、非課税ですと２０５万円程度のものが、均等割になりますと２２１万円程度まで広がるという形です。","id":"exchange-006"},{"speaker":"鈴木委員","kind":"質問","question":"続けてやってしまっていいですか。では、皆さん質問したいと思いますので、一旦、取りあえず終わりにします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"こんの委員","kind":"質問・要望","question":"何点か確認をまずさせてほしいと求めました。それは総務だったり、いわゆる６月の値上げということも踏まえての算出をされているのか、その辺をまず伺いたいと思います。","respondent":"松山障害者支援課長、菅野高齢者福祉課長","answer":"訪問・相談系サービスについては事業者に事前のアンケートを行いまして、それが１施設当たり７万円から８万円程度だったという根拠が出ました。６月からの値上げを含めてのものなのかということなのですが、値上げ分ですとか… 私からも同様なご質問についてお答えするところなのですけれども、障害者支援課長がお答えしたとおりの形で、同様だということでお話をします。","id":"exchange-008"},{"speaker":"こんの委員","kind":"質問・要望","question":"３月２８日、私ども会派としても、区長に緊急要望させていただきました。２番の(2)の下にある米印、これはどういう世帯をいうのか、ご説明をお願いしたいと思います。","respondent":"豊嶋生活福祉課長（生活支援臨時給付金担当課長兼務）","answer":"そういった意味の文言でございまして、大変分かりにくい表現で申し訳ありませんでした。そういった意味です。","id":"exchange-009"},{"speaker":"こんの委員","kind":"確認","question":"申請をされてからの支給までの流れについて確認というか、前回、それを印字して通知をしてくださる。コールセンター、前回は何人体制で、何時から何時までそれを受け付けてという体制を取っていたのか、その辺も伺いたいと思います。","respondent":"豊嶋生活福祉課長（生活支援臨時給付金担当課長兼務）","answer":"コールセンターですが、今、最終的な詰めを行っている状態ではありますが、６名から１０名程度のコールセンターで進めていければと考えています。今、最後の詳細を詰めている段階です。","id":"exchange-010"},{"speaker":"こんの委員","kind":"質問・要望","question":"ノウハウが積み上がっているもので、その支給体制というのは、なるべく早くの体制というのは取れないものなのでしょうか。その辺のところを伺いたいと思います。","respondent":"豊嶋生活福祉課長（生活支援臨時給付金担当課長兼務）","answer":"６月の上旬から中旬にかけてというところで、やはりどうしても通知を出せるのが、７月の早くても中旬前後という形になってしまいます。ある程度時間がかかって、改修した後の検証期間も当然必要になってまいりますので、ある程度の日数が必要とご理解をいただければと思います。","id":"exchange-011"},{"speaker":"こんの委員","kind":"質問・要望","question":"その辺の流れをまず確認をさせていただきたいのと、こちらは多胎児妊娠の場合は、超音波の検査はどのようになるのでしょうかというところです。この検査については多胎児妊娠の場合はどうなのでしょうかというところを、この２つ、お願いします。","respondent":"若生健康課長","answer":"そこの中で実施のほうは先にというか、４月以降、早急に３月中に意思決定と周知をさせていただいたという流れです。１回の妊娠に対して受診券を交付するということで、多胎か単胎か関わらず、超音波検査については４回というようなことでしています。","id":"exchange-012"},{"speaker":"こんの委員","kind":"確認","question":"国でも、厚生労働省から出ている指針は４回と出ておりますので、多胎児妊娠の方への流れも考えていくということでよろしいでしょうか。答えにくいかもしれないですけれども。","respondent":"若生健康課長","answer":"妊娠期を通して４回というところはあるものの、妊婦健康診査に関しての医療機関等へのアンケートですとか調査というところもいろいろ検討されていた中で、区でもそこはそれを踏まえて検討を進めていく必要があると認識しております。","id":"exchange-013"},{"speaker":"こんの委員","kind":"質問・要望","question":"ありがとうございました。多胎児のところは、ぜひ動きを注視していただきながら進めてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"筒井委員","kind":"確認","question":"基本的な確認なのですけれども、１０分１０ということなのですけれども、何で一旦都を挟んで区に行くという。〔「所管外ではないか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"筒井委員","kind":"質問","question":"款はどこの所管になるのですか。〔「総務」と呼ぶ者あり〕。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"筒井委員","kind":"確認","question":"では、総務に確認をします。家計急変世帯が５００世帯を見込んでいるのですけれども、これ、その場合の対応というのはどのようにお考えなのか尋ねました。","respondent":"豊嶋生活福祉課長（生活支援臨時給付金担当課長兼務）","answer":"家計急変の考え方は、あくまで収入が急変した世帯という考え方ですので、値上がり等々の対応ということでは、この考え方はないということをご理解いただければと思います。","id":"exchange-017"},{"speaker":"筒井委員","kind":"意見","question":"その意味というか重要性、そもそも超音波検査をやる意味と、回数を増やすと効果が上がってくるという。どういった理由でこの回数を増やすのかというところをお教えほしいと求めました。","respondent":"若生健康課長","answer":"不安等も含めて把握して取り除いていくというようなところを対応していくというところが意義があると考えておりまして、この回数というところは必ずしも４回なのかどうかというところは、４回と示されてあります。","id":"exchange-018"},{"speaker":"筒井委員","kind":"質問","question":"そうすると、望ましい基準として、一つ、国の基準を参考として、４回という数字が出てきたということでよろしいのか尋ねました。","respondent":"若生健康課長","answer":"こちら、４回というところの根拠としては、国の基準に基づいて設定されていると認識しております。","id":"exchange-019"},{"speaker":"ひがし委員","kind":"確認","question":"ここのところの算出の金額というのは、あとは、どのぐらいの期間の補助ができているのかというのを確認したいのがまず１点。もう１点が、施設に恐らくこの金額は行くと思っていて、支援金の使途の制限などは何かあるのかというのをお聞きしたいです。","respondent":"菅野高齢者福祉課長、松山障害者支援課長","answer":"消費者物価指数というものを基に、そこは世間一般の上昇率にある程度は準拠しているというか、応じて算出しているのかと認識しているところです。… 高齢分野の考え方というのは、期間についても１年間ですし、詳細な算出根拠は同じ１.２３４％を乗じたものです。かなり精度を上げて… 障害者支援課長が言ったとおり、交付金ですので、限定をしていないというのが実情です。","id":"exchange-020"},{"speaker":"ひがし委員","kind":"質問","question":"施設によって不足しているところが出ているというのがあったのですけれども、逆に足りているというところもあったのか。足りていないところに対する今後の対策とかはどのように考えているのかというのをお聞きしたいです。","respondent":"松山障害者支援課長、菅野高齢者福祉課長","answer":"職員の健康・安全を配慮しつつエコ活動には取り組んでいただいておりますけれども、事業者のお声を聞いていかなければならないと考えております。今回支給させていただいて、その後また事業者から… 令和４年度の光熱水費と、通所施設については、そうでもなかったという結果が出ております。","id":"exchange-021"},{"speaker":"やなぎさわ委員","kind":"質問","question":"先ほどお話のあったように、令和４年度の支援金、非常に助かりました。令和４年度のことを含めてのご質問なのですが、どういったスキームといいますか、支払いをするのかということをお伺いしたいのですけれども。","respondent":"菅野高齢者福祉課長、松山障害者支援課長","answer":"締切りを決めさせていただいて、お申込みをいただき、その後支出の手続をするという流れになっております。１回目１月３０日、２回目３回目ということで、追加で支給をさせていただいたという経緯があります。東京都のスキームがまだ情報として得られておりませんので、東京都の情報が得られましたら、追加でまた情報を流するということになっております。","id":"exchange-022"},{"speaker":"やなぎさわ委員","kind":"質問","question":"これ、申請しないで、区のほうから、こういう感じで支払いますということで頂くということはできないのでしょうか。やはり現場の業務は煩雑というか、申請業務とかが大変だと思うので、そういうことは難しそうか尋ねました。","respondent":"菅野高齢者福祉課長、松山障害者支援課長","answer":"前回の１２月補正のときの支援金につきましては、９割弱のところが申請をしていただいておりますので、おおむね普及されていると思います。どういった経緯があったかというのはそこまでは追及していないのですけれども… ３回に分けてというのは、あるいは法人や事業所によって考え方等々がありますので、こちらのほうは申請を促すという形になっております。今回もこのスキームでやらせていただきたいと思っています。","id":"exchange-023"},{"speaker":"やなぎさわ委員","kind":"質問","question":"プラスアルファで２つぐらいあると、質問は以上なのですけれども、そういった何か支援策を考えていただけたらと。物価高騰に追いついていないので、ぜひそういったところも前向きに検討していただけたらと思いまして、私の質問を終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"おぎの委員","kind":"質問","question":"超音波の件数３,８３８件と、2)番3)番３,６１８件というのは、この件数の違いというのは何かあるのか尋ねました。","respondent":"若生健康課長","answer":"委託料というところがそもそも発生せず、区から直接ご本人の口座に払うというようなことになっていますので、この２２０件という差が出てきているところです。","id":"exchange-025"},{"speaker":"鈴木委員","kind":"質問・要望","question":"これは私もずっと議会の中で拡大をということで求めてきたので、そういうところでは、２３区のいつも統一でされているところでは話合いがされたのか。少なくとも４回はやるべきでしょうということでこの間も求めてきましたけれども、でも、教えてほしいと求めました。","respondent":"若生健康課長","answer":"その区の状況によってというところで実施していたところなのですけれども、そういったところの支援として、区としても実施を決めたという状況です。","id":"exchange-026"},{"speaker":"鈴木委員","kind":"質問・要望","question":"そういうところはなぜ交付金ではないのかということを伺いたいのですけれども、ネットで見たら、幾つもの自治体がやっているところがあったのです。一般財源を充ててでもぜひやっていただきたい問題ではないかと思うのですが、その点について伺いたいと思います。","respondent":"豊嶋生活福祉課長（生活支援臨時給付金担当課長兼務）","answer":"ひとまず国が考える対象までがもちろんそういったお金が手当てされるのでしょうけれども、ひとまず一般財源を充てて、まずは支給をしましょうです。","id":"exchange-027"},{"speaker":"鈴木委員","kind":"質問・要望","question":"エアコンについては、毎年毎年本当にこれは問題になるところでして、特に今年もすごく暑い夏がこれからやってくることになってくると思うので、ぜひエアコンがないために、命に関わるようなことがないための、そういう対応というのはしていただきたいということで、要望させてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"先ほどの私の質問の少しだけ補足なのですけれども、電話という順番になると思うのですけれども、通知したというのが証拠として残ります。というか、もしできれば、ペーパーレス化も進めてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-029"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/651938?Template=document&Id=3658#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":30365,"voices":97}},{"id":"r05-20230526-8","meetingId":"r05-cm05","date":"2023年5月26日","dateIso":"2023-05-26","committee":"建設委員会","time":"午後 ２時５１分～午後 ３時５０分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を15件整理しています。","topics":[{"id":"topic-01","title":"第３１号議案、令和５年度品川区一般会計補正予算（歳出 建設委員会所管分）","agenda":"第３１号議案、令和５年度品川区一般会計補正予算（歳出 建設委員会所管分）","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"既に買ってしまった方は、何かそこへの手だてというのをぜひお願いしたいと思いますが、いかがでしょうか。それは、すぐに区民の方が見て分かるものなのかどうか、どういうものが必要なのかというのを伺いたいと思います。","respondent":"工藤交通安全担当課長","answer":"４月１日からヘルメットの着用努力義務化になりましたので、着用すべく、安全運転に努めていただくということで広報を実施してまいりました。２９日、運用開始がまだではありますけれども、こういった準備をしておりますということは早めに区民の方々にお知らせしたいと思います。","id":"exchange-001"},{"speaker":"のだて委員","kind":"質問・要望","question":"希望する人が、あまり手間がかからずに、きちんと申請できるような仕組みにしてほしいと思うのですが、いかがでしょうか。他区ではお店の窓口で、そういったこともできなかったのかなと思うのですが、今回こうした仕組みにした理由を伺いたいと思います。","respondent":"工藤交通安全担当課長","answer":"一例を挙げますと、添付してもらおうかということも検討はしたのですが、それを担保に助成金の交付をさせていただきたいと考えているところです。その辺はご理解というか、ではどうしようかということで、今回の区内共通商品券を交付するという仕組みになった経緯があります。","id":"exchange-002"},{"speaker":"のだて委員","kind":"質問・要望","question":"今回予算は約２,４００万円ということなのですが、終わらないように予算を追加して事業を続けてほしいと思うのですが、いかがでしょうか。他区でも数年間、事業期間が継続するところもありますので、品川区としても１年だけでなくて、継続してもらいたいと思うのですが、いかがか尋ねました。","respondent":"工藤交通安全担当課長","answer":"もし１万人以上の申請があった場合には、状況によっては財政課とご相談をさせていただきながら、取り組んでいきたいと考えております。まだ浸透していないようであれば、それはまた来年度もやらせていただくべく、予算要求等をしていこうかというところでは考えているところです。","id":"exchange-003"},{"speaker":"西本委員","kind":"質問・要望","question":"目標が今の２倍とおっしゃっていたと思いますが、どの数値から２倍なのでしょうかということなのです。なぜ商品券なのですかということなのです。","respondent":"工藤交通安全担当課長","answer":"郵送するという作業を行いますので、その辺の人件費というのは特にかかっておりませんので、商品券でやらせていただければと考えています。","id":"exchange-004"},{"speaker":"西本委員","kind":"質問・要望","question":"それは入ることに意義があるということで、その周知をしっかりやっていただきたいと要望したいと思います。なので、市場の状況を見てからの啓発活動というのも考えていかないといけないのかなと思いますが、その辺はいかがか尋ねました。","respondent":"工藤交通安全担当課長","answer":"なかなかそれを考えていると促進が進まないという面もありますので、その辺も少し考えながらやっていきたいと思います。どういったものが対象になるのか、どういったものが必要なのかというところは、しっかり周知していきたいと考えております。","id":"exchange-005"},{"speaker":"田中委員","kind":"質問・要望","question":"倍としても１万人が増えるということの評価と、予算を上回るような要望があれば、そこはぜひ期待をしていきたいと考えています。どういう受け止めをされるのかというところの観点で伺いたいのですが、区としてはどう評価といいますか、まずそこからお伺いしたいと思います。","respondent":"工藤交通安全担当課長","answer":"売れ筋といたしましては５,０００円前後、５,０００円から七、八千円ぐらいが売れているというお話は伺っているところです。既にヘルメットの購入助成を実施している区が、大体これで、２,０００円の商品券というところで設定をさせていただいた次第であります。","id":"exchange-006"},{"speaker":"田中委員","kind":"質問","question":"他区の事例を参考にされたということで、特段不満の声はなかったということではありますが、今後参考にしていきたいのですけれども、他区で、２,０００円補助したことでどれぐらい着用率がアップしたのかという、そこまでの評価はされていらっしゃるのか尋ねました。","respondent":"工藤交通安全担当課長","answer":"他区の着用率の関係については、他区でそういった調査というのは行っていないというところで把握しておりますので、現状のところは、すみません、分かりません。","id":"exchange-007"},{"speaker":"田中委員","kind":"質問","question":"向上という意味での商品券を活用するという意味合いが少し薄れるのかどうか、その結果として、区内で使える商品券が２,０００円もらえると。まだ商品券を戻す２,０００円に活用するという視点で、そこをもう少し加味していただけるといいのかなと思うのですが、その辺はいかがか尋ねました。","respondent":"工藤交通安全担当課長","answer":"同じように周知していただけるというお話をいただいておりますので、今後とも自転車商とは積極的に連携を図りながらやっていきたいと考えています。やはり物価高騰対策の面では、区内に還元されるというところもあると思いますので、商品券でやらせていただければと考えています。","id":"exchange-008"},{"speaker":"田中委員","kind":"質問・要望","question":"逆に言うと９４％は、１００％につなげていただけるような制度にぜひしてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"渡辺委員","kind":"質問","question":"１点だけ。そこが額でいうと４００万円、何か検討されているのか、情報があれば説明を求めました。","respondent":"工藤交通安全担当課長","answer":"今のところは４００万円上限ということでお話を伺っているのですが、果たして４００万円でいいのかどうかというところの検討はされているということを伺っておりますので、その辺はしっかりと動きを注視していきたいと考えています。","id":"exchange-010"},{"speaker":"渡辺委員","kind":"質問・要望","question":"その辺の抱負と、リーダーシップを東京都へしっかりと要望していくのだというところ、決意もありましたら説明を求めました。","respondent":"工藤交通安全担当課長","answer":"区といたしましても、近年、自転車の事故というのが、少しずつではありますけれども、増えている状況にあります。そういったところが絶対ないように、特に自転車事故の防止については力を入れてやってまいりたいと考えております。","id":"exchange-011"},{"speaker":"若林委員","kind":"意見","question":"冒頭のご説明、また今の質疑の中でも、区内の還元みたいな観点でもありました。物価高騰対策という視点で、まず、この事業をもう少し総合的にお話しほしいと求めました。","respondent":"工藤交通安全担当課長","answer":"区としては少しでも区民の方々の支えになればと思って、やっているところですので、そういったところをご理解いただければと思います。","id":"exchange-012"},{"speaker":"若林委員","kind":"質問・要望","question":"森澤区長に物価高騰対策として緊急要望をさせていただいた中の一項目に、自転車のヘルメットの助成制度ということも直接ご要望させていただきました。早めにセットで広報していただきたいということが、一つ要望として、後で説明を求めました。","respondent":"工藤交通安全担当課長","answer":"現在、鋭意推進中ですけれども、７月の中旬頃を目途に頑張って作業を進めたいと考えています。そういったところでも、やりますよということで区民の皆さんには周知をして、それ以外の媒体も使いながら周知してまいりたいと考えておりま… 決定通知書と商品券、２回の発送になるのではないかというところなのですけれども、１回の発送でできるような方法で考えていきたいと思います。","id":"exchange-013"},{"speaker":"若林委員","kind":"質問・要望","question":"最後に、安全基準がどうしても私は気になるのですが、ここでは具体的に、ＳＧマーク等と書いてあったのです。例えば死亡率が２割、これまで以上に力を入れていただきたいという要望と、以上２点です。","respondent":"工藤交通安全担当課長","answer":"そういったところの検査をやっていると認識をしております。これまでも周知を図ってきておりますけれども、引き続き、より分かりやすいように周知に努めてまいりたいと考えております。","id":"exchange-014"},{"speaker":"若林委員","kind":"意見","question":"例えば２か月後の申請でも、来年の６月３０日までだけれども、加入オーケーですよと。７月末に加入しても、あなたは６月３０日までの１年を切ってしまっているけれども、保険証を発給しますよという工夫ができないのかなとの意見を述べました。","respondent":"工藤交通安全担当課長","answer":"その辺の部分についても、今後、制度の構築という面で検討させていただければと考えています。","id":"exchange-015"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/372951?Template=document&Id=4376#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":17248,"voices":54}}]);
